#!/usr/bin/env bash
# =====================================================================
#  i3 Everforest Installer for Debian 13 (trixie)
# ---------------------------------------------------------------------
#  Reproduces this rice on a clean Debian 13 install, on X11:
#    Theme   : Everforest-Dark-BL-LB  (Fausto-Korpsvart / Everforest)
#    Icons   : Material-Black-Lime-Numix-FLAT
#    Terminal: Alacritty              Bar     : Polybar
#    Launcher: Rofi                   Files   : Nemo/PCManFM
#    Wallpaper: wallhaven.cc/w/4xxw9z
#
#  Usage:
#    sudo ./i3-everforest-installer.sh            # interactive TUI
#    ./i3-everforest-installer.sh --yes           # accept defaults
#    ./i3-everforest-installer.sh --uninstall
#
#  Everything this script creates is recorded in a manifest so that
#  "--uninstall" restores your machine to its previous state.
# =====================================================================

set -Eeuo pipefail
shopt -s nullglob extglob

VERSION="2.0.0"
PROG="i3-everforest"
SELF="$(readlink -f "${BASH_SOURCE[0]}" 2>/dev/null || echo "${BASH_SOURCE[0]}")"

# ---------------------------------------------------------------------
# Paths
# ---------------------------------------------------------------------
SHARE_DIR_NAME="i3-everforest"
THEME_NAME="Everforest-Dark-BL-LB"
ICON_NAME="Material-Black-Lime-Numix-FLAT"
SESSION_FILE="i3-everforest.desktop"

WALLPAPER_URL="https://w.wallhaven.cc/full/4x/wallhaven-4xxw9z.jpg"
THEME_SRC_URL="https://codeload.github.com/Fausto-Korpsvart/Everforest-GTK-Theme/tar.gz/refs/heads/master"
ICON_SRC_URL="https://codeload.github.com/razorhavoc/HTB-pwnbox/tar.gz/refs/heads/master"
ICON_SRC_PATH="usr/share/icons/${ICON_NAME}"

# ---------------------------------------------------------------------
# Everforest palette (used by the TUI itself)
# ---------------------------------------------------------------------
EF_BG0="30;35;38"       # #1e2326
EF_BG1="39;46;51"       # #272e33
EF_BG2="47;51;54"       # #2f3336
EF_FG="211;198;170"     # #d3c6aa
EF_LIME="185;255;102"   # #b9ff66
EF_GREEN="167;192;128"  # #a7c080
EF_BLUE="127;187;179"   # #7fbbb3
EF_YELLOW="219;188;127" # #dbbc7f
EF_RED="230;126;128"    # #e67e80
EF_GREY="122;132;120"   # #7a8478

# ---------------------------------------------------------------------
# Options (defaults)
# ---------------------------------------------------------------------
OPT_YES=0
OPT_UNINSTALL=0
OPT_DRY_RUN=0
OPT_KEEP_PACKAGES=0
OPT_PURGE_EVERYTHING=0
OPT_USER=""
OPT_APT_UPDATE=1
OPT_ASSUME_TUI="auto"

CORE=1        # desktop packages (i3, C bar, kitty, rofi, ...)
APPS=1        # file manager, system monitor, media, power menu, ...
GTK_THEME=1   # Everforest GTK theme + GTK3/GTK4/libadwaita settings
ICONS=1       # Material-Black-Lime-Numix-FLAT icon theme
WALLPAPER=1   # wallpaper
DOTS=1        # i3/bar/kitty/rofi/dunst/i3lock/btop configs
SESSION=1     # xsessions entry (login from a display manager)
SHELLFX=1     # "mf" fetch script + Everforest bash prompt
SDDM=1        # SDDM display manager + SilentSDDM theme (X11 session)

# Polybar transparency: solid (opaque), soft, clear. Applied to the panel and
# the pills together so the bar reads as one material.
BAR_OPACITY="solid"
OPT_OPACITY_GIVEN=""   # set when --opacity is passed explicitly

TARGET_USER=""
TARGET_GROUP=""
HOME_DIR=""
STATE_DIR=""
BACKUP_DIR=""
MANIFEST=""
TMPWORK=""
LOG_FILE=""
SPIN_PID=""
ASSET_DIR=""
SCRIPT_ASSET_DIR=""

# Runtime
INTERACTIVE=0
TUI_LINES=24
TUI_COLS=80

# ---------------------------------------------------------------------
# Terminal / colour helpers
# ---------------------------------------------------------------------
setup_colors() {
	if [[ -n "${NO_COLOR:-}" ]] || [[ ! -t 1 ]]; then
		C_RESET="" C_FG="" C_LIME="" C_GREEN="" C_BLUE="" C_YELLOW="" C_RED="" C_GREY="" C_BG="" C_BOLD=""
		return 0
	fi
	C_RESET=$'\033[0m' C_BOLD=$'\033[1m'
	C_FG=$'\033[38;2;'"${EF_FG}"'m'
	C_LIME=$'\033[38;2;'"${EF_LIME}"'m'
	C_GREEN=$'\033[38;2;'"${EF_GREEN}"'m'
	C_BLUE=$'\033[38;2;'"${EF_BLUE}"'m'
	C_YELLOW=$'\033[38;2;'"${EF_YELLOW}"'m'
	C_RED=$'\033[38;2;'"${EF_RED}"'m'
	C_GREY=$'\033[38;2;'"${EF_GREY}"'m'
	C_BG=$'\033[48;2;'"${EF_BG1}"'m'
}

ui_clear() { [[ ${INTERACTIVE} -eq 1 ]] && printf '\033[H\033[2J'; }

ui_hdr() {
	printf '\n%s%s  %s%s\n' "${C_BOLD}" "${C_LIME}" "$*" "${C_RESET}"
	printf '%s  %s%s\n' "${C_GREY}" "────────────────────────────────────────────────────────────" "${C_RESET}"
}

ui_line() { printf '  %s\n' "$*"; }
ui_dim()  { printf '  %s%s%s\n' "${C_GREY}" "$*" "${C_RESET}"; }
ui_step() { printf '  %s❯%s %s\n' "${C_BLUE}" "${C_RESET}" "$*"; }
ui_ok()   { printf '  %s✔%s %s\n' "${C_GREEN}" "${C_RESET}" "$*"; }
ui_warn() { printf '  %s!%s %s\n' "${C_YELLOW}" "${C_RESET}" "$*"; }
ui_err()  { printf '  %s✘%s %s\n' "${C_RED}" "${C_RESET}" "$*" >&2; }
ui_rule() { printf '  %s%s%s\n' "${C_GREY}" "────────────────────────────────────────────────────────────" "${C_RESET}"; }

die() {
	ui_err "$*"
	if [[ -n "${LOG_FILE}" && -s "${LOG_FILE}" ]]; then
		printf '\n'; ui_dim "Last 20 log lines (${LOG_FILE}):"
		tail -n 20 "${LOG_FILE}" | sed 's/^/    /'
	fi
	exit 1
}

cleanup() {
	if [[ -n "${SPIN_PID}" ]] && kill -0 "${SPIN_PID}" 2>/dev/null; then
		kill "${SPIN_PID}" 2>/dev/null || true
		wait "${SPIN_PID}" 2>/dev/null || true
	fi
	if [[ -n "${TMPWORK}" && -d "${TMPWORK}" && -z "${KEEP_TMP:-}" ]]; then
		rm -rf "${TMPWORK}" 2>/dev/null || true
	fi
	# restore the cursor only if the TUI actually hid it
	if [[ ${INTERACTIVE:-0} -eq 1 && -t 1 ]]; then
		printf '\033[?25h' 2>/dev/null || true
	fi
}
trap cleanup EXIT
trap 'die "unexpected failure at line ${LINENO}"' ERR

# ---------------------------------------------------------------------
# Small utilities
# ---------------------------------------------------------------------
have() { command -v "$1" >/dev/null 2>&1; }

# display_reachable - is there an X server behind $DISPLAY that answers?
#
# DISPLAY being set proves nothing: under sudo, ssh or inside a chroot it
# routinely points at a socket the current user cannot open, and every tool
# that needs real X then fails for a reason that has nothing to do with the
# configuration. Anything X-dependent asks this first.
display_reachable() {
	[[ -n "${DISPLAY:-}" ]] || return 1
	if have xdpyinfo; then
		xdpyinfo >/dev/null 2>&1 && return 0
		return 1
	fi
	if have xset; then
		xset q >/dev/null 2>&1 && return 0
		return 1
	fi
	# Without a probe tool, fall back to the socket the display names.
	local n="${DISPLAY#*:}"
	n="${n%%.*}"
	[[ -S "/tmp/.X11-unix/X${n}" ]] && return 0
	return 1
}

mul() { # print n copies of a character
	local n="$1" ch="$2" out="" i
	for ((i = 0; i < n; i++)); do out+="${ch}"; done
	printf '%s' "${out}"
}

pkg_installed() { dpkg-query -W -f='${Status}' "$1" 2>/dev/null | grep -q "ok installed"; }

apt_cleanup_name() { printf '%s' "${1%%:*}"; }

# ---------------------------------------------------------------------
# 20-tui.sh
# ---------------------------------------------------------------------
# =====================================================================
#  TUI - pure bash, English, line-based so it works everywhere
# ---------------------------------------------------------------------
#  The menu is deliberately line-oriented: the user types a number to
#  toggle a component and presses Enter. This works identically in a
#  console, in a terminal emulator, over SSH, under sudo, and when stdin
#  comes from a pipe - none of which hold true for raw single-key input.
# =====================================================================

tui_detect() {
	if [[ "${OPT_YES}" -eq 1 ]]; then INTERACTIVE=0; return; fi
	if [[ "${OPT_ASSUME_TUI}" == "off" ]]; then INTERACTIVE=0; return; fi
	if [[ -t 0 && -t 1 ]]; then INTERACTIVE=1; else INTERACTIVE=0; fi
}

tui_size() {
	if [[ -t 1 ]]; then
		TUI_COLS="$(tput cols 2>/dev/null || echo 80)"
	else
		TUI_COLS=80
	fi
	if ((TUI_COLS < 72)); then TUI_COLS=72; fi
}

tui_hline() {
	local ch="$1" n="$2" out="" i
	for ((i = 0; i < n; i++)); do out+="${ch}"; done
	printf '%s' "${out}"
}

tui_w() {
	local w=$((TUI_COLS - 4))
	if ((w > 88)); then w=88; fi
	printf '%s' "${w}"
}

opt_short() {
	case "$1" in
	core) printf 'Desktop core    i3, C bar, foot, rofi, dunst, feh' ;;
	apps) printf 'Everyday apps   pcmanfm, btop, pavucontrol, flameshot, imv, nomacs, mpv' ;;
	theme) printf 'GTK theme       Everforest-Dark-BL-LB (+ libadwaita override)' ;;
	icons) printf 'Icon theme      Material-Black-Lime-Numix-FLAT' ;;
	wall) printf 'Wallpaper       wallhaven 4xxw9z, 1920x1080' ;;
	dots) printf 'Dotfiles        i3, C bar, foot, rofi, dunst, i3lock' ;;
	session) printf 'Login session   xsessions entry for i3' ;;
	shell) printf 'Shell extras    mf fetch block + Everforest bash prompt' ;;
	sddm) printf 'SDDM greeter    display manager + SilentSDDM theme' ;;
	esac
}

opt_desc() {
	case "$1" in
	core) printf 'Required. X11 window manager, bar, terminal, launcher, notifications.' ;;
	apps) printf 'The applications wired to the keybindings and the bar.' ;;
	theme) printf 'GTK2/3/4 theme plus gtk-3.0, gtk-4.0 and libadwaita settings.' ;;
	icons) printf 'The lime folders and black application glyphs from the screenshot.' ;;
	wall) printf 'The exact wallpaper from the original post.' ;;
	dots) printf 'All configuration files; existing ones are backed up first.' ;;
	session) printf "Adds 'i3 (Everforest)' to lightdm / gdm3 / sddm / greetd." ;;
	shell) printf 'The two-column fetch block shown in the terminal screenshot.' ;;
	sddm) printf 'Boots to a graphical login; pick the i3 session there.' ;;
	esac
}

opt_state() {
	local v
	case "$1" in
	core) v=$CORE ;; apps) v=$APPS ;; theme) v=$GTK_THEME ;; icons) v=$ICONS ;;
	wall) v=$WALLPAPER ;; dots) v=$DOTS ;; session) v=$SESSION ;; shell) v=$SHELLFX ;;
	sddm) v=$SDDM ;;
	*) v=0 ;;
	esac
	if [[ "${v}" -eq 1 ]]; then printf 'x'; else printf ' '; fi
}

OPT_KEYS=(core apps theme icons wall dots session sddm shell)
TUI_DONE=0

selected_count() {
	local k n=0
	for k in "${OPT_KEYS[@]}"; do
		if [[ "$(opt_state "${k}")" == "x" ]]; then n=$((n + 1)); fi
	done
	printf '%s' "${n}"
}

tui_toggle() {
	case "$1" in
	core) if [[ ${CORE} -eq 1 ]]; then CORE=0; else CORE=1; fi ;;
	apps) if [[ ${APPS} -eq 1 ]]; then APPS=0; else APPS=1; fi ;;
	theme) if [[ ${GTK_THEME} -eq 1 ]]; then GTK_THEME=0; else GTK_THEME=1; fi ;;
	icons) if [[ ${ICONS} -eq 1 ]]; then ICONS=0; else ICONS=1; fi ;;
	wall) if [[ ${WALLPAPER} -eq 1 ]]; then WALLPAPER=0; else WALLPAPER=1; fi ;;
	dots) if [[ ${DOTS} -eq 1 ]]; then DOTS=0; else DOTS=1; fi ;;
	session) if [[ ${SESSION} -eq 1 ]]; then SESSION=0; else SESSION=1; fi ;;
	shell) if [[ ${SHELLFX} -eq 1 ]]; then SHELLFX=0; else SHELLFX=1; fi ;;
	sddm) if [[ ${SDDM} -eq 1 ]]; then SDDM=0; else SDDM=1; fi ;;
	esac
}

tui_render() {
	local w inner i k mark flag banner
	w="$(tui_w)"; inner=$((w - 2))
	ui_clear
	printf '\n'
	printf '%s╭%s╮%s\n' "${C_LIME}" "$(tui_hline '─' "${inner}")" "${C_RESET}"
	printf '%s│%s%-*s%s│%s\n' "${C_LIME}" "${C_RESET}${C_BOLD}${C_FG}" "${inner}" \
		"  i3 Everforest · Debian 13 installer · v${VERSION}" "${C_LIME}" "${C_RESET}"
	printf '%s│%s%-*s%s│%s\n' "${C_LIME}" "${C_RESET}${C_GREY}" "${inner}" \
		"  ${THEME_NAME}  ·  ${ICON_NAME}" "${C_LIME}" "${C_RESET}"
	printf '%s╰%s╯%s\n' "${C_LIME}" "$(tui_hline '─' "${inner}")" "${C_RESET}"
	printf '\n'

	for i in "${!OPT_KEYS[@]}"; do
		k="${OPT_KEYS[$i]}"
		mark="$(opt_state "${k}")"
		printf '  %s[%s]%s %s%-6s%s %s\n' \
			"${C_GREEN}" "${mark}" "${C_RESET}" "${C_BOLD}" "$((i + 1))" "${C_RESET}" \
			"$(opt_short "${k}")"
		printf '       %s%s%s\n' "${C_GREY}" "$(opt_desc "${k}")" "${C_RESET}"
	done

	printf '\n  %s%s%s\n' "${C_GREY}" "$(tui_hline '─' 68)" "${C_RESET}"
	printf '  %sselected:%s %s/%s' "${C_GREY}" "${C_RESET}" "$(selected_count)" "${#OPT_KEYS[@]}"
	if [[ -n "${OPT_USER:-}" ]]; then
		printf '    %starget user:%s %s' "${C_GREY}" "${C_RESET}" "${OPT_USER}"
	fi
	printf '\n'
	printf '  %sbar opacity:%s %s   %s(o cycles solid/soft/clear)%s\n' \
		"${C_GREY}" "${C_RESET}" "${C_LIME}${BAR_OPACITY}${C_RESET}" "${C_GREY}" "${C_RESET}"
	printf '\n'
	# Build the hint row from labelled keys: hand-counting printf arguments is
	# how the line ended up printed twice (printf reuses its format when the
	# argument list runs out).
	local -a hints=( "1-9:toggle" "a:all" "n:none" "o:opacity" "i:install" "q:quit" )
	local hint="" pair k d
	for pair in "${hints[@]}"; do
		k="${pair%%:*}"
		d="${pair#*:}"
		hint+="${C_BOLD}${C_LIME}${k}${C_RESET} ${d}    "
	done
	printf '  %s\n' "${hint%    }"
	printf '\n  %s>%s ' "${C_LIME}" "${C_RESET}"
}

# ---------------------------------------------------------------------
#  Action menu - the very first thing an interactive run shows
# ---------------------------------------------------------------------
#  Three mutually exclusive intents. "Install" continues into the component
#  picker; "Reinstall" resets every component to selected first so a previous
#  partial run does not silently skip things; "Uninstall" hands over to the
#  removal path. Keeping this separate from the component menu avoids
#  accidentally reinstalling when the user meant to remove.
TUI_ACTION=""

tui_action_render() {
	local w; w="$(tui_w)"
	printf '
'
	printf '  %s%s%s
' "${C_LIME}" "$(tui_hline '─' "${w}")" "${C_RESET}"
	printf '  %si3 Everforest%s %s· Debian 13 installer · v%s%s
' \
		"${C_BOLD}" "${C_RESET}" "${C_GREY}" "${VERSION}" "${C_RESET}"
	printf '  %s%s%s
' "${C_LIME}" "$(tui_hline '─' "${w}")" "${C_RESET}"
	printf '
'

	if [[ -d "${STATE_DIR}" && -f "${STATE_DIR}/manifest.list" ]]; then
		printf '  %sAn existing installation was found:%s
' "${C_YELLOW}" "${C_RESET}"
		printf '    %s%s%s
' "${C_GREY}" "${STATE_DIR}" "${C_RESET}"
	else
		printf '  %sNo previous installation found.%s
' "${C_GREY}" "${C_RESET}"
	fi
	printf '
'
	printf '  %s1%s  Install      %sinstall the components you pick%s
' \
		"${C_BOLD}${C_LIME}" "${C_RESET}" "${C_GREY}" "${C_RESET}"
	printf '  %s2%s  Reinstall    %sre-select everything and install again%s
' \
		"${C_BOLD}${C_LIME}" "${C_RESET}" "${C_GREY}" "${C_RESET}"
	printf '  %s3%s  Uninstall    %sremove everything this script installed%s
' \
		"${C_BOLD}${C_LIME}" "${C_RESET}" "${C_GREY}" "${C_RESET}"
	printf '
'
	printf '  %s1-3 select    q quit%s
' "${C_GREY}" "${C_RESET}"
	printf '
  %s>%s ' "${C_LIME}" "${C_RESET}"
}

tui_action_menu() {
	local input
	while true; do
		tui_action_render
		input=""
		IFS= read -r input || { printf '\n'; die "standard input closed"; }
		input="${input//[[:space:]]/}"
		case "${input}" in
		1|i|I|install|c|C|continue)
			TUI_ACTION="install"
			return 0
			;;
		2|r|R|reinstall)
			TUI_ACTION="reinstall"
			return 0
			;;
		3|u|U|uninstall|remove)
			TUI_ACTION="uninstall"
			return 0
			;;
		q|Q|quit|exit)
			printf '\n'
			ui_dim "cancelled by user"
			exit 0
			;;
		'')
			continue
			;;
		*)
			printf '\n  %sUnknown choice: %s%s\n' "${C_RED}" "${input}" "${C_RESET}"
			sleep 1
			;;
		esac
	done
}

tui_menu() {
	local input
	while true; do
		tui_render
		input=""
		IFS= read -r input || { printf '\n'; die "standard input closed"; }
		input="${input//[[:space:]]/}"
		if [[ -z "${input}" ]]; then continue; fi

		case "${input}" in
		i|I|install|y|Y|yes|go|ok)
			if [[ "$(selected_count)" -gt 0 ]]; then TUI_DONE=1; return 0; fi
			printf '\n  %sNothing selected.%s\n' "${C_RED}" "${C_RESET}"
			sleep 1
			;;
		q|Q|quit|exit|n|no)
			printf '\n'
			ui_dim "cancelled by user"
			exit 0
			;;
		o|O|opacity)
			case "${BAR_OPACITY}" in
			solid) BAR_OPACITY="soft" ;;
			soft)  BAR_OPACITY="clear" ;;
			*)     BAR_OPACITY="solid" ;;
			esac
			;;
		a|A|all)
			CORE=1 APPS=1 GTK_THEME=1 ICONS=1 WALLPAPER=1 DOTS=1 SESSION=1 SHELLFX=1 SDDM=1
			;;
		none|none!)
			CORE=0 APPS=0 GTK_THEME=0 ICONS=0 WALLPAPER=0 DOTS=0 SESSION=0 SHELLFX=0 SDDM=0
			;;
		*)
			if [[ "${input}" =~ ^[1-9]+$ ]]; then
				local ch idx
				for ((ch = 0; ch < ${#input}; ch++)); do
					idx=$(( ${input:ch:1} - 1 ))
					if ((idx >= 0 && idx < ${#OPT_KEYS[@]})); then
						tui_toggle "${OPT_KEYS[$idx]}"
					fi
				done
			else
				printf '\n  %sUnknown choice: %s%s\n' "${C_RED}" "${input}" "${C_RESET}"
				sleep 1
			fi
			;;
		esac
	done
}

tui_summary() {
	local w inner k row
	w="$(tui_w)"; inner=$((w - 2))
	ui_clear
	printf '\n'
	printf '%s╭%s╮%s\n' "${C_LIME}" "$(tui_hline '─' "${inner}")" "${C_RESET}"
	printf '%s│%s%-*s%s│%s\n' "${C_LIME}" "${C_RESET}${C_BOLD}${C_FG}" "${inner}" \
		"  Ready to install" "${C_LIME}" "${C_RESET}"
	printf '%s├%s┤%s\n' "${C_LIME}" "$(tui_hline '─' "${inner}")" "${C_RESET}"
	for k in "${OPT_KEYS[@]}"; do
		if [[ "$(opt_state "${k}")" == "x" ]]; then
			row="  [x] $(opt_short "${k}")"
			printf '%s│%s%-*s%s│%s\n' "${C_LIME}" "${C_RESET}${C_GREEN}" \
				"${inner}" "${row}" "${C_LIME}" "${C_RESET}"
		fi
	done
	if [[ "$(selected_count)" -eq 0 ]]; then
		printf '%s╰%s╯%s\n' "${C_LIME}" "$(tui_hline '─' "${inner}")" "${C_RESET}"
		ui_err "nothing selected"
		return 1
	fi
	printf '%s├%s┤%s\n' "${C_LIME}" "$(tui_hline '─' "${inner}")" "${C_RESET}"
	row="  user:  ${TARGET_USER}"
	printf '%s│%s%-*s%s│%s\n' "${C_LIME}" "${C_RESET}${C_GREY}" "${inner}" "${row}" "${C_LIME}" "${C_RESET}"
	row="  log:   ${LOG_FILE}"
	printf '%s│%s%-*s%s│%s\n' "${C_LIME}" "${C_RESET}${C_GREY}" "${inner}" "${row}" "${C_LIME}" "${C_RESET}"
	row="  undo:  $(basename "${SELF}") --uninstall"
	printf '%s│%s%-*s%s│%s\n' "${C_LIME}" "${C_RESET}${C_GREY}" "${inner}" "${row}" "${C_LIME}" "${C_RESET}"
	row="  bar transparency: ${BAR_OPACITY}  (change with --opacity soft|clear)"
	printf '%s│%s%-*s%s│%s\n' "${C_LIME}" "${C_RESET}${C_GREY}" "${inner}" "${row}" "${C_LIME}" "${C_RESET}"
	local extra=""
	[[ ${SOFT_ZENNB:-0} -eq 1 ]] && extra+="zen "
	[[ ${SOFT_VLC:-0} -eq 1 ]] && extra+="vlc "
	[[ ${SOFT_OBS:-0} -eq 1 ]] && extra+="obs "
	[[ ${SOFT_FCITX:-0} -eq 1 ]] && extra+="fcitx5 "
	row="  extra software: ${extra:-none}"
	printf '%s│%s%-*s%s│%s\n' "${C_LIME}" "${C_RESET}${C_GREY}" "${inner}" "${row}" "${C_LIME}" "${C_RESET}"
	printf '%s╰%s╯%s\n' "${C_LIME}" "$(tui_hline '─' "${inner}")" "${C_RESET}"
	printf '\n  %sProceed? [Y/n]%s ' "${C_FG}" "${C_RESET}"

	local ans=""
	IFS= read -r ans || ans=""
	if [[ "${ans}" =~ ^[nN] ]]; then return 1; fi
	return 0
}

# ---------------------------------------------------------------------
#  Third page: extra software
# ---------------------------------------------------------------------
#  OPT keys for the optional applications. Each entry is "key|label|hint".
OPT_SOFT_KEYS=( zennb vlc obs fcitx )
SOFT_ZENNB=0
SOFT_VLC=0
SOFT_OBS=0
SOFT_FCITX=0

soft_state() {
	case "$1" in
	zennb) [[ ${SOFT_ZENNB} -eq 1 ]] && printf 'x' || printf ' ' ;;
	vlc)   [[ ${SOFT_VLC} -eq 1 ]] && printf 'x' || printf ' ' ;;
	obs)   [[ ${SOFT_OBS} -eq 1 ]] && printf 'x' || printf ' ' ;;
	fcitx) [[ ${SOFT_FCITX} -eq 1 ]] && printf 'x' || printf ' ' ;;
	esac
}

soft_set() {
	local v="$2"
	case "$1" in
	zennb) SOFT_ZENNB=${v} ;;
	vlc)   SOFT_VLC=${v} ;;
	obs)   SOFT_OBS=${v} ;;
	fcitx) SOFT_FCITX=${v} ;;
	esac
}

soft_short() {
	case "$1" in
	zennb) printf 'Zen Browser    private, Firefox-based (official installer)' ;;
	vlc)   printf 'VLC            media player' ;;
	obs)   printf 'OBS Studio     screen recording and streaming' ;;
	fcitx) printf 'fcitx5         Chinese pinyin input method' ;;
	esac
}

soft_desc() {
	case "$1" in
	zennb) printf 'Official installer: curl -fsSL https://updates.zen-browser.app/install.sh | bash' ;;
	vlc)   printf 'Plays almost every audio and video format.' ;;
	obs)   printf 'X11 capture; records the screen through the X composite extension.' ;;
	fcitx) printf 'Includes fcitx5-chinese-addons (pinyin) and the Qt/GTK modules.' ;;
	esac
}

soft_count() {
	local n=0 k
	for k in "${OPT_SOFT_KEYS[@]}"; do
		[[ "$(soft_state "${k}")" == "x" ]] && n=$((n + 1))
	done
	printf '%s' "${n}"
}

tui_soft_render() {
	local w inner i k mark
	w="$(tui_w)"; inner=$((w - 2))
	ui_clear
	printf '\n'
	printf '%s╭%s╮%s\n' "${C_LIME}" "$(tui_hline '─' "${inner}")" "${C_RESET}"
	printf '%s│%s%-*s%s│%s\n' "${C_LIME}" "${C_RESET}${C_BOLD}${C_FG}" "${inner}" \
		"  Optional software" "${C_LIME}" "${C_RESET}"
	printf '%s│%s%-*s%s│%s\n' "${C_LIME}" "${C_RESET}${C_GREY}" "${inner}" \
		"  Nothing here is required; press Enter to keep the defaults" "${C_LIME}" "${C_RESET}"
	printf '%s╰%s╯%s\n' "${C_LIME}" "$(tui_hline '─' "${inner}")" "${C_RESET}"
	printf '\n'

	for i in "${!OPT_SOFT_KEYS[@]}"; do
		k="${OPT_SOFT_KEYS[$i]}"
		mark="$(soft_state "${k}")"
		printf '  %s[%s]%s %s%-6s%s %s\n' \
			"${C_GREEN}" "${mark}" "${C_RESET}" "${C_BOLD}" "$((i + 1))" "${C_RESET}" \
			"$(soft_short "${k}")"
		printf '       %s%s%s\n' "${C_GREY}" "$(soft_desc "${k}")" "${C_RESET}"
	done

	printf '\n  %s%s%s\n' "${C_GREY}" "$(tui_hline '─' 68)" "${C_RESET}"
	printf '  %sselected:%s %s/%s\n' "${C_GREY}" "${C_RESET}" "$(soft_count)" "${#OPT_SOFT_KEYS[@]}"
	printf '\n'
	local -a hints=( "1-4:toggle" "a:all" "n:none" "Enter:continue" "b:back" )
	local hint="" pair keyk desc
	for pair in "${hints[@]}"; do
		keyk="${pair%%:*}"; desc="${pair#*:}"
		hint+="${C_BOLD}${C_LIME}${keyk}${C_RESET} ${desc}    "
	done
	printf '  %s\n' "${hint%    }"
	printf '\n  %s>%s ' "${C_LIME}" "${C_RESET}"
}

tui_soft_menu() {
	local input
	while true; do
		tui_soft_render
		input=""
		IFS= read -r input || { printf '\n'; return 0; }
		input="${input//[[:space:]]/}"
		case "${input}" in
		"")
			return 0
			;;
		b|B|back)
			return 2
			;;
		a|A|all)
			SOFT_ZENNB=1; SOFT_VLC=1; SOFT_OBS=1; SOFT_FCITX=1
			;;
		n|N|none)
			SOFT_ZENNB=0; SOFT_VLC=0; SOFT_OBS=0; SOFT_FCITX=0
			;;
		*)
			if [[ "${input}" =~ ^[1-4]+$ ]]; then
				local ch idx
				for ((ch = 0; ch < ${#input}; ch++)); do
					idx=$(( ${input:ch:1} - 1 ))
					local key="${OPT_SOFT_KEYS[$idx]}"
					if [[ "$(soft_state "${key}")" == "x" ]]; then
						soft_set "${key}" 0
					else
						soft_set "${key}" 1
					fi
				done
			fi
			;;
		esac
	done
}


# ---------------------------------------------------------------------
# 30-preflight.sh
# ---------------------------------------------------------------------
# =====================================================================
#  Pre-flight checks
# =====================================================================

check_root() {
	[[ "${EUID}" -eq 0 ]] || die "run this installer as root:  sudo $0"
}

check_distro() {
	local id="" ver=""
	if [[ -r /etc/os-release ]]; then
		# shellcheck disable=SC1091
		. /etc/os-release
		id="${ID:-}"; ver="${VERSION_ID:-}"
	fi
	[[ "${id}" == "debian" ]] || die "this installer targets Debian 13 (trixie); detected '${id:-unknown}'"
	case "${ver}" in
	13*) : ;;
	*) ui_warn "Debian ${ver} detected - tested on Debian 13 (trixie) only" ;;
	esac
}

check_arch_packages() {
	# wayland stack is amd64/arm64 only in Debian; refuse on 32-bit
	local arch; arch="$(dpkg --print-architecture)"
	case "${arch}" in
	amd64|arm64) : ;;
	*) die "unsupported architecture '${arch}' (need amd64 or arm64)" ;;
	esac
}

check_systemd() {
	[[ -d /run/systemd/system ]] || ui_warn "systemd not detected; some services will not be enabled"
}

resolve_target_user() {
	if [[ -n "${OPT_USER}" ]]; then
		TARGET_USER="${OPT_USER}"
	elif [[ -n "${SUDO_USER:-}" && "${SUDO_USER}" != "root" ]]; then
		TARGET_USER="${SUDO_USER}"
	elif [[ -n "${PKEXEC_UID:-}" ]]; then
		TARGET_USER="$(getent passwd "${PKEXEC_UID}" | cut -d: -f1)"
	elif [[ -n "${DOAS_USER:-}" ]]; then
		TARGET_USER="${DOAS_USER}"
	else
		TARGET_USER="$(logname 2>/dev/null || true)"
	fi
	if [[ -z "${TARGET_USER}" ]]; then TARGET_USER="${FALLBACK_USER:-builder}"; fi

	if ! id -u "${TARGET_USER}" >/dev/null 2>&1; then
		# fall back to the first normal user
		TARGET_USER="$(awk -F: '($3>=1000 && $3<65000 && $1!="nobody"){print $1; exit}' /etc/passwd)"
	fi
	id -u "${TARGET_USER}" >/dev/null 2>&1 || die "cannot determine the desktop user; re-run with --user <name>"
	if [[ "${TARGET_USER}" == "root" ]]; then die "refusing to install a desktop session for root; use --user <name>"; fi

	TARGET_GROUP="$(id -gn "${TARGET_USER}")"
	HOME_DIR="$(getent passwd "${TARGET_USER}" | cut -d: -f6)"
	if [[ -z "${HOME_DIR}" || ! -d "${HOME_DIR}" ]]; then die "home directory for '${TARGET_USER}' does not exist"; fi

	STATE_DIR="${HOME_DIR}/.local/state/${SHARE_DIR_NAME}"
	BACKUP_DIR="${STATE_DIR}/backups/$(date +%Y%m%d-%H%M%S)"
	MANIFEST="${STATE_DIR}/manifest.list"
	LOG_FILE="${STATE_DIR}/install.log"
}

as_user() {
	# runuser keeps root's environment by default, which would make tools
	# like gsettings write into /root. Re-export the user's XDG paths.
	runuser -u "${TARGET_USER}" -- env \
		HOME="${HOME_DIR}" \
		USER="${TARGET_USER}" \
		LOGNAME="${TARGET_USER}" \
		XDG_CONFIG_HOME="${HOME_DIR}/.config" \
		XDG_DATA_HOME="${HOME_DIR}/.local/share" \
		XDG_STATE_HOME="${HOME_DIR}/.local/state" \
		XDG_CACHE_HOME="${HOME_DIR}/.cache" \
		"$@"
}
chown_user() { chown -R "${TARGET_USER}:${TARGET_GROUP}" "$@"; }

preflight() {
	ui_hdr "Pre-flight checks"
	check_root
	check_distro
	check_arch_packages
	check_systemd
	resolve_target_user
	ui_ok "distribution : Debian $(. /etc/os-release; echo "${VERSION_ID}") ($(dpkg --print-architecture))"
	ui_ok "desktop user : ${TARGET_USER} (${HOME_DIR})"
	ui_ok "state        : ${STATE_DIR}"

	# A dry run must not create the state directory, the log or the manifest.
	if [[ "${OPT_DRY_RUN}" -eq 1 ]]; then
		return 0
	fi

	mkdir -p "${STATE_DIR}/backups"
	touch "${LOG_FILE}"
	chown_user "${STATE_DIR}"
	: > "${MANIFEST}.new"

	# Keep apt usable on a live system while we work.
	export DEBIAN_FRONTEND=noninteractive
	export APT_LISTCHANGES_FRONTEND=none
	export NEEDRESTART_MODE=a
	if [[ -f /etc/needrestart/needrestart.conf ]]; then
		export NEEDRESTART_SUSPEND=1
	fi
}

# ---------------------------------------------------------------------
# Manifest - every change is recorded so --uninstall can undo it
# ---------------------------------------------------------------------
manifest_add() {
	[[ -n "${MANIFEST}" ]] || return 0
	printf '%s\t%s\n' "$1" "$2" >>"${MANIFEST}.new"
}

manifest_pkg() { manifest_add "pkg" "$1"; }
manifest_file() { manifest_add "file" "$1"; }
manifest_dir() { manifest_add "dir" "$1"; }
manifest_backup() { manifest_add "backup" "$1"; }

# Register a file we are about to create/overwrite.
register_file() {
	local path="$1"
	manifest_file "${path}"
	printf '%s\n' "${path}" >>"${STATE_DIR}/installed-files.list"
}

# Back up an existing file/dir before we overwrite it.
# The *first* backup of a path wins: if the installer is run again, later
# runs must not replace the record of what the file looked like before the
# very first install, or uninstall would restore an intermediate state.
backup_path() {
	local path="$1" rel dest map
	[[ -e "${path}" || -L "${path}" ]] || return 0
	map="${STATE_DIR}/backup-map.tsv"
	mkdir -p "${STATE_DIR}"
	[[ -f "${map}" ]] || : >"${map}"

	# already recorded and still present? nothing to do
	if [[ -f "${map}" ]]; then
		local existing
		existing="$(awk -F'\t' -v p="${path}" '$1 == p { print $2; exit }' "${map}")"
		if [[ -n "${existing}" && -e "${existing}" ]]; then
			return 0
		fi
	fi

	rel="${path#/}"
	dest="${BACKUP_DIR}/${rel}"
	mkdir -p "$(dirname "${dest}")"
	cp -a "${path}" "${dest}"
	manifest_backup "${path}"
	printf '%s\t%s\n' "${path}" "${dest}" >>"${map}"
}

# ---------------------------------------------------------------------
# 40-packages.sh
# ---------------------------------------------------------------------
# =====================================================================
#  Packages
# =====================================================================

PKGS_CORE=(
	# X11 session
	i3-wm i3status i3lock xinit x11-xserver-utils x11-utils xserver-xorg
	xserver-xorg-input-libinput xserver-xorg-video-all xserver-xorg-video-fbdev
	xauth dbus-x11 xcape numlockx
	# bar (bundled GTK3 program), terminal, launcher, notifications,
	# wallpaper, idle
	python3-gi gir1.2-gtk-3.0 gir1.2-gdkpixbuf-2.0 gir1.2-pango-1.0
	python3-xlib python3-i3ipc
	rofi dunst feh xwallpaper picom
	# desktop plumbing
	dbus dbus-user-session libpam-systemd polkitd lxpolkit brightnessctl playerctl
	network-manager pipewire wireplumber pulseaudio-utils
	fonts-jetbrains-mono fonts-font-awesome fonts-dejavu-core fonts-noto-color-emoji
	adwaita-icon-theme libglib2.0-bin gsettings-desktop-schemas xdg-user-dirs
	gtk2-engines-murrine gnome-themes-extra librsvg2-common libgtk-3-bin
	xz-utils curl ca-certificates jq unzip tar sudo xdg-utils
	desktop-file-utils
	# bar actions: notify-send for the helpers, cal for the clock popup
	libnotify-bin bsdmainutils
)


# libpam-systemd is only a Recommends of sddm and of systemd-sysv, so
# `apt install --no-install-recommends` silently skips it. Without pam_systemd
# there is no logind session, so /run/user/<uid> is never created and the
# session bus, pulseaudio and every XDG runtime consumer fall back to /tmp:
# the greeter accepts the password and the session comes up half broken.
# It is therefore listed explicitly.
#
# xserver-xorg-video-all is what actually gives X a usable driver (modesetting
# for KMS hardware); the bare `xserver-xorg` metapackage pulls the server but
# leaves the driver choice to whatever happens to be installed.

PKGS_APPS=(
	pcmanfm gvfs gvfs-backends btop fastfetch pavucontrol network-manager-gnome
	imv nomacs mpv flameshot swappy cliphist
	imagemagick
)

# Pills on the bar call these directly; without them a click silently does
# nothing, so they are core rather than optional apps.
# PCManFM delegates archive handling to an external program (it hard-codes
# "ark" rather than using any registered handler) and removable-media eject
# goes through udisks2 + a polkit agent. Without this trio the context menu
# entries exist but do nothing.
PKGS_FILEMANAGER_DEPS=(
	# libfm does not hard-code one archiver: /usr/share/libfm/archivers.list
	# defines file-roller, xarchiver, squeeze, engrampa and ark, and any of them
	# works. xarchiver is chosen because it is the lightest of the five
	# (~1.7 MB, 4 dependencies) and is a GTK app like the rest of the rice -
	# ark would pull in ~33 KDE libraries for the same result.
	xarchiver
	7zip             # 7z support behind xarchiver
	udisks2          # mount/eject removable media
	polkitd          # authorization for those mount operations
	lxpolkit         # polkit authentication agent for the i3 session
	gvfs             # trash, network and mtp volumes
	gvfs-backends
	gvfs-fuse
)

PKGS_BAR_DEPS=(
	pavucontrol    # volume / microphone pill
	rofi           # launcher pill and every menu the helpers open
	network-manager-gnome  # nm-connection-editor, right-click on the network pill
	# The screenshot and colour dropper buttons are bar actions, so their
	# tools belong here and not in the optional apps: with --no-apps the
	# buttons must still work.
	maim           # full-screen and region capture
	slop           # region / single-pixel selection
	xclip          # clipboard for the screenshot and colour helpers
	xdotool        # window activation for the calendar / monitor popups
	xprintidle     # idle time for the lock helper
	xss-lock       # lock on suspend / screensaver
	xinput         # touchpad settings (tap, natural scroll, dwt)
	x11-xkb-utils  # setxkbmap, for Caps Lock -> Ctrl
	i3-wm          # i3-msg drives workspace switching and reloads
	jq             # the bar parses i3's tree to pick the tooltip / layout
	# The bar is a C program built at install time, so it needs headers rather
	# than a Python GTK stack; this replaces ~60 MB of runtime with a 47 KB
	# binary.
	build-essential pkg-config
	libcairo2-dev libpango1.0-dev libx11-dev
)

PKGS_ICONS_FALLBACK=(numix-icon-theme numix-icon-theme-circle)

apt_update_once() {
	if ((APT_UPDATED)); then return 0; fi
	ui_step "refreshing package lists (apt-get update)"
	if ! apt-get update -qq >>"${LOG_FILE}" 2>&1; then
		ui_warn "apt-get update reported an error - continuing with the existing lists"
	fi
	APT_UPDATED=1
}
APT_UPDATED=0

apt_install() {
	# apt_install <group-label> <pkg>...
	local label="$1"; shift
	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then
		local -a missing=()
		local q
		for q in "$@"; do
			[[ -n "${q}" ]] || continue
			pkg_installed "${q}" || missing+=("${q}")
		done
		if [[ ${#missing[@]} -gt 0 ]]; then
			ui_dim "would install ${label}: ${missing[*]}"
		else
			ui_ok "${label}: already installed"
		fi
		return 0
	fi
	local -a want=() need=()
	local p
	for p in "$@"; do
		[[ -z "${p}" ]] && continue
		want+=("${p}")
		pkg_installed "$p" || need+=("${p}")
	done
	# Record every package this script is responsible for, including ones that
	# happened to be installed already: the uninstall step compares the list
	# against preinstalled-packages.txt and only removes what was genuinely
	# absent before. Skipping the recording here is why a re-run on a machine
	# that already had the packages left nothing to uninstall.
	local rec
	for rec in "${want[@]}"; do manifest_pkg "$(apt_cleanup_name "${rec}")"; done

	if [[ ${#need[@]} -eq 0 ]]; then
		ui_ok "${label}: already installed (${#want[@]} packages)"
		return 0
	fi
	ui_step "${label}: installing ${#need[@]} package(s)"
	ui_dim "  ${need[*]}"
	apt_update_once
	if ! apt-get install -y --no-install-recommends -o Dpkg::Options::=--force-confdef \
		-o Dpkg::Options::=--force-confold "${need[@]}" >>"${LOG_FILE}" 2>&1; then
		ui_err "apt could not install: ${need[*]}"
		ui_dim "  see ${LOG_FILE}"
		return 1
	fi
	ui_ok "${label}: done"
}

install_packages() {
	ui_hdr "Packages"
	if [[ ${CORE} -eq 1 ]]; then
		apt_install "core" "${PKGS_CORE[@]}" || die "the core package set is required; aborting"
	fi
	if [[ ${APPS} -eq 1 ]]; then
		# The file manager's extract and eject menu entries need these.
		apt_install "file manager" "${PKGS_FILEMANAGER_DEPS[@]}" || \
			ui_warn "archive and removable-media actions may not work"
		# libfm picks the first entry in archivers.list that is installed, so a
		# pre-existing file-roller/engrampa is fine too. Only warn when nothing
		# can handle an archive at all.
		local archiver_ok=0 a
		for a in file-roller xarchiver engrampa ark squeeze; do
			if command -v "${a}" >/dev/null 2>&1; then archiver_ok=1; break; fi
		done
		if [[ ${archiver_ok} -eq 0 ]]; then
			ui_warn "no archive manager found - extracting from the file manager will not work"
		fi
	fi
	if [[ ${DOTS} -eq 1 ]]; then
		# The bar's pills call these; without them a click does nothing.
		apt_install "bar actions" "${PKGS_BAR_DEPS[@]}" || \
			ui_warn "some bar actions will not work (their programs are missing)"
	fi
	if [[ ${APPS} -eq 1 ]]; then
		apt_install "apps" "${PKGS_APPS[@]}" || ui_warn "some optional apps failed to install (the rice still works)"
	fi
	if [[ ${ICONS} -eq 1 && ${ICON_EMBEDDED:-0} -eq 0 ]]; then
		apt_install "icon fallback" "${PKGS_ICONS_FALLBACK[@]}" || true
	fi
	if [[ ${GTK_THEME} -eq 1 ]]; then
		apt_install "gtk theme deps" gtk2-engines-murrine gnome-themes-extra librsvg2-common libgtk-3-bin || true
	fi
}

# ---------------------------------------------------------------------
#  Optional software (third page of the TUI)
# ---------------------------------------------------------------------
install_optional_software() {
	# fcitx5 may already be installed from an earlier run: wire it into the
	# session even when no optional component is selected this time. Doing this
	# before the "any" short-circuit is what makes that possible.
	if command -v fcitx5 >/dev/null 2>&1 && [[ ${OPT_DRY_RUN} -eq 0 ]]; then
		write_fcitx_env
	fi

	local any=0
	[[ ${SOFT_ZENNB:-0} -eq 1 || ${SOFT_VLC:-0} -eq 1 || ${SOFT_OBS:-0} -eq 1 || ${SOFT_FCITX:-0} -eq 1 ]] && any=1
	[[ ${any} -eq 1 ]] || return 0

	ui_hdr "Optional software"

	if [[ ${SOFT_VLC:-0} -eq 1 ]]; then
		apt_install "vlc" vlc || ui_warn "VLC could not be installed"
	fi
	if [[ ${SOFT_OBS:-0} -eq 1 ]]; then
		apt_install "obs-studio" obs-studio || ui_warn "OBS could not be installed"
	fi
	if [[ ${SOFT_FCITX:-0} -eq 1 ]]; then
		# Chinese pinyin plus the input-method modules GTK and Qt need.
		apt_install "fcitx5" fcitx5 fcitx5-chinese-addons \
			fcitx5-frontend-gtk3 fcitx5-frontend-gtk4 \
			fcitx5-frontend-qt6 fcitx5-config-qt \
			|| ui_warn "fcitx5 could not be installed"
	fi
	# Freshly installed here, so its session wiring has to be written now.
	if [[ ${SOFT_FCITX:-0} -eq 1 && ${OPT_DRY_RUN} -eq 0 ]]; then
		write_fcitx_env
	fi
	if [[ ${SOFT_ZENNB:-0} -eq 1 ]]; then
		install_zen_browser || ui_warn "Zen Browser could not be installed"
	fi
	return 0
}

# GTK/Qt applications only pick fcitx5 up when the IM module is exported.
write_fcitx_env() {
	local dir="${HOME_DIR}/.config/environment.d"
	local fdir="${HOME_DIR}/.config/fcitx5"
	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then
		ui_dim "would configure fcitx5 (im-config, layout order, Ctrl+Space)"
		return 0
	fi

	# 1) Tell the session to use fcitx5. im-config writes ~/.xinputrc, which is
	#    what GTK/Qt and the X11 bridge read on login.
	if command -v im-config >/dev/null 2>&1; then
		as_user im-config -n fcitx5 >/dev/null 2>&1 ||
			ui_warn "im-config could not be set to fcitx5"
	fi

	# 2) Make fcitx5 start with the session. Without an autostart entry it
	#    only ran when something happened to launch it, so a fresh login had no
	#    input method until the user started it by hand. The XDG autostart file
	#    works for both i3 (X11) and sway (Wayland) because both sessions honour
	#    ~/.config/autostart via xdg-autostart.
	local adir="${HOME_DIR}/.config/autostart"
	mkdir -p "${adir}"
	cat >"${adir}/org.fcitx.Fcitx5.desktop" <<'FCAUTO'
[Desktop Entry]
Type=Application
Name=Fcitx 5
Comment=Start the input method with the session
Exec=fcitx5 -d --disable virtualkeyboard,emoji,table,spell,kimpanel,quickphrase,unicode,clipboard,notificationitem,fcitx4frontend,ibusfrontend,wayland,waylandim
Icon=fcitx
Terminal=false
Categories=Utility;
X-GNOME-Autostart-enabled=true
X-GNOME-Autostart-Delay=2
NoDisplay=true
FCAUTO
	register_file "${adir}/org.fcitx.Fcitx5.desktop"
	chown_user "${adir}" 2>/dev/null || true

	# 3) Export the IM modules so every toolkit picks fcitx up.
	mkdir -p "${dir}"
	cat >"${dir}/fcitx5.conf" <<'ENVFILE'
GTK_IM_MODULE=fcitx
QT_IM_MODULE=fcitx
XMODIFIERS=@im=fcitx
SDL_IM_MODULE=fcitx
GLFW_IM_MODULE=ibus
ENVFILE
	register_file "${dir}/fcitx5.conf"
	chown_user "${dir}" 2>/dev/null || true

	# 4) Input method order: English first, Pinyin second. The file must be
	#    self-contained - fcitx5 appends its own [Groups] block on first run, and
	#    a duplicate section means the older one wins.
	mkdir -p "${fdir}"
	cat >"${fdir}/profile" <<'FCPROFILE'
[Groups/0]
Name=Default
Default Layout=us
DefaultIM=keyboard-us

[Groups/0/Items/0]
Name=keyboard-us
Layout=

[Groups/0/Items/1]
Name=pinyin
Layout=

[GroupOrder]
0=Default
FCPROFILE
	register_file "${fdir}/profile"
	chown_user "${fdir}" 2>/dev/null || true

	# 5) Ctrl+Space toggles between the two. Writing the section explicitly
	#    keeps it even when fcitx5 recreates config on first start.
	# A partial [Hotkey] block gets rewritten by fcitx5 on exit, which could
	# lose TriggerKeys; ship the full set. Ctrl+Space cycles the two input
	# methods enabled in `profile` (English / Pinyin).
	# Bindings live in conf/hotkey.conf.
	mkdir -p "${fdir}/conf"
	cat >"${fdir}/conf/hotkey.conf" <<'FCHOTKEY'
[Hotkey]
EnumerateWithTriggerKeys=True
EnumerateForwardKeys=
EnumerateBackwardKeys=
ModifierOnlyKeyTimeout=250
[Hotkey/TriggerKeys]
1=Control+space
2=Zenkaku_Hankaku
3=Hangul
4=Hangul_Hanja
[Hotkey/AltTriggerKeys]
1=Shift_L
[Hotkey/ActivateKeys]
1=Super+space
[Hotkey/DeactivateKeys]
1=Super+space
[Hotkey/TogglePinyin]
1=Super+space
FCHOTKEY
	register_file "${fdir}/conf/hotkey.conf"


	cat >"${fdir}/config" <<'FCCONFIG'
[Hotkey]
TriggerKeys=Control+space
EnumerateWithTriggerKeys=True
EnumerateForwardKeys=
EnumerateBackwardKeys=
ActivateKeys=
DeactivateKeys=
TogglePinyin=Super+space
TogglePinyinFirstCandidate=Shift
PrevPage=minus
NextPage=equal

[Behavior]
ActiveByDefault=False
ShareInputState=No
ShowInputMethodInformation=True
ShowInputMethodInformationWhenFocusIn=False
EnableAddonForAllPrograms=True
FCCONFIG

	# Trim the loaded addon set. fcitx5 loads every installed addon by default;
	# the heavy ones (virtual keyboard, emoji, table IMEs, spell checker) are
	# not needed for Chinese/English typing and cost real memory.
	#
	# Neither ~/.config/fcitx5/config [Addon/*] nor conf/addon.conf has any
	# effect on this build - it logged "Disabled Addons: {}" for both. The
	# supported switch is --disable, carried by the autostart entry.
	FCITX_DISABLE="virtualkeyboard,emoji,table,spell,kimpanel,quickphrase,unicode,clipboard,notificationitem,fcitx4frontend,ibusfrontend,wayland,waylandim"
	register_file "${fdir}/config"
	register_file "${fdir}/config"
	chown_user "${fdir}" 2>/dev/null || true

	# 5) X11 sessions started from a TTY (startx / xinit) do not source
	#    environment.d - only a systemd user session does - so mirror the same
	#    exports into ~/.xprofile, which is what the X session reads.
	local xp="${HOME_DIR}/.xprofile"
	local marker_begin="# >>> i3-everforest fcitx5 >>>"
	local marker_end="# <<< i3-everforest fcitx5 <<<"
	# Rewrite the block whenever its contents changed, not only when it is
	# missing. Wrapping it in fcitx5 is what caused the memory to creep back:
	# a stale "fcitx5 -d" (no --disable) started first, so i3's guarded launch
	# saw the process already running and skipped its --disable flags.
	local block
	block=$(printf '%s\n' \
		"${marker_begin}" \
		'export GTK_IM_MODULE=fcitx' \
		'export QT_IM_MODULE=fcitx' \
		'export XMODIFIERS=@im=fcitx' \
		"fcitx5 -d --disable ${FCITX_DISABLE} >/dev/null 2>&1 &" \
		"${marker_end}")

	local current=""
	if grep -qF "${marker_begin}" "${xp}" 2>/dev/null; then
		current=$(sed -n "/^${marker_begin}$/,/^${marker_end}$/p" "${xp}")
	fi
	if [[ "${current}" != "${block}" ]]; then
		[[ -f "${xp}" ]] && backup_path "${xp}"
		if grep -qF "${marker_begin}" "${xp}" 2>/dev/null; then
			# Replace just the marked block, leaving the rest untouched.
			local tmp
			tmp=$(mktemp)
			awk -v b="${marker_begin}" -v e="${marker_end}" -v repl="${block}" '
				$0 == b { print repl; skip = 1; next }
				$0 == e { skip = 0; next }
				!skip { print }
			' "${xp}" >"${tmp}"
			cat "${tmp}" >"${xp}"
			rm -f "${tmp}"
		else
			printf '%s\n' "${block}" >>"${xp}"
		fi
		register_file "${xp}"
		chown_user "${xp}" 2>/dev/null || true
	fi

	ui_ok "fcitx5 enabled (English + Pinyin, Ctrl+Space to switch)"
	return 0
}

# Zen Browser is installed with the project's own official installer. That
# script is the single source of truth for the layout (it unpacks the release
# under $HOME/.tarball-installations/zen), so it is fetched and executed
# verbatim instead of re-implementing its download/unpack logic here.
#
#   curl -fsSL https://updates.zen-browser.app/install.sh | bash
#
# The installer needs no root: it writes into the target user's home, so it is
# run as that user.
ZEN_INSTALL_URL="https://updates.zen-browser.app/install.sh"

install_zen_browser() {
	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then
		ui_dim "would run: curl -fsSL ${ZEN_INSTALL_URL} | bash"
		return 0
	fi

	ui_step "installing Zen Browser (official installer)"
	local script="${TMPWORK}/zen-install.sh"
	local log="${TMPWORK}/zen-install.log"

	# Fetch first so a network failure is reported as a download problem
	# instead of a half-executed shell pipeline.
	if ! curl -fsSL --max-time 60 --retry 2 \
		"${ZEN_INSTALL_URL}" -o "${script}" >"${log}" 2>&1; then
		ui_warn "could not download the Zen installer"
		ui_dim "install it manually: curl -fsSL ${ZEN_INSTALL_URL} | bash"
		return 1
	fi
	if [[ ! -s "${script}" ]]; then
		ui_warn "the Zen installer came back empty"
		return 1
	fi
	# A piped installer is only worth running when it is actually a shell
	# script; a captive portal or proxy error page is not.
	if ! head -1 "${script}" | grep -q '^#!.*sh'; then
		ui_warn "the Zen installer did not look like a shell script; refusing to run it"
		rm -f "${script}"
		return 1
	fi

	# Run it as the target user: it installs under $HOME and needs no root.
	local rc=0
	as_user bash "${script}" >>"${log}" 2>&1 || rc=$?
	if [[ ${rc} -ne 0 ]]; then
		ui_warn "the Zen installer failed (exit ${rc})"
		sed -n '1,12p' "${log}" 2>/dev/null | sed 's/^/      /' >&2 || true
		rm -f "${script}"
		return 1
	fi
	rm -f "${script}"

	local desk="${HOME_DIR}/.local/share/applications/zen.desktop"
	if [[ ! -f "${desk}" ]]; then
		ui_warn "Zen installed but no desktop entry was created"
		return 1
	fi
	register_file "${desk}"

	# The upstream entry advertises desktop Actions, and a launcher such as
	# rofi turns each Action into its own row - which is why Zen showed up as a
	# menu instead of one icon. Dropping the Actions line leaves a single,
	# plain launcher; the same commands stay reachable from Zen's own menu.
	if grep -q '^Actions=' "${desk}" 2>/dev/null; then
		as_user sed -i '/^Actions=/d' "${desk}" 2>/dev/null ||
			sed -i '/^Actions=/d' "${desk}" 2>/dev/null || true
		# Remove the now-orphaned [Desktop Action ...] groups as well.
		as_user sed -i '/^\[Desktop Action /,/^$/d' "${desk}" 2>/dev/null ||
			sed -i '/^\[Desktop Action /,/^$/d' "${desk}" 2>/dev/null || true
	fi

	# The official installer drops the binary in ~/.local/bin; make sure that
	# directory is on PATH for every session type.
	local prof="${HOME_DIR}/.profile"
	if [[ -f "${prof}" ]] && ! grep -q '\$HOME/.local/bin' "${prof}" 2>/dev/null; then
		backup_path "${prof}"
		{
			printf '\n# Added by the i3 Everforest installer (Zen Browser lives here)\n'
			printf 'case ":$PATH:" in\n'
			printf '  *":$HOME/.local/bin:"*) ;;\n'
			printf '  *) PATH="$HOME/.local/bin:$PATH" ;;\n'
			printf 'esac\nexport PATH\n'
		} >>"${prof}"
		register_file "${prof}"
		chown_user "${prof}" 2>/dev/null || true
	fi

	if command -v update-desktop-database >/dev/null 2>&1; then
		as_user update-desktop-database "${HOME_DIR}/.local/share/applications" >/dev/null 2>&1 ||
			update-desktop-database "${HOME_DIR}/.local/share/applications" >/dev/null 2>&1 || true
	fi

	ui_ok "Zen Browser installed (one launcher entry, no sub-menu)"
	return 0
}

# ---------------------------------------------------------------------
# 50-theme.sh
# ---------------------------------------------------------------------
# =====================================================================
#  GTK theme  (Everforest-Dark-BL-LB)
# ---------------------------------------------------------------------
#  Order of preference:
#    1. the payload bundled in this file (exact palette, no network)
#    2. a local build from the upstream sassc sources
#    3. an already-installed Everforest theme, renamed (last resort)
# =====================================================================

THEME_INSTALLED=0

theme_install_bundled() {
	local src="${ASSET_DIR}/gtk-theme/${THEME_NAME}"
	if [[ -d "${src}/gtk-3.0" ]]; then
		rm -rf "/usr/share/themes/${THEME_NAME}"
		install -d /usr/share/themes
		cp -a "${src}" "/usr/share/themes/${THEME_NAME}"
		ui_ok "theme installed from the bundled payload"
		return 0
	fi
	return 1
}

theme_build_from_source() {
	have sassc || return 1
	local tarball="${TMPWORK}/everforest-gtk.tar.gz" src="${TMPWORK}/everforest-gtk" out="${TMPWORK}/gtk-out"

	if [[ -d "${ASSET_DIR:-}/theme-src/themes" ]]; then
		mkdir -p "${src}"
		cp -a "${ASSET_DIR}/theme-src/." "${src}/"
	else
		ui_step "downloading the theme sources"
		curl -fsSL --retry 2 --retry-delay 2 --connect-timeout 15 \
			-o "${tarball}" "${THEME_SRC_URL}" >>"${LOG_FILE}" 2>&1 || return 1
		tar tzf "${tarball}" >/dev/null 2>&1 || return 1
		mkdir -p "${src}"
		tar xzf "${tarball}" -C "${src}" --strip-components=1 >>"${LOG_FILE}" 2>&1 || return 1
	fi

	mkdir -p "${out}"
	(
		cd "${src}/themes" && ./install.sh -d "${out}" -c dark -t default --tweaks
	) >>"${LOG_FILE}" 2>&1 || return 1

	local built="${out}/Everforest-Dark"
	[[ -d "${built}" ]] || return 1
	rm -rf "/usr/share/themes/${THEME_NAME}"
	cp -a "${built}" "/usr/share/themes/${THEME_NAME}"
	ui_ok "theme compiled from source"
	return 0
}

theme_install_from_archive() {
	ui_warn "falling back to an already-installed Everforest theme (palette may differ)"
	local cand
	for cand in /usr/share/themes/Everforest-Dark /usr/share/themes/Everforest-BL-LB-Dark; do
		[[ -d "${cand}" ]] || continue
		rm -rf "/usr/share/themes/${THEME_NAME}"
		cp -a "${cand}" "/usr/share/themes/${THEME_NAME}"
		ui_ok "copied $(basename "${cand}") into ${THEME_NAME}"
		return 0
	done
	return 1
}

theme_install() {
	ui_hdr "GTK theme"
	local dest="/usr/share/themes/${THEME_NAME}"

	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then
		ui_dim "would install ${dest}"
		return 0
	fi

	if [[ -e "${dest}" ]]; then
		backup_path "${dest}"
		rm -rf "${dest}"
	fi

	if theme_install_bundled || theme_build_from_source || theme_install_from_archive; then
		:
	else
		ui_err "could not obtain the GTK theme"
		return 1
	fi

	# Keep index.theme in sync with the directory name we install to.
	if [[ -f "${dest}/index.theme" ]]; then
		sed -i "s/^Name=.*/Name=${THEME_NAME}/" "${dest}/index.theme"
		sed -i "s/^GtkTheme=.*/GtkTheme=${THEME_NAME}/" "${dest}/index.theme"
		sed -i "s/^MetacityTheme=.*/MetacityTheme=${THEME_NAME}/" "${dest}/index.theme"
		sed -i "s/^IconTheme=.*/IconTheme=${ICON_NAME}/" "${dest}/index.theme"
	fi
	manifest_dir "${dest}"
	THEME_INSTALLED=1
	ui_ok "installed ${dest}"

	# GTK4 / libadwaita: the theme's gtk-4.0 stylesheet must live in the
	# user's config directory for libadwaita applications to see it.
	local g4="${HOME_DIR}/.config/gtk-4.0" f
	if [[ -d "${dest}/gtk-4.0" ]]; then
		mkdir -p "${g4}"
		for f in assets gtk.css gtk-dark.css; do
			if [[ -e "${g4}/${f}" && ! -L "${g4}/${f}" ]]; then
				backup_path "${g4}/${f}"
				rm -rf "${g4}/${f}"
			fi
			ln -sfn "${dest}/gtk-4.0/${f}" "${g4}/${f}"
			register_file "${g4}/${f}"
		done
		chown_user "${g4}"
		ui_ok "libadwaita override linked into ~/.config/gtk-4.0"
	fi
}

gtk_apply_settings() {
	local g3="${HOME_DIR}/.config/gtk-3.0"
	mkdir -p "${g3}"

	local s3="${g3}/settings.ini"
	if [[ -f "${s3}" ]]; then backup_path "${s3}"; fi
	cat >"${s3}" <<EOF
[Settings]
gtk-theme-name=${THEME_NAME}
gtk-icon-theme-name=${ICON_NAME}
gtk-font-name=JetBrains Mono 10
gtk-cursor-theme-name=Adwaita
gtk-cursor-theme-size=24
gtk-application-prefer-dark-theme=1
gtk-menu-images=1
gtk-button-images=1
gtk-enable-event-sounds=1
gtk-enable-input-feedback-sounds=0
gtk-xft-antialias=1
gtk-xft-hinting=1
gtk-xft-hintstyle=hintslight
gtk-xft-rgba=rgb
EOF
	register_file "${s3}"

	local g4dir="${HOME_DIR}/.config/gtk-4.0"
	local s4="${g4dir}/settings.ini"
	mkdir -p "${g4dir}"
	if [[ -f "${s4}" ]]; then backup_path "${s4}"; fi
	cat >"${s4}" <<EOF
[Settings]
gtk-theme-name=${THEME_NAME}
gtk-icon-theme-name=${ICON_NAME}
gtk-font-name=JetBrains Mono 10
gtk-cursor-theme-name=Adwaita
gtk-cursor-theme-size=24
gtk-application-prefer-dark-theme=1
gtk-xft-antialias=1
gtk-xft-hinting=1
gtk-xft-hintstyle=hintslight
gtk-xft-rgba=rgb
EOF
	register_file "${s4}"

	local g2="${HOME_DIR}/.gtkrc-2.0"
	if [[ -f "${g2}" ]]; then backup_path "${g2}"; fi
	cat >"${g2}" <<EOF
# Everforest - generated by ${PROG}
gtk-theme-name="${THEME_NAME}"
gtk-icon-theme-name="${ICON_NAME}"
gtk-font-name="JetBrains Mono 10"
gtk-cursor-theme-name="Adwaita"
gtk-cursor-theme-size=24
gtk-toolbar-style=GTK_TOOLBAR_ICONS
EOF
	register_file "${g2}"

	local themes_dir="${HOME_DIR}/.themes"
	mkdir -p "${themes_dir}"
	if [[ ! -e "${themes_dir}/${THEME_NAME}" ]]; then
		ln -sfn "/usr/share/themes/${THEME_NAME}" "${themes_dir}/${THEME_NAME}"
		register_file "${themes_dir}/${THEME_NAME}"
	fi

	chown_user "${g3}" "${g4dir}" "${g2}" "${themes_dir}"

	# Desktop-wide settings for portal / GNOME-adjacent applications.
	if have gsettings; then
		as_user dbus-run-session -- gsettings set org.gnome.desktop.interface gtk-theme "${THEME_NAME}" 2>/dev/null || true
		as_user dbus-run-session -- gsettings set org.gnome.desktop.interface icon-theme "${ICON_NAME}" 2>/dev/null || true
		as_user dbus-run-session -- gsettings set org.gnome.desktop.interface color-scheme "prefer-dark" 2>/dev/null || true
		as_user dbus-run-session -- gsettings set org.gnome.desktop.interface font-name "JetBrains Mono 10" 2>/dev/null || true
	fi
	ui_ok "GTK settings applied (${THEME_NAME} + ${ICON_NAME})"
}

# ---------------------------------------------------------------------
#  Theme guard
# ---------------------------------------------------------------------
#  Other appearance tools (COSMIC settings ports, GNOME tweaks, desktop
#  environment daemons) rewrite ~/.config/gtk-*/settings.ini when the user
#  flips a light/dark switch, and each of them overwrites gtk-theme-name and
#  sometimes drops gtk-icon-theme-name entirely. That silently breaks the rice
#  until the installer is run again.
#
#  This installs a tiny script plus a systemd user timer that puts the four
#  keys back if they drift, so the desktop self-heals after such a change.
theme_guard_install() {
	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then
		ui_dim "would install the theme guard (restores the theme after light/dark switches)"
		return 0
	fi

	local guard="${HOME_DIR}/.local/bin/i3-everforest-theme-guard"
	mkdir -p "${HOME_DIR}/.local/bin"
	cat >"${guard}" <<'GUARD'
#!/bin/sh
# Put the Everforest theme keys back if another tool overwrote them.
# Usage: i3-everforest-theme-guard [--quiet]
theme="${I3_EVERFOREST_THEME:-__THEME__}"
icons="${I3_EVERFOREST_ICONS:-__ICONS__}"
changed=0

fix_one() {
	dir="$1"
	[ -d "$dir" ] || mkdir -p "$dir" 2>/dev/null || return 0
	f="$dir/settings.ini"
	[ -f "$f" ] || : >"$f"

	cur_theme=$(sed -n 's/^gtk-theme-name=//p' "$f" 2>/dev/null | head -1)
	cur_icon=$(sed -n 's/^gtk-icon-theme-name=//p' "$f" 2>/dev/null | head -1)

	[ "$cur_theme" = "$theme" ] && [ "$cur_icon" = "$icons" ] && return 0

	tmp=$(mktemp) || return 0
	# keep every other key the other tool wrote, replace only ours
	grep -v -e '^gtk-theme-name=' -e '^gtk-icon-theme-name=' "$f" >"$tmp" 2>/dev/null || : >"$tmp"
	case "$(head -1 "$tmp" 2>/dev/null)" in
	'[Settings]') : ;;
	*) sed -i '1i [Settings]' "$tmp" 2>/dev/null || printf '[Settings]\n' | cat - "$tmp" >"$tmp.2" && mv "$tmp.2" "$tmp" ;;
	esac
	printf 'gtk-theme-name=%s\ngtk-icon-theme-name=%s\n' "$theme" "$icons" >>"$tmp"
	mv "$tmp" "$f"
	changed=1
	return 0
}

fix_one "$HOME/.config/gtk-3.0"
fix_one "$HOME/.config/gtk-4.0"

# gsettings is what a running GTK desktop actually follows, and it can drift
# from settings.ini independently (a settings panel may write one but not the
# other). Sync it every run, not only when a file had to be repaired.
if command -v gsettings >/dev/null 2>&1; then
	cur_gt=$(gsettings get org.gnome.desktop.interface gtk-theme 2>/dev/null | tr -d "'")
	cur_ic=$(gsettings get org.gnome.desktop.interface icon-theme 2>/dev/null | tr -d "'")
	[ "$cur_gt" = "$theme" ] || { gsettings set org.gnome.desktop.interface gtk-theme "$theme" 2>/dev/null && changed=1; }
	[ "$cur_ic" = "$icons" ] || { gsettings set org.gnome.desktop.interface icon-theme "$icons" 2>/dev/null && changed=1; }
fi

if [ "$changed" -eq 1 ]; then
	[ "${1:-}" = "--quiet" ] || echo "theme keys restored"
fi
exit 0
GUARD
	sed -i "s|__THEME__|${THEME_NAME}|; s|__ICONS__|${ICON_NAME}|" "${guard}"
	chmod 755 "${guard}"
	register_file "${guard}"

	# Run it on login and every 10 minutes, so a light/dark toggle is undone
	# without the user having to re-run the installer.
	local unit_dir="${HOME_DIR}/.config/systemd/user"
	mkdir -p "${unit_dir}"
	cat >"${unit_dir}/i3-everforest-theme-guard.service" <<EOF
[Unit]
Description=Restore the Everforest theme keys

[Service]
Type=oneshot
ExecStart=${guard} --quiet
EOF
	cat >"${unit_dir}/i3-everforest-theme-guard.timer" <<EOF
[Unit]
Description=Re-apply the Everforest theme keys periodically

[Timer]
OnBootSec=30s
OnUnitActiveSec=10min

[Install]
WantedBy=timers.target
EOF
	register_file "${unit_dir}/i3-everforest-theme-guard.service"
	register_file "${unit_dir}/i3-everforest-theme-guard.timer"
	chown_user "${HOME_DIR}/.local/bin" 2>/dev/null || true
	chown_user "${unit_dir}" 2>/dev/null || true

	# Enable it for the login session when systemd is available.
	if [[ -d /run/systemd/system ]]; then
		as_user systemctl --user daemon-reload >/dev/null 2>&1 || true
		as_user systemctl --user enable --now i3-everforest-theme-guard.timer \
			>/dev/null 2>&1 || ui_dim "enable the theme guard manually: systemctl --user enable --now i3-everforest-theme-guard.timer"
	fi

	# Fix the current state immediately.
	as_user "${guard}" >/dev/null 2>&1 || "${guard}" >/dev/null 2>&1 || true
	ui_ok "theme guard installed (restores the theme after light/dark switches)"
	return 0
}

# ---------------------------------------------------------------------
# 55-icons.sh
# ---------------------------------------------------------------------
# =====================================================================
#  Icon theme  (Material-Black-Lime-Numix-FLAT)
# ---------------------------------------------------------------------
#  1. bundled payload (exact icon set from the screenshot)
#  2. Numix from the Debian archive, recoloured to lime (offline build)
# =====================================================================

icons_install_bundled() {
	local dest="/usr/share/icons/${ICON_NAME}"

	# assets_prepare() already expanded the archives, so prefer the
	# unpacked tree; fall back to the archive for the development layout.
	if [[ -d "${ASSET_DIR}/icons/${ICON_NAME}" ]]; then
		ui_step "installing the bundled icon theme"
		mkdir -p /usr/share/icons
		rm -rf "${dest}"
		cp -a "${ASSET_DIR}/icons/${ICON_NAME}" "${dest}" || return 1
	elif [[ -f "${ASSET_DIR}/icons.tar.xz" ]]; then
		ui_step "extracting the bundled icon theme"
		mkdir -p /usr/share/icons
		rm -rf "${dest}"
		tar -xJf "${ASSET_DIR}/icons.tar.xz" -C /usr/share/icons 2>/dev/null || return 1
	fi

	[[ -d "${dest}" ]] || return 1
	ui_ok "icons installed from the bundled payload"
	return 0
}

icons_build_from_numix() {
	have gtk-update-icon-cache >/dev/null 2>&1 || true
	# make sure Numix exists
	if ! pkg_installed numix-icon-theme; then
		apt_install "numix icons" "${PKGS_ICONS_FALLBACK[@]}" || return 1
	fi

	local src="" cand
	for cand in /usr/share/icons/Numix /usr/share/icons/Numix-Circle; do
		if [[ -d "${cand}" ]]; then src="${cand}"; break; fi
	done
	[[ -n "${src}" ]] || return 1

	local dest="/usr/share/icons/${ICON_NAME}"
	ui_step "generating ${ICON_NAME} from Numix (lime folders, black glyphs)"
	rm -rf "${dest}"
	cp -a "${src}" "${dest}"

	# Recolour the folders: Numix orange -> Everforest lime.
	local f
	while IFS= read -r -d '' f; do
		sed -i \
			-e 's/#ea9036/#b9ff66/Ig' \
			-e 's/#f2bb64/#cdfa8f/Ig' \
			-e 's/#f6c37d/#d7fba4/Ig' \
			-e 's/#e58b32/#a8ef55/Ig' \
			"${f}" 2>/dev/null || true
	done < <(find "${dest}" -name '*.svg' -print0 2>/dev/null)

	# Darken the application glyphs a little so they read as "black".
	while IFS= read -r -d '' f; do
		sed -i -e 's/#ffffff/#1e2326/Ig' -e 's/#f9f9f9/#1e2326/Ig' "${f}" 2>/dev/null || true
	done < <(find "${dest}/48/apps" "${dest}/64/apps" -name '*.svg' -print0 2>/dev/null)

	# Rewrite the identity
	cat >"${dest}/index.theme" <<EOF
[Icon Theme]
Name=${ICON_NAME}
Comment=Numix icons recoloured with the Everforest lime palette
Inherits=gnome,hicolor
Example=folder
Directories=$(find "${dest}" -maxdepth 1 -mindepth 1 -type d -printf '%f\n' | sort -u | paste -sd, -)

EOF
	find "${dest}" -maxdepth 1 -mindepth 1 -type d -printf '%f\n' | sort -u | while read -r d; do
		{
			printf '[%s]\nSize=%s\nContext=%s\nType=Fixed\n\n' \
				"${d}" "${d%%@*}" \
				"$(case "${d}" in
					*/actions) echo Actions ;;
					*/apps) echo Applications ;;
					*/devices) echo Devices ;;
					*/places) echo Places ;;
					*/status) echo Status ;;
					*/categories) echo Categories ;;
					*/mimetypes) echo MimeTypes ;;
					*/emblems) echo Emblems ;;
					*/panel) echo Panel ;;
					*/notifications) echo Notifications ;;
					*) echo Applications ;;
					esac)"
		} >>"${dest}/index.theme"
	done
	ui_ok "generated ${dest}"
	return 0
}

icons_install() {
	ui_hdr "Icon theme"
	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then ui_dim "would install ${ICON_NAME}"; return 0; fi

	local dest="/usr/share/icons/${ICON_NAME}"
	local stamp="${dest}/.i3-everforest-source"

	# The Numix fallback build uses the same theme name as the real icon
	# set, so the name alone cannot tell them apart: record where the
	# installed copy came from. The bundled payload always wins, because
	# it is the exact set from the screenshot.
	local current=""
	if [[ -f "${stamp}" ]]; then current="$(cat "${stamp}" 2>/dev/null)"; fi

	if [[ "${current}" == "payload" && -d "${dest}" ]]; then
		ui_ok "${ICON_NAME} is already installed (bundled set)"
	else
		if [[ -e "${dest}" ]]; then
			backup_path "${dest}"
			rm -rf "${dest}"
		fi
		if icons_install_bundled; then
			printf 'payload\n' >"${dest}/.i3-everforest-source"
			manifest_dir "${dest}"
		elif icons_build_from_numix; then
			printf 'numix-fallback\n' >"${dest}/.i3-everforest-source"
			manifest_dir "${dest}"
		else
			ui_warn "could not install the icon theme; keeping the current icons"
			return 1
		fi
	fi

	# Refresh the caches if the tools are available.
	if have gtk-update-icon-cache; then
		gtk-update-icon-cache -q -t -f "${dest}" 2>/dev/null || true
	fi
	ui_ok "icon theme ready: ${ICON_NAME}"
	return 0
}

# ---------------------------------------------------------------------
#  Icon overrides
# ---------------------------------------------------------------------
#  The reference screenshot shows an amber disc for the home folder and a red
#  bin, while the bundled set draws both in lime/steel. Those two glyphs are
#  replaced inside the installed theme.
#
#  Overlay themes (a user-level theme that Inherits the bundled one) were tried
#  first and rejected: GTK resolves the inherited icon fine, but the sidebar of
#  Nemo/PCManFM picks icons through the theme's own directory list, so a
#  two-directory overlay makes the whole set fall back to Adwaita and the
#  folders turn blue. Overwriting the installed theme keeps every index entry
#  valid and changes exactly the two files we ship.
icons_install_overrides() {
	local src="${ASSET_DIR}/icons/rice-overrides"
	local dest="/usr/share/icons/${ICON_NAME}"

	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then
		ui_dim "would install icon overrides into ${dest}"
		return 0
	fi
	if [[ ! -d "${src}" ]] || [[ ! -d "${dest}" ]]; then
		ui_dim "no icon overrides to install"
		return 0
	fi

	local f base n=0
	for f in "${src}"/*.svg; do
		[[ -f "${f}" ]] || continue
		base="$(basename "${f}")"
		# Write into every pixel size the theme ships, so a request at 24px
		# finds the same artwork as one at 48px.
		for d in "${dest}"/*/places; do
			[[ -d "${d}" ]] || continue
			[[ -f "${d}/${base}" ]] || continue
			cp -f "${f}" "${d}/${base}"
			register_file "${d}/${base}"
			n=$((n + 1))
		done
	done
	# The "-symbolic" names are what a file-manager sidebar asks for. They only
	# exist in scalable/, so they are written there explicitly.
	local sd="${dest}/scalable/places"
	if [[ -d "${sd}" ]]; then
		for f in "${src}"/*-symbolic.svg; do
			[[ -f "${f}" ]] || continue
			cp -f "${f}" "${sd}/$(basename "${f}")"
			register_file "${sd}/$(basename "${f}")"
			n=$((n + 1))
		done
	fi
	# Refresh the icon cache so file managers pick the new artwork up.
	if command -v gtk-update-icon-cache >/dev/null 2>&1; then
		gtk-update-icon-cache -f -t "${dest}" >/dev/null 2>&1 || true
	fi
	ui_ok "accent icons installed (${n} file(s) in ${ICON_NAME})"
	return 0
}

# ---------------------------------------------------------------------
# 57-wallpaper.sh
# ---------------------------------------------------------------------
# =====================================================================
#  Wallpaper
# =====================================================================
WALL_DIR_NAME="${SHARE_DIR_NAME}"

wallpaper_path() { printf '%s/.local/share/%s/wallpaper.jpg' "${HOME_DIR}" "${WALL_DIR_NAME}"; }

wallpaper_install() {
	ui_hdr "Wallpaper"
	local dest_dir="${HOME_DIR}/.local/share/${WALL_DIR_NAME}"
	local dest="${dest_dir}/wallpaper.jpg"

	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then ui_dim "would install ${dest}"; return 0; fi
	mkdir -p "${dest_dir}"

	if [[ -f "${ASSET_DIR}/wallpaper.jpg" ]]; then
		ui_step "copying the bundled wallpaper"
		cp -a "${ASSET_DIR}/wallpaper.jpg" "${dest}"
	elif curl -fsSL --retry 3 --retry-delay 2 --connect-timeout 20 \
		-o "${dest}.part" "${WALLPAPER_URL}" >>"${LOG_FILE}" 2>&1; then
		mv "${dest}.part" "${dest}"
		ui_step "wallpaper downloaded from wallhaven"
	else
		ui_warn "could not fetch the wallpaper; generating an Everforest gradient instead"
		wallpaper_generate "${dest}"
	fi

	# A 1920x1080 JPEG should be at least a few dozen KB.
	if [[ ! -s "${dest}" ]] || [[ "$(stat -c%s "${dest}")" -lt 20000 ]]; then
		wallpaper_generate "${dest}"
	fi

	chown_user "${dest_dir}"
	register_file "${dest}"
	ui_ok "wallpaper: ${dest}"

	# Lock screen background + lightdm greeter (best effort)
	mkdir -p /usr/share/backgrounds
	ln -sfn "${dest}" /usr/share/backgrounds/i3-everforest.jpg
	manifest_file /usr/share/backgrounds/i3-everforest.jpg
}

wallpaper_generate() {
	local dest="$1"
	ui_step "generating a fallback wallpaper"
	if have convert; then
		convert -size 1920x1080 gradient:'#1e2326-#4b5a43' "${dest}" >>"${LOG_FILE}" 2>&1 && return 0
	fi
	# last resort: a 1x1 solid JPEG in the Everforest background colour
	if have convert; then
		convert -size 1920x1080 xc:'#1e2326' "${dest}" >>"${LOG_FILE}" 2>&1 && return 0
	fi
	return 1
}

# =====================================================================
#  Icon font (Nerd Font symbols)
# ---------------------------------------------------------------------
#  The bar and the prompt use Nerd Font glyphs (volume, brightness,
#  colour picker, terminal, notification bell, ...). Debian has no Nerd
#  Font package, and fonts-font-awesome is only 4.7, so the symbols are
#  bundled and installed into the user's font directory.
# =====================================================================
fonts_install() {
	ui_hdr "Icon font"
	local src="${ASSET_DIR}/fonts"
	local dest="${HOME_DIR}/.local/share/fonts"
	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then
		ui_dim "would install the Nerd Font symbols into ${dest}"
		return 0
	fi

	if [[ ! -d "${src}" ]]; then
		ui_warn "the bundled font payload is missing; bar icons may show as boxes"
		return 1
	fi

	mkdir -p "${dest}"
	local f n=0
	for f in "${src}"/*.ttf; do
		[[ -f "${f}" ]] || continue
		if have cmp && cmp -s "${f}" "${dest}/$(basename "${f}")" 2>/dev/null; then
			continue
		fi
		cp -f "${f}" "${dest}/$(basename "${f}")" || continue
		register_file "${dest}/$(basename "${f}")"
		n=$((n + 1))
	done
	chown_user "${dest}"

	if have fc-cache; then
		as_user fc-cache -f "${dest}" >/dev/null 2>&1 || true
	fi

	if ((n > 0)); then
		ui_ok "installed ${n} font file(s) into ${dest}"
	else
		ui_ok "icon font already present"
	fi
	return 0
}

# ---------------------------------------------------------------------
# 60-dotfiles.sh
# ---------------------------------------------------------------------
# =====================================================================
#  Dotfiles: i3, the GTK bar, st, rofi, dunst, i3lock, btop
# ---------------------------------------------------------------------
#  Every file is written through install_user_file(), which backs up a
#  previous file and records it in the manifest for --uninstall.
#
#  This is an X11 desktop: the window manager is i3, the bar is a GTK3
#  program that draws the Waybar stylesheet, and the launcher is rofi. The
#  visual language (colours, geometry, keybindings)
#  is unchanged from the Wayland original.
# =====================================================================

install_user_file() {
	# install_user_file <abs-path> <mode>  (content on stdin)
	local path="$1" mode="${2:-644}"
	local tmp; tmp="$(mktemp)"
	cat >"${tmp}"          # read stdin exactly once
	if [[ -e "${path}" ]] && cmp -s "${tmp}" "${path}"; then
		rm -f "${tmp}"
		ui_dim "unchanged: ${path}"
		return 0
	fi
	mkdir -p "$(dirname "${path}")"
	if [[ -e "${path}" || -L "${path}" ]]; then
		backup_path "${path}"
	fi
	install -m "${mode}" "${tmp}" "${path}"
	rm -f "${tmp}"
	register_file "${path}"
	ui_ok "wrote ${path}"
}

write_i3() {
	local dir="${HOME_DIR}/.config/i3"
	local cfg="${dir}/config"
	local tmp; tmp="$(mktemp)"
	sed "s|@HOME@|${HOME_DIR}|g" >"${tmp}" <<'I3CONF'
### i3 - Everforest  (generated by i3-everforest installer)
#
# Modifier: Super. This is the same layout the reference rice uses, ported
# from sway to i3 on X11: identical keybindings, identical colours.
set $mod Mod4
# The rice's terminal is foot, which is Wayland-only. kitty replaces it with
# foot.ini's font, padding, 60% alpha, palette and cursor ported over, so the
# terminal looks the same. See write_kitty().
set $term st
set $menu rofi -show drun -theme i3-everforest
set $files pcmanfm ~
set $shot i3-everforest-shot
set $wall @HOME@/.local/share/i3-everforest/wallpaper.jpg

### Input
# The sway version configures these through `input` blocks. X11 has no such
# directive, so i3-everforest-input applies the same settings with xinput and
# setxkbmap at session start:
#   touchpad: tap to click, natural scrolling, disable-while-typing
#   keyboard: Caps Lock mapped to Ctrl (xkb option ctrl:nocaps)
exec --no-startup-id i3-everforest-input

### Look: pixel borders in Everforest lime, 8px gaps
# i3 has no "gaps" of its own; smart_gaps/smart_borders are emulated by
# i3-gaps which is merged into i3 4.22+, so both are native here.
default_border pixel 1
default_floating_border pixel 1
gaps inner 8
# Top gap equal to the bar strip, so tiled windows never sit under it.
gaps outer 8
smart_gaps on
# sway's `smart_borders off` means "always draw the outline". i3 has no `off`
# keyword (it would fail to parse) and both `on` and `no_gaps` hide the border
# in common tiling cases, so smart_borders is simply left disabled - which is
# exactly "always draw it".
# smart_borders off
hide_edge_borders smart
font pango:JetBrains Mono 10

# A thin yellow outline on every window, matching the reference: i3 keeps one
# border palette for the whole session, so per-window colours are not
# possible. client.focused_inactive/unfocused carry the *title bar* colours,
# which are invisible with pixel borders but still drive tabbed mode.
#   client.focused          <border> <background> <text> <indicator> <child_border>
client.focused          #ffe066 #1e2326 #d3c6aa #ffe066 #ffe066
client.focused_inactive #ffe066 #1e2326 #d3c6aa #2f3336 #ffe066
client.unfocused        #ffe066 #1e2326 #d3c6aa #1e2326 #ffe066
client.urgent           #e67e80 #1e2326 #d3c6aa #e67e80 #e67e80

### Essentials
bindsym $mod+Return exec $term
bindsym $mod+d exec $menu
bindsym $mod+Shift+Return exec $term -e btop
bindsym $mod+e exec $files
bindsym $mod+q kill
bindsym $mod+Shift+c reload
bindsym $mod+Shift+e exec i3-everforest-powermenu
# Mod+Shift+X is the secondary, mnemonic-free binding for the same menu; the
# reference only has Mod+Shift+E, so both do exactly the same thing.
bindsym $mod+Shift+q exec i3-nagbar -t warning -m 'Exit i3?' -B 'Yes, exit i3' 'i3-msg exit'

### Screenshots
# Same three bindings as the sway config:
#   Print              full screen -> clipboard
#   $mod+Print         drag a region -> clipboard
#   $mod+Shift+Print   drag a region -> clipboard, then open it in swappy
bindsym Print exec $shot clip
bindsym $mod+Print exec $shot region-clip
bindsym $mod+Shift+Print exec $shot region-swappy

### Media / brightness keys
bindsym XF86AudioRaiseVolume exec pactl set-sink-volume @DEFAULT_SINK@ +5%
bindsym XF86AudioLowerVolume exec pactl set-sink-volume @DEFAULT_SINK@ -5%
bindsym XF86AudioMute exec pactl set-sink-mute @DEFAULT_SINK@ toggle
bindsym XF86AudioMicMute exec pactl set-source-mute @DEFAULT_SOURCE@ toggle
bindsym XF86AudioPlay exec playerctl play-pause
bindsym XF86AudioNext exec playerctl next
bindsym XF86AudioPrev exec playerctl previous
bindsym XF86MonBrightnessUp exec brightnessctl set 5%+
bindsym XF86MonBrightnessDown exec brightnessctl set 5%-
bindsym $mod+Escape exec i3-everforest-lock

### Focus / move
bindsym $mod+Left focus left
bindsym $mod+Down focus down
bindsym $mod+Up focus up
bindsym $mod+Right focus right
bindsym $mod+Shift+Left move left
bindsym $mod+Shift+Down move down
bindsym $mod+Shift+Up move up
bindsym $mod+Shift+Right move right

### Workspaces 1-8
# Input method switch. fcitx5's own hotkey needs an X11 grab that some clients
# never trigger; binding it in i3 makes Ctrl+Space always work.
bindsym Control+space exec --no-startup-id fcitx5-remote -t
bindsym $mod+1 workspace number 1
bindsym $mod+2 workspace number 2
bindsym $mod+3 workspace number 3
bindsym $mod+4 workspace number 4
bindsym $mod+5 workspace number 5
bindsym $mod+6 workspace number 6
bindsym $mod+7 workspace number 7
bindsym $mod+8 workspace number 8
bindsym $mod+Shift+1 move container to workspace number 1
bindsym $mod+Shift+2 move container to workspace number 2
bindsym $mod+Shift+3 move container to workspace number 3
bindsym $mod+Shift+4 move container to workspace number 4
bindsym $mod+Shift+5 move container to workspace number 5
bindsym $mod+Shift+6 move container to workspace number 6
bindsym $mod+Shift+7 move container to workspace number 7
bindsym $mod+Shift+8 move container to workspace number 8

### Layout
bindsym $mod+b split h
bindsym $mod+s split v
bindsym $mod+w layout tabbed
bindsym $mod+f fullscreen toggle
bindsym $mod+Shift+space floating toggle
bindsym $mod+space focus mode_toggle
bindsym $mod+a focus parent
bindsym $mod+r mode resize

mode "resize" {
    bindsym Left resize shrink width 10 px or 10 ppt
    bindsym Down resize grow height 10 px or 10 ppt
    bindsym Up resize shrink height 10 px or 10 ppt
    bindsym Right resize grow width 10 px or 10 ppt
    bindsym Return mode "default"
    bindsym Escape mode "default"
}

### Autostart
# dbus-update-activation-environment keeps the session bus in sync with the
# X11 session, which GTK/portal/notifications rely on. XDG_CURRENT_DESKTOP
# must be i3: portal backends pick their implementation from it, and a wrong
# value makes them look for a desktop that is not running.
exec_always --no-startup-id dbus-update-activation-environment --systemd DISPLAY XAUTHORITY XDG_SESSION_TYPE XDG_CURRENT_DESKTOP=i3
exec --no-startup-id lxpolkit
# picom supplies the compositor: shadows only, no blur, and the bar is
# excluded so its own alpha is drawn untouched. The rules live in a config
# file because i3 does not honour shell quoting on an exec line, which used
# to strip the quotes off the shadow-exclude rule.
exec --no-startup-id picom --config "$HOME/.config/picom/picom.conf"
exec --no-startup-id dunst
# Input method. i3 has no xdg-autostart, so the ~/.config/autostart entry that
# sway uses is not enough here; start it directly, but only when fcitx5 exists
# and is not already running.
exec --no-startup-id sh -c 'command -v fcitx5 >/dev/null 2>&1 && ! pgrep -x fcitx5 >/dev/null 2>&1 && exec fcitx5 -d --disable virtualkeyboard,emoji,table,spell,kimpanel,quickphrase,unicode,clipboard,notificationitem,fcitx4frontend,ibusfrontend,wayland,waylandim'
exec --no-startup-id xwallpaper --zoom "$wall"
# The bar is a dock strip at an exact offset. i3 places tiled clients itself,
# so the bar is declared floating, borderless and pinned with a move command;
# the bar program also sets _NET_WM_WINDOW_TYPE_DOCK and its strut.
# The bar is a GTK dock: i3 reserves a dockarea exactly as tall as the dock
# window, so windows never overlap the strip. i3 has no "top offset" for a
# dock, which means the window must *include* the reference's 6px top margin -
# otherwise the workspace starts at y=34 and paints over the bar's bottom edge.
for_window [class="^i3-everforest-bar-c$"] floating enable, border none
for_window [class="^i3-everforest-bar-c$"] move position 0 px 0 px
for_window [class="^i3-everforest-bar-c$"] sticky enable
# exec_always, not exec: a plain `exec` runs once per i3 *start*, so
# `i3-msg restart` left the desktop with no bar at all. exec_always re-runs on
# every reload, which is what makes the bar come back after a reload.
#
# It re-runs unconditionally, so two details matter:
#   - guard with pgrep, or every reload would add another bar
#   - start it with `&`, not `exec`: `exec` replaces the shell that i3 waits
#     on, and i3 then treats the long-lived bar as a command that never
#     returns.
exec_always --no-startup-id sh -c 'pgrep -f "/usr/local/bin/i3-everforest-bar$" >/dev/null 2>&1 || /usr/local/bin/i3-everforest-bar &'
exec --no-startup-id i3-everforest-border
exec --no-startup-id i3-everforest-wifi-cache
exec --no-startup-id i3-everforest-idle
I3CONF
	install_user_file "${cfg}" 644 <"${tmp}"
	rm -f "${tmp}"
}

write_bar() {
	# The bar is a small C program: cairo + pango on a plain X11 dock window.
	# It reproduces the Waybar stylesheet that the GTK version used, at about a
	# twentieth of the memory (3 MB vs 62 MB) and without a Python runtime.
	#
	# The sources ship inside this installer and are compiled at install time,
	# so the target machine needs no source tree afterwards.
	local dir="${HOME_DIR}/.config/i3-everforest"
	local src="${ASSET_DIR}/bar-c"
	local build
	mkdir -p "${dir}"

	if [[ ! -d "${src}/src" ]]; then
		ui_warn "the bundled bar sources are missing"
		return 1
	fi

	if ! pkg-config --exists cairo pangocairo x11 2>/dev/null; then
		ui_warn "bar build needs libcairo2-dev, libpango1.0-dev and libx11-dev"
		return 1
	fi

	build="$(mktemp -d)"
	cp -r "${src}/src" "${build}/src"
	cp "${src}/Makefile" "${build}/Makefile"
	if ! ( cd "${build}" && make -s 2>/dev/null ); then
		ui_warn "the bar failed to build"
		rm -rf "${build}"
		return 1
	fi
	install -m 755 "${build}/i3-everforest-bar-c" /usr/local/bin/i3-everforest-bar
	rm -rf "${build}"
	register_file "/usr/local/bin/i3-everforest-bar"

	# The layout description mirrors the Waybar config key for key. Opacity is
	# handled specially: if a bar.json already exists, keep whatever the user
	# has selected there unless --opacity was passed explicitly. Reinstalling
	# used to silently reset the choice back to "solid".
	local opacity="${BAR_OPACITY}"
	if [[ -z "${OPT_OPACITY_GIVEN:-}" && -f "${dir}/bar.json" ]]; then
		local cur
		cur="$(sed -n 's/.*"opacity"[[:space:]]*:[[:space:]]*"\([a-z]*\)".*/\1/p' \
			"${dir}/bar.json" 2>/dev/null | head -1)"
		case "${cur}" in
		solid|soft|clear) opacity="${cur}" ;;
		esac
	fi
	[[ -n "${opacity}" ]] || opacity="solid"

	local tmp; tmp="$(mktemp)"
	if [[ -f "${ASSET_DIR}/bar/bar.json" ]]; then
		sed -e "s|\"opacity\": *\"[a-z]*\"|\"opacity\": \"${opacity}\"|" \
			"${ASSET_DIR}/bar/bar.json" >"${tmp}"
	fi
	install_user_file "${dir}/bar.json" 644 <"${tmp}"
	rm -f "${tmp}"
	ui_dim "bar opacity: ${opacity}"
}

write_bar_opacity() {
	# Change the bar's transparency preset at runtime.
	#
	#   i3-everforest-bar-opacity            cycle solid -> soft -> clear
	#   i3-everforest-bar-opacity clear      set one preset
	#
	# The preset lives in bar.json; the bar re-reads it on SIGHUP, so the change
	# applies immediately and survives the next login.
	local ctl="/usr/local/bin/i3-everforest-bar-opacity"
	cat >"${ctl}" <<'OPSH'
#!/bin/sh
# Change the bar transparency preset and reload the running bar.
export LC_ALL=C

cfg="${HOME}/.config/i3-everforest/bar.json"
[ -f "${cfg}" ] || { echo "no ${cfg}" >&2; exit 1; }

cur=$(sed -n 's/.*"opacity"[[:space:]]*:[[:space:]]*"\([a-z]*\)".*/\1/p' "${cfg}" | head -1)
[ -n "${cur}" ] || cur=solid

case "${1:-}" in
	solid|soft|clear) want="$1" ;;
	"")
		case "${cur}" in
		solid) want=soft ;;
		soft)  want=clear ;;
		*)     want=solid ;;
		esac
		;;
	*) echo "usage: $(basename "$0") [solid|soft|clear]" >&2; exit 2 ;;
esac

sed -i "s|\"opacity\"[[:space:]]*:[[:space:]]*\"[a-z]*\"|\"opacity\": \"${want}\"|" "${cfg}"

pid=$(ps -eo pid,args --no-headers 2>/dev/null |
	awk '$2 ~ /i3-everforest-bar$/ { print $1; exit }')
[ -n "${pid}" ] && kill -HUP "${pid}" 2>/dev/null

printf 'bar opacity: %s -> %s\n' "${cur}" "${want}"
OPSH
	chmod 755 "${ctl}"
	register_file "${ctl}"
	ui_ok "bar opacity switcher installed"
}

write_border_ctl() {
	# i3 reads `default_border` only at startup, so a window created after a
	# reload got no outline; and `hide_edge_borders` cannot tell a split pane
	# from a lone one. Decide per workspace instead: a single window fills the
	# workspace (no border), two or more are split (each keeps its border).
	local ctl="/usr/local/bin/i3-everforest-border"
	cat >"${ctl}" <<'BCTL'
#!/usr/bin/env python3
"""Keep window borders in step with the layout.

A lone window fills its workspace and should look edge-to-edge, so it gets no
outline; as soon as the workspace is split, every pane shows one.
"""
import i3ipc


def leaves(con):
    out = []

    def walk(c):
        if c.window is not None:
            out.append(c)
            return
        for n in c.nodes:
            walk(n)

    walk(con)
    return out


def apply(i3, _event=None):
    try:
        for ws in i3.get_tree().workspaces():
            panes = leaves(ws)
            want = "pixel" if len(panes) > 1 else "none"
            for c in panes:
                if c.name and "everforest-bar" in c.name:
                    continue
                if c.border != want:
                    c.command(f"border {want}")
    except Exception:
        pass


def main():
    i3 = i3ipc.Connection()
    apply(i3)
    for ev in ("window::new", "window::close", "window::move",
               "window::floating"):
        i3.on(ev, apply)
    i3.main()


if __name__ == "__main__":
    main()
BCTL
	chmod 755 "${ctl}"
	register_file "${ctl}"
	ui_ok "border controller installed"
}


# ---------------------------------------------------------------------
#  X11 session environment
# ---------------------------------------------------------------------
#  On Wayland, environment.d fed the session through systemd. An X session
#  started by a display manager or startx does not read it: it sources
#  ~/.xsessionrc (Debian's Xsession) and ~/.xprofile (startx), and tools like
#  im-config write ~/.xinputrc. Writing the same exports there is what makes
#  the theme, the cursor and the IME apply inside i3.
write_xsession_env() {
	local xsr="${HOME_DIR}/.xsessionrc"
	local marker_begin="# >>> i3-everforest >>>"
	local marker_end="# <<< i3-everforest <<<"

	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then
		ui_dim "would write ${xsr}"
		return 0
	fi

	if grep -qF "${marker_begin}" "${xsr}" 2>/dev/null; then
		# The block already exists: make sure settings added since then are
		# present, without rewriting the whole file.
		if ! grep -q 'ST_ALPHA' "${xsr}" 2>/dev/null; then
			sed -i "/${marker_end}/i export ST_ALPHA=78" "${xsr}" 2>/dev/null
		fi
		ui_dim "unchanged: ${xsr}"
		return 0
	fi
	[[ -f "${xsr}" ]] && backup_path "${xsr}"

	cat >>"${xsr}" <<XSESS
${marker_begin}
# Session identity: every desktop-aware program (portals, Qt, GTK, OBS,
# browsers) keys off these.
export XDG_CURRENT_DESKTOP=i3
export XDG_SESSION_DESKTOP=i3
export XDG_SESSION_TYPE=x11
export DESKTOP_SESSION=i3
export XDG_SESSION_CLASS=user

# Toolkit hints for an X11 desktop.
export QT_QPA_PLATFORMTHEME=gtk3
export MOZ_ENABLE_WAYLAND=0
export _JAVA_AWT_WM_NONREPARENTING=1

# Use the polkit agent and the notification daemon this rice ships.
export GTK_THEME=${THEME_NAME}

# Keep the X clipboard alive after a client exits, so screenshots and the
# colour picker still paste.
export CLIPBOARD_PERSIST=1

# st reads its background alpha from here; keep the terminal translucent
# (60%) the way kitty's background_opacity 0.60 looks.
export ST_ALPHA=78

${marker_end}
XSESS
	register_file "${xsr}"
	chown_user "${xsr}" 2>/dev/null || true

	# ~/.Xresources: the GTK/cursor/Xft settings that X clients read at start.
	local xres="${HOME_DIR}/.Xresources"
	local rmark_begin="! >>> i3-everforest >>>"
	local rmark_end="! <<< i3-everforest <<<"
	if ! grep -qF "${rmark_begin}" "${xres}" 2>/dev/null; then
		[[ -f "${xres}" ]] && backup_path "${xres}"
		cat >>"${xres}" <<XRES
${rmark_begin}
Xft.dpi: 96
Xft.antialias: 1
Xft.hinting: 1
Xft.hintstyle: hintslight
Xft.rgba: rgb
Xcursor.theme: Adwaita
Xcursor.size: 24
${rmark_end}
XRES
		register_file "${xres}"
		chown_user "${xres}" 2>/dev/null || true
	fi
	ui_ok "X11 session environment written"
	return 0
}

user_dirs_create() {
	# xdg-user-dirs creates Desktop/Documents/Downloads/Music/Pictures/Videos
	# from the localized names in /etc/xdg/user-dirs.defaults. Without this the
	# bookmarks and the file manager sidebar point at directories that do not
	# exist yet.
	if command -v xdg-user-dirs-update >/dev/null 2>&1; then
		if [[ ${OPT_DRY_RUN} -eq 1 ]]; then
			ui_dim "would create the XDG user directories"
			return 0
		fi
		as_user xdg-user-dirs-update --force >/dev/null 2>&1 ||
			as_user xdg-user-dirs-update >/dev/null 2>&1 || true
	fi
	# Make sure the set we link to exists even when xdg-user-dirs is absent.
	local d
	for d in Desktop Documents Downloads Music Pictures Videos Public Templates; do
		[[ -d "${HOME_DIR}/${d}" ]] || mkdir -p "${HOME_DIR}/${d}" 2>/dev/null || true
		chown_user "${HOME_DIR}/${d}" 2>/dev/null || true
	done
	ui_ok "user directories ready"
	return 0
}

write_pcmanfm() {
	local dir="${HOME_DIR}/.config/pcmanfm/default"
	# The layout below is the one verified live: Places sidebar with the
	# built-in entries (Home Folder, Desktop, Trash Can) followed by Computer
	# and Network, and nothing else in the bookmark list.
	install_user_file "${dir}/pcmanfm.conf" 644 <<'PCMANFM'
[config]
bm_open_method=0

[volume]
mount_on_startup=1
mount_removable=1
autorun=1

[ui]
always_show_tabs=0
max_tab_chars=32
win_width=778
win_height=820
splitter_pos=150
media_in_new_tab=0
desktop_folder_new_win=0
change_tab_on_drop=1
close_on_unmount=1
focus_previous=0
side_pane_mode=places
view_mode=icon
show_hidden=0
sort=name;ascending;
toolbar=newtab;navigation;home;
show_statusbar=1
pathbar_mode_buttons=0
PCMANFM
	register_file "${dir}/pcmanfm.conf"

	# Sidebar bookmarks: ~/.config/gtk-3.0/bookmarks, one entry per line as
	# "URI [Label]".
	#
	# PCManFM renders its own places first (Home Folder, Desktop, Trash Can),
	# driven by GIO's volume monitor, so listing those here would duplicate
	# them. Computer and Network are not offered automatically on a machine
	# with no mounted volumes and no gvfs network backends, which is why they
	# are added explicitly:
	#   computer:///  resolves to the "computer" icon; file:/// would only
	#                 get a plain folder icon.
	#   network:///   PCManFM's own network browser, no gvfs required.
	local bm="${HOME_DIR}/.config/gtk-3.0/bookmarks"
	mkdir -p "$(dirname "${bm}")"
	{
		printf 'computer:/// Computer\n'
		printf 'network:/// Network\n'
	} >"${bm}"
	register_file "${bm}"
	chown_user "${bm}"
	return 0
}


write_foot() {
	local dir="${HOME_DIR}/.config/foot"
	# foot reads the background alpha from the colour itself, so transparency
	# needs no compositor effect. Option placement matters: every key has one
	# valid section, and a misplaced one makes foot print a config error on
	# every start (alpha belongs under [colors], lines under [scrollback]).
	install_user_file "${dir}/foot.ini" 644 <<'FOOT'
# foot - Everforest (dark)

[main]
font=JetBrains Mono:size=11
dpi-aware=no
# 2px of breathing room so the text does not touch the i3 border.
pad=2x2
selection-target=both

[scrollback]
lines=10000
multiplier=3.0

[cursor]
style=block
blink=yes

[mouse]
hide-when-typing=yes

[csd]
# The compositor draws the frame; foot's own title bar is not wanted.
preferred=server

[colors]
# Pure black base at 60% alpha: the wallpaper tints it without washing out
# the text. Raise towards 1.0 for a more solid window.
alpha=0.60
background=000000
foreground=d3c6aa
regular0=000000
regular1=e67e80
regular2=a7c080
regular3=dbbc7f
regular4=7fbbb3
regular5=d699b6
regular6=83c092
regular7=d3c6aa
bright0=7a8478
bright1=e67e80
bright2=a7c080
bright3=dbbc7f
bright4=7fbbb3
bright5=d699b6
bright6=83c092
bright7=fffbef

[key-bindings]
clipboard-copy=Control+Shift+c
clipboard-paste=Control+Shift+v
primary-paste=Shift+Insert
spawn-terminal=Control+Shift+n
FOOT
}



write_st_desktop() {
	# st ships no .desktop file, so it never appeared in rofi's drun list.
	local desk="/usr/local/share/applications/st.desktop"
	mkdir -p "$(dirname "${desk}")" 2>/dev/null
	cat >"${desk}" <<'STDESK'
[Desktop Entry]
Type=Application
Name=Simple Terminal
Comment=Simple terminal
GenericName=Terminal
Exec=st
Icon=utilities-terminal
Terminal=false
Categories=System;TerminalEmulator;
Keywords=shell;prompt;command;terminal;
StartupNotify=true
STDESK
	chmod 644 "${desk}"
	register_file "${desk}"
	# Some rofi builds only scan the system directory.
	if [[ -d /usr/share/applications ]]; then
		cp "${desk}" /usr/share/applications/st.desktop 2>/dev/null &&
			chmod 644 /usr/share/applications/st.desktop 2>/dev/null &&
			register_file /usr/share/applications/st.desktop
	fi
	ui_ok "st desktop entry installed"

	# The rice's icon theme carries only a few application icons, so entries
	# like the file manager showed a blank row. Drop a user-level copy of
	# index.theme whose inheritance falls back to Numix-Circle (12k icons).
	local ico_dir="${HOME_DIR}/.local/share/icons/${ICON_NAME}"
	local src_index="/usr/share/icons/${ICON_NAME}/index.theme"
	[[ -f "${src_index}" ]] || return 0
	mkdir -p "${ico_dir}" 2>/dev/null
	sed -e 's/^Inherits=.*/Inherits=Numix-Circle,gnome,hicolor/' \
		"${src_index}" >"${ico_dir}/index.theme" 2>/dev/null
	install_user_file "${ico_dir}/index.theme" 644 <"${ico_dir}/index.theme"
}


write_st() {
	# st (suckless terminal) replaces kitty: the same Everforest palette, but
	# ~8 MB resident instead of ~130 MB. It is not packaged for Debian, so the
	# installer builds it once and installs the binary; the patched config.h
	# carries the colours so the look matches the rest of the rice.
	local src="/usr/local/src/i3-everforest-st"
	local bin="/usr/local/bin/st"

	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then
		ui_dim "would build ${bin} from source"
		return 0
	fi

	if command -v st >/dev/null 2>&1 && \
		"${bin}" -v 2>&1 | grep -q '^st-'; then
		ui_dim "st already installed"
		return 0
	fi

	if ! command -v make >/dev/null 2>&1 || ! command -v cc >/dev/null 2>&1; then
		ui_warn "no C toolchain - st cannot be built"
		return 0
	fi

	mkdir -p "${src}" 2>/dev/null
	chmod 755 "${src}" 2>/dev/null

	local tarball="${src}/st.tar.gz"
	if [[ ! -s "${src}/st/config.h" ]]; then
		curl -fsSL https://dl.suckless.org/st/st-0.9.2.tar.gz \
			-o "${tarball}" 2>/dev/null || {
			ui_warn "could not download st"
			return 0
		}
		tar xzf "${tarball}" -C "${src}" --strip-components=1 2>/dev/null
	fi

	# Give st a real default window title: with opt_title == NULL the window
	# name is empty and the bar shows the class ("st") instead.
	python3 - "${src}/x.c" <<'PYTITLE'
import sys

path = sys.argv[1]
text = open(path, encoding="utf-8").read()
if "opt_title = \"Simple Terminal\"" not in text:
    text = text.replace('static char *opt_title = NULL;',
                        'static char *opt_title = "Simple Terminal";')
open(path, "w", encoding="utf-8").write(text)
PYTITLE

	# Start from the shipped config.def.h and patch only the values we change:
	# replacing the file wholesale dropped required declarations (cols, rows,
	# selmasks, ...) and broke the build.
	cp "${src}/config.def.h" "${src}/config.h"

	# Palette: the rice's Everforest colours.
	python3 - "${src}/config.h" <<'PYPATCH'
import re
import sys

path = sys.argv[1]
text = open(path, encoding="utf-8").read()

palette = """static const char *colorname[] = {
	/* Exactly the values from the rice's kitty.conf. */
	[0]   = "#000000", [1]   = "#e67e80", [2]   = "#a7c080", [3]   = "#dbbc7f",
	[4]   = "#7fbbb3", [5]   = "#d699b6", [6]   = "#83c092", [7]   = "#d3c6aa",
	[8]   = "#7a8478", [9]   = "#e67e80", [10]  = "#a7c080", [11]  = "#dbbc7f",
	[12]  = "#7fbbb3", [13]  = "#d699b6", [14]  = "#83c092", [15]  = "#fffbef",
	[255] = 0,
	[256] = "#d3c6aa",  /* foreground */
	[257] = "#000000",  /* background */
	[258] = "#d3c6aa",  /* cursor */
	[259] = "#1e2326",  /* reverse cursor */
};
"""

text = re.sub(r"static const char \*colorname\[\] = \{.*?\n\};",
              palette.rstrip(), text, flags=re.S)

# Larger text and a comfortable inset from the window edge.
text = re.sub(r'^static char \*font\s*=.*$',
              'static char *font = '
              '"JetBrains Mono:pixelsize=14:antialias=true:hinting=true:hintstyle=hintslight:autohint=false:rgba=rgb";',
              text, flags=re.M)
text = re.sub(r'^static int borderpx\s*=.*$', 'static int borderpx = 2;',
              text, flags=re.M)

# kitty blinks the block cursor every 0.5s; st uses milliseconds.
text = re.sub(r'^static unsigned int blinktimeout\s*=.*$',
              'static unsigned int blinktimeout = 500;', text, flags=re.M)

# Point the default colours at the palette slots filled above. config.def.h
# leaves defaultbg at 259 (a lighter shade), which made the whole window look
# washed-out grey instead of black.
text = re.sub(r'^unsigned int defaultfg\s*=.*$', 'unsigned int defaultfg = 256;',
              text, flags=re.M)
text = re.sub(r'^unsigned int defaultbg\s*=.*$', 'unsigned int defaultbg = 257;',
              text, flags=re.M)
text = re.sub(r'^unsigned int defaultcs\s*=.*$', 'unsigned int defaultcs = 258;',
              text, flags=re.M)
text = re.sub(r'^static unsigned int defaultrcs\s*=.*$',
              'static unsigned int defaultrcs = 259;', text, flags=re.M)

open(path, "w", encoding="utf-8").write(text)
PYPATCH

	# Background-only transparency, the way kitty's background_opacity works.
	#
	# st picks the default (24-bit) visual, which has no alpha channel, so a
	# translucent background colour is simply ignored. Give it an ARGB visual
	# and paint the background with XRender using ST_ALPHA, leaving the glyphs
	# fully opaque - picom cannot do this because it dims the whole window.
	python3 - "${src}/x.c" <<'PYPATCH2'
import re
import sys

path = sys.argv[1]
text = open(path, encoding="utf-8").read()

if "xw.depth" not in text:
    # 1) Prefer a 32-bit TrueColor visual when one exists.
    text = text.replace(
        "\txw.vis = XDefaultVisual(xw.dpy, xw.scr);",
        "\t/* Prefer an ARGB visual so a translucent background is possible. */\n"
        "\t{\n"
        "\t\tXVisualInfo vi;\n"
        "\t\tif (XMatchVisualInfo(xw.dpy, xw.scr, 32, TrueColor, &vi)) {\n"
        "\t\t\txw.vis = vi.visual;\n"
        "\t\t\txw.depth = 32;\n"
        "\t\t} else {\n"
        "\t\t\txw.vis = XDefaultVisual(xw.dpy, xw.scr);\n"
        "\t\t\txw.depth = XDefaultDepth(xw.dpy, xw.scr);\n"
        "\t\t}\n"
        "\t}")

    # 2) A 32-bit visual needs its own colormap, not the root's.
    text = text.replace(
        "\txw.cmap = XDefaultColormap(xw.dpy, xw.scr);",
        "\txw.cmap = (xw.depth == 32)\n"
        "\t\t? XCreateColormap(xw.dpy, XRootWindow(xw.dpy, xw.scr),\n"
        "\t\t\txw.vis, AllocNone)\n"
        "\t\t: XDefaultColormap(xw.dpy, xw.scr);")

    # 3) The back buffer must match the window depth too.
    text = text.replace(
        "xw.buf = XCreatePixmap(xw.dpy, xw.win, win.w, win.h,\n\t\t\tDefaultDepth(xw.dpy, xw.scr));",
        "xw.buf = XCreatePixmap(xw.dpy, xw.win, win.w, win.h,\n\t\t\txw.depth);")

    # 4) The GC must be bound to the window, not the root: drawing into a 32-bit
    # pixmap with a 24-bit GC raises BadMatch.
    text = text.replace(
        "dc.gc = XCreateGC(xw.dpy, parent, GCGraphicsExposures,",
        "dc.gc = XCreateGC(xw.dpy, xw.win, GCGraphicsExposures,")

    # 5) A 32-bit window must not have an opaque background pixel.
    text = text.replace(
        "\txw.attrs.background_pixel = dc.col[defaultbg].pixel;",
        "\txw.attrs.background_pixel = (xw.depth == 32)\n"
        "\t\t? 0 : dc.col[defaultbg].pixel;")

    # 6) Apply the background alpha after the palette is loaded:
    # XftColorAllocName always returns alpha=0xffff.
    text = text.replace(
        "\tloaded = 1;\n}",
        "\tif (xw.depth == 32) {\n"
        "\t\tunsigned short a = (unsigned short)(65535.0 *\n"
        "\t\t\t((getenv(\"ST_ALPHA\") ? atoi(getenv(\"ST_ALPHA\")) : 78) / 100.0));\n"
        "\t\tdc.col[defaultbg].color.alpha = a;\n"
        "\t}\n"
        "\tloaded = 1;\n}", 1)

    # 6) Create the window with that depth and colormap.
    text = text.replace(
        "\t\t\twin.w, win.h, 0, XDefaultDepth(xw.dpy, xw.scr), InputOutput,\n"
        "\t\t\txw.vis, CWBackPixel | CWBorderPixel | CWBitGravity",
        "\t\t\twin.w, win.h, 0, xw.depth, InputOutput,\n"
        "\t\t\txw.vis, CWBackPixel | CWBorderPixel | CWBitGravity")

    # 3) Background alpha from ST_ALPHA so only the backdrop is see-through.
    text = text.replace(
        "colbg.alpha = 0xffff;",
        "colbg.alpha = (unsigned short)(65535.0 *\n"
        "\t\t\t((getenv(\"ST_ALPHA\") ? atoi(getenv(\"ST_ALPHA\")) : 78) / 100.0));")

open(path, "w", encoding="utf-8").write(text)
PYPATCH2

	# xw.depth is new; the XWindow struct lives in x.c.
	python3 - "${src}/x.c" <<'PYPATCH3'
import sys

path = sys.argv[1]
text = open(path, encoding="utf-8").read()
if "\tint depth;" not in text:
    text = text.replace("\tVisual *vis;", "\tVisual *vis;\n\tint depth;", 1)
open(path, "w", encoding="utf-8").write(text)
PYPATCH3

	# Font and padding, matching the rice.
	sed -i \
		-e 's|^static char \*font.*|static char *font = "JetBrains Mono:pixelsize=14:antialias=true:hinting=true:hintstyle=hintslight:autohint=false:rgba=rgb";|' \
		-e 's|^static int borderpx.*|static int borderpx = 2;|' \
		"${src}/config.h" 2>/dev/null

	( cd "${src}" && make clean >/dev/null 2>&1 && make >/dev/null 2>&1 ) || {
		ui_warn "st failed to build"
		return 0
	}

	install -m 755 "${src}/st" "${bin}" 2>/dev/null && \
		register_file "${bin}"
	if command -v setcap >/dev/null 2>&1; then
		setcap cap_net_ext_admin+ep "${bin}" 2>/dev/null || true
	fi
	ui_ok "built ${bin}"
}


write_kitty() {
	local dir="${HOME_DIR}/.config/kitty"
	# The rice's terminal is foot, which is Wayland-only and cannot run on X11.
	# kitty replaces it, and every visible value is carried over from foot.ini
	# so the terminal looks identical:
	#   font        JetBrains Mono 11pt     (foot: size=11)
	#   padding     2px                     (foot: pad=2x2)
	#   opacity     0.60                    (foot: alpha=0.60)
	#   background  #000000, the 16 Everforest colours from foot's palette
	#   cursor      block, blinking         (foot: style=block, blink=yes)
	#   scrollback  10000 lines             (foot: lines=10000)
	#   mouse       hide when typing        (foot: hide-when-typing=yes)
	#   no decorations                      (foot: csd.preferred=server)
	install_user_file "${dir}/kitty.conf" 644 <<'KITTY'
# kitty - Everforest (faithful port of the rice's foot.ini)
#
# foot is a Wayland terminal and cannot run under X11, so kitty takes its
# place. Every value below mirrors foot.ini line for line.

# foot [main] font=JetBrains Mono:size=11
font_family      JetBrains Mono
bold_font        auto
italic_font      auto
bold_italic_font auto
font_size        11.0

# foot [main] pad=2x2
window_padding_width 2

# foot [colors] alpha=0.60
background_opacity 0.60

# foot [csd] preferred=server: the WM draws the frame, not the terminal.
hide_window_decorations yes
remember_window_size  no
initial_window_width  640
initial_window_height 400

# foot [scrollback] lines=10000 multiplier=3.0
scrollback_lines 10000

# foot [cursor] style=block blink=yes
cursor_shape         block
cursor_blink_interval 0.5

# foot [mouse] hide-when-typing=yes
mouse_hide_wait 0.0

# foot [key-bindings]
#   clipboard-copy=Control+Shift+c
#   clipboard-paste=Control+Shift+v
#   primary-paste=Shift+Insert
#   spawn-terminal=Control+Shift+n
map ctrl+shift+c    copy_to_clipboard
map ctrl+shift+v    paste_from_clipboard
map shift+insert    paste_from_selection
map ctrl+shift+n    new_os_window

# foot [colors]: background=000000 foreground=d3c6aa
background            #000000
foreground            #d3c6aa
selection_background  #d3c6aa
selection_foreground  #1e2326

# foot regular0..regular7
color0  #000000
color1  #e67e80
color2  #a7c080
color3  #dbbc7f
color4  #7fbbb3
color5  #d699b6
color6  #83c092
color7  #d3c6aa

# foot bright0..bright7
color8   #7a8478
color9   #e67e80
color10  #a7c080
color11  #dbbc7f
color12  #7fbbb3
color13  #d699b6
color14  #83c092
color15  #fffbef

# foot cursor colours (background / foreground swapped, as foot does)
cursor            #d3c6aa
cursor_text_color #000000

# Kitty's own conveniences that foot also had
enable_audio_bell no
confirm_os_window_close 0
KITTY
}

write_rofi() {
	local dir="${HOME_DIR}/.config/rofi"
	# Rofi replaces wofi here, so the theme reproduces wofi's stylesheet value
	# for value. The wofi CSS this is derived from:
	#     *          font 17px
	#     #outer-box #1e2326, 1px solid #d3c6aa, radius 12px,
	#                padding 10px 14px 14px 14px
	#     #input     #2f3336, radius 4px, padding 4px 12px, margin 0 0 10px 0
	#     #entry     min-height 41px, padding 0 10px, radius 4px
	#     #entry:selected   #b9ff66 with #1e2326 text
	# Window size comes from the wofi config: 440x330, centred.
	install_user_file "${dir}/config.rasi" 644 <<'ROFICONF'
/* Rofi - Everforest. Behaviour only; the look lives in the theme below.
 *
 * The geometry mirrors the wofi config this rice used on sway:
 *   width=440, height=330, location=center, columns=1,
 *   allow_images=true, image_size=24, insensitive=true,
 *   matching=contains, hide_scroll=true
 */
configuration {
    modi: "drun,run";
    show-icons: true;
    icon-theme: "Material-Black-Lime-Numix-FLAT";
    display-drun: "Applications";
    display-run: "Run";
    drun-display-format: "{name}";
    /* wofi's matching=contains is a plain substring match; rofi calls that
     * "normal" (valid values: normal, regex, glob, fuzzy, prefix). */
    matching: "normal";
    /* wofi's insensitive=true: search is not case sensitive */
    case-sensitive: false;
    /* wofi's hide_scroll=true: keep the scrollbar hidden and add no arrows */
    scroll-method: 0;
    terminal: "st";
    font: "JetBrains Mono 13";
    /* wofi searched as you typed with no explicit submit */
    lazy-filter: true;
    /* wofi's allow_images / image_size=24 live in the theme */
}

/* Load the Everforest look. This must stay the last directive in the file. */
@theme "i3-everforest"
ROFICONF

	install_user_file "${dir}/i3-everforest.rasi" 644 <<'ROFITHEME'
/* Rofi - Everforest, a faithful port of the wofi stylesheet.
 *
 * Every value below is the one the wofi CSS used, so the launcher looks the
 * same as it did on sway: flat #1e2326 panel, 1px cream border, 12px radius,
 * inset #2f3336 search field, 41px rows, lime selection with dark text.
 */
* {
    bg0:    #1e2326;
    bg1:    #2f3336;
    fg:     #d3c6aa;
    lime:   #b9ff66;
    grey:   #7a8478;

    background-color: transparent;
    text-color:       @fg;
    font:             "JetBrains Mono 13";
    border:           0;
    margin:           0;
    padding:          0;
    spacing:          0;
}

window {
    /* wofi: window { background-color: transparent; border: none; } */
    background-color: transparent;
    border:           0;
    padding:          0;
    /* wofi config: width=440 height=330 location=center */
    width:            440px;
    height:           330px;
    location:         center;
    anchor:           center;
}

/* wofi #outer-box: #1e2326, 1px solid #d3c6aa, radius 12px,
 * padding 10px 14px 14px 14px */
mainbox {
    /* Translucent so picom's dual-kawase blur shows through: an opaque
     * background would hide the frosted backdrop entirely. */
    background-color: rgba(30, 35, 38, 0.78);
    border:           1px solid;
    border-color:     @fg;
    border-radius:    12px;
    padding:          10px 14px 14px 14px;
    spacing:          10px;
    children:         [ inputbar, message, listview ];
}

/* Detail pane used by the wifi configuration menu (-mesg). Wrapped in a
 * scrollable textbox so long values stay readable. */
message {
    background-color: @bg1;
    border-radius:    4px;
    padding:          8px 12px;
    margin:           0px 0px 8px 0px;
}

textbox {
    text-color:  @fg;
    font:        "JetBrains Mono 10";
    background-color: transparent;
}

/* wofi #input: #2f3336, radius 4px, padding 4px 12px, margin-bottom 10px */
inputbar {
    background-color: @bg1;
    border-radius:    4px;
    padding:          4px 12px;
    margin:           0 0 10px 0;
    spacing:          8px;
    children:         [ prompt, entry ];
}

/* wofi #input image { color: #7a8478; padding-right: 8px; } */
prompt {
    background-color: transparent;
    text-color:       @grey;
    padding:          0 8px 0 0;
}

entry {
    background-color: transparent;
    text-color:       @fg;
    placeholder:      "Search";
    placeholder-color: @grey;
}

/* wofi #scroll { margin: 0; } plus hide_scroll=true */
listview {
    background-color: transparent;
    /* 330px window - 24px mainbox padding - 50px inputbar = 256px for the
     * list; at the reference's 41px row height that is 6 rows. */
    lines:            6;
    columns:          1;
    spacing:          0;
    scrollbar:        false;
    fixed-height:     false;
    dynamic:          true;
    cycle:            true;
    children:         [ element ];
}

/* wofi #entry: padding 0 10px, min-height 41px, radius 4px */
element {
    background-color: transparent;
    text-color:       @fg;
    border-radius:    4px;
    /* wofi #entry: padding 0 10px, min-height 41px. rofi sizes a row from its
     * content (24px icon + text), so the 41px comes from vertical padding
     * rather than `min-height`, which rofi treats as a hint only. */
    padding:          5px 10px;
    /* wofi #img { margin-right: 10px; } is the only gap between icon and
     * text, so the row spacing is 0 and the margin carries it. */
    spacing:          0;
    vertical-align:   0.5;
    children:         [ element-icon, element-text ];
}

/* wofi allow_images / image_size=24, #img { margin-right: 10px; } */
element-icon {
    /* No background box: wofi drew the image directly on the row. */
    background-color: transparent;
    size:             24px;
    /* Centre the 24px icon inside the 41px row, both ways. */
    vertical-align:   0.5;
    horizontal-align: 0.5;
    padding:          0;
    /* wofi #img { margin-right: 10px; } */
    margin:           0 10px 0 0;
    border:           0;
}

/* wofi #text { color: #d3c6aa; padding-left: 4px; } */
element-text {
    background-color: transparent;
    text-color:       inherit;
    /* The 10px gap comes from the icon's margin, as in wofi. */
    padding:          0;
    vertical-align:   0.5;
    horizontal-align: 0;
}

/* wofi #entry:selected { background-color: #b9ff66; }
 * wofi #entry:selected #text { color: #1e2326; font-weight: 700; } */
element selected {
    background-color: @lime;
    text-color:       @bg0;
    border-radius:    4px;
}

element selected element-text {
    text-color: @bg0;
}
ROFITHEME
}

write_picom() {
	local dir="${HOME_DIR}/.config/picom"
	# The reference has no blur and no fancy effects: picom is here to give
	# X11 the per-window alpha the wallpaper shows through, plus a soft
	# shadow. The bar keeps its own translucency, so it is excluded.
	install_user_file "${dir}/picom.conf" 644 <<'PICOM'
# picom - Everforest
#
# Compositing (so ARGB windows such as the bar blend),
# a soft shadow, and a dual-kawase blur limited to the power menu - its
# translucent scrim then reads as frosted glass. Nothing else is blurred, so
# the rest of the rice looks exactly as before.

backend = "glx";

# Frosted glass for the full-screen power menu only.
blur-background = true;
blur-method = "dual_kawase";
blur-strength = 6;
blur-background-frame = false;
blur-background-fixed = false;
# The bar is always a plain transparent frame - never frosted - so it is
# excluded from blur outright.
blur-background-exclude = [
    "class_g = 'i3-frame'",
    "class_g = 'Dunst'",
    "class_g = 'i3-everforest-bar-c'",
    # slop is the region selector used by the screenshot button: as an ARGB
    # overlay it would otherwise frost the whole screen.
    "class_g = 'slop'",
    "class_g = 'i3-everforest-tooltip'",
    "window_type = 'desktop'",
];

# Shadows: subtle, so the 1px Everforest border stays the visual edge.
shadow = true;
shadow-radius = 12;
shadow-opacity = 0.35;
shadow-offset-x = -8;
shadow-offset-y = -8;

# The bar is a translucent panel; a shadow under it would double its edge.
shadow-exclude = [
    "class_g = 'i3-everforest-bar-c'",
    "class_g = 'i3-everforest-tooltip'",
    "class_g = 'i3-frame'",
    "_NET_WM_WINDOW_TYPE@:a = 'DOCK'",
];

# Alacritty, the launcher and the notification daemon carry their own alpha
# (foot's 0.60 ported over); letting picom fade again would double-dim them.
opacity-rule = [
    "100:class_g = 'i3-everforest-bar-c'",
    "100:class_g = 'i3-everforest-tooltip'",
    "100:class_g = 'Rofi'",
    "100:class_g = 'Dunst'",
    /* st renders its own background alpha (ST_ALPHA), like kitty's
     * background_opacity - keep picom from dimming its text as well. */
    "100:class_g = 'st-256color'",
    "100:class_g = 'st'",
];

# Keep fullscreen video and games unredirected so they do not stutter.
unredir-if-possible = true;
unredir-if-possible-exclude = [
    "class_g = 'i3-everforest-bar-c'",
    "class_g = 'i3-everforest-tooltip'",
];

# i3 reparents every window; without this the shadow is drawn around the
# frame instead of the client.
detect-client-leader = true;

# Blur is deliberately absent: sway had none and the reference does not use it.
PICOM
}

write_dunst() {
	local dir="${HOME_DIR}/.config/dunst"
	install_user_file "${dir}/dunstrc" 644 <<'DUNST'
# Dunst - Everforest
[global]
    monitor = 0
    follow = none
    # mako: width=360 height=140
    width = 300
    height = (70, 70)
    # mako: anchor=top-right margin=10. The bar occupies the top 40px
    # (6 margin + 34 strip), so the notification starts below it.
    origin = top-right
    offset = (10, 50)
    scale = 1
    # mako: max-visible=4
    notification_limit = 4
    # mako: progress-color=over #2f3336ff
    progress_bar = true
    progress_bar_height = 6
    progress_bar_frame_width = 1
    progress_bar_min_width = 150
    progress_bar_max_width = 360
    progress_bar_corner_radius = 3
    # mako's background is #1e2326ee (alpha 0xee = 93%); dunst expresses the
    # same thing as 7% transparency on top of an opaque background colour.
    transparency = 7
    separator_height = 2
    padding = 10
    horizontal_padding = 12
    text_icon_padding = 0
    frame_width = 2
    frame_color = "#b9ff66"
    gap_size = 10
    separator_color = frame
    sort = yes
    font = JetBrains Mono 10
    line_height = 0
    format = "<b>%s</b>\n%b"
    alignment = left
    vertical_alignment = center
    show_age_threshold = 60
    ellipsize = middle
    ignore_newline = no
    stack_duplicates = true
    hide_duplicate_count = false
    show_indicators = no
    icon_position = left
    min_icon_size = 24
    max_icon_size = 48
    sticky_history = yes
    history_length = 20
    dmenu = /usr/bin/rofi -dmenu -p dunst:
    browser = /usr/bin/xdg-open
    always_run_script = true
    title = Dunst
    class = Dunst
    corner_radius = 10
    ignore_dbusclose = false
    force_xinerama = false
    mouse_left_click = close_current
    mouse_middle_click = do_action, close_current
    mouse_right_click = close_all

[experimental]
    per_monitor_dpi = false

[urgency_low]
    background = "#1e2326"
    foreground = "#d3c6aa"
    # mako had one border-color for everything (#b9ff66).
    frame_color = "#b9ff66"
    timeout = 6

[urgency_normal]
    background = "#1e2326"
    foreground = "#d3c6aa"
    # mako: border-color=#b9ff66
    frame_color = "#b9ff66"
    # mako: default-timeout=6000
    timeout = 6

[urgency_critical]
    background = "#1e2326"
    foreground = "#e67e80"
    frame_color = "#e67e80"
    timeout = 0
DUNST
}

