	# --- wifi: scan and connect ----------------------------------------------
	cat >/usr/local/bin/i3-everforest-wifi <<'WIFI'
#!/bin/sh
# WiFi control for the bar, driven entirely by NetworkManager.
#
#   (no args)   left click:  pick a network and join it
#   config      right click: connection details (state, IP, signal, forget)
#
# nmcli owns the radio here: the installer flips NetworkManager.conf to
# managed=true and stops any ifupdown wpa_supplicant that would hold the
# interface. Passphrases go through `nmcli --ask`, so they are never passed on
# a command line (where they would show up in ps) and NM stores them itself.
export LC_ALL=C
PATH="/usr/sbin:/sbin:$PATH"

say() {
	command -v notify-send >/dev/null 2>&1 &&
		notify-send -a Everforest -t "${2:-4000}" "WiFi" "$1"
	exit "${3:-0}"
}

have_nm() {
	command -v nmcli >/dev/null 2>&1 || return 1
	systemctl is-active --quiet NetworkManager 2>/dev/null
}

wifi_dev() {
	nmcli -t -f DEVICE,TYPE device 2>/dev/null |
		awk -F: '$2=="wifi"{print $1; exit}'
}

# Current SSID, empty when disconnected.
active_ssid() {
	nmcli -t -f ACTIVE,SSID device wifi list 2>/dev/null |
		awk -F: '$1=="yes"{print $2; exit}'
}

# "SSID<TAB>SIGNAL<TAB>SECURED<TAB>ACTIVE", strongest first, one row per SSID.
scan_networks() {
	nmcli -t -f IN-USE,SSID,SIGNAL,SECURITY device wifi list 2>/dev/null |
		awk -F: 'NF>=4 && $2!="" {
			act = ($1=="*") ? "1" : "0"
			sec = ($4 ~ /WPA|WEP|802/) ? "1" : "0"
			sig = $3 + 0
			# Keep the strongest sighting of each SSID.
			if (!($2 in best) || sig > best[$2]) {
				best[$2] = sig; sect[$2] = sec; actv[$2] = act
			}
		}
		END {
			for (s in best)
				printf "%s\t%d\t%s\t%s\n", s, best[s], sect[s], actv[s]
		}' | sort -t"	" -k2,2nr
}

# Ask for a passphrase through rofi (masked) and hand it to nmcli on stdin so
# it never appears in the process list.
join_network() {
	ssid="$1"
	secured="$2"

	if [ "$secured" = "0" ]; then
		nmcli device wifi connect "$ssid" >/dev/null 2>&1 &&
			say "Connected to $ssid" 3000 0
		say "Could not join $ssid" 5000 1
	fi

	# Reuse NetworkManager's stored key when there is one.
	if nmcli -t -f NAME connection show 2>/dev/null | grep -qxF "$ssid"; then
		nmcli connection up id "$ssid" >/dev/null 2>&1 &&
			say "Connected to $ssid" 3000 0
	fi

	psk=$(rofi -dmenu -password -p "$ssid" -theme i3-everforest \
		-theme-str 'window {width: 420px; height: 90px;}' \
		-theme-str 'listview {lines: 0;}' \
		-theme-str 'mainbox {padding: 10px;}' \
		-theme-str 'entry {placeholder: "Password";}' \
		-no-click-to-exit 2>/dev/null)
	if [ -z "$psk" ]; then
		exit 0
	fi

	# `nmcli --ask` reads the secret from this pipe, so the value stays out of
	# argv. The trailing newline is what the prompt consumes.
	printf '%s\n' "$psk" |
		nmcli --ask device wifi connect "$ssid" >/dev/null 2>&1 &&
		say "Connected to $ssid" 3000 0
	say "Could not join $ssid (wrong password?)" 5000 1
}

show_list() {
	have_nm || say "NetworkManager is not running"

	dev=$(wifi_dev)
	[ -n "$dev" ] || say "No wireless adaptor detected"

	# Read the snapshot a background refresher keeps warm (see
	# i3-everforest-wifi-cache). Falling back to a live call is only needed the
	# very first time, before the cache exists.
	cache="${XDG_RUNTIME_DIR:-/tmp}/i3-everforest-wifi.cache"
	snapshot=""
	if [ -f "${cache}" ]; then
		snapshot=$(cat "${cache}" 2>/dev/null)
	fi
	if [ -z "${snapshot}" ]; then
		snapshot=$(nmcli -t -f IN-USE,SSID,SIGNAL,SECURITY device wifi list 2>/dev/null)
	fi
	cur=$(printf '%s\n' "$snapshot" | awk -F: '$1=="*"{print $2; exit}')
	rows=$(printf '%s\n' "$snapshot" | awk -F: 'NF>=4 && $2!="" {
		act = ($1=="*") ? "1" : "0"
		sec = ($4 ~ /WPA|WEP|802/) ? "1" : "0"
		sig = $3 + 0
		if (!($2 in best) || sig > best[$2]) {
			best[$2] = sig; sect[$2] = sec; actv[$2] = act
		}
	}
	END {
		for (s in best)
			printf "%s\t%d\t%s\t%s\n", s, best[s], sect[s], actv[s]
	}' | sort -t"	" -k2,2nr)
	[ -n "$rows" ] || say "No networks found (is the radio on?)"

	# Display: SSID, signal%, and the security type. No leading glyphs - the
	# list is easier to scan when the names line up.
	display=$(printf '%s\n' "$rows" | awk -F'\t' -v cur="$cur" '
		{
			sig = $2 + 0
			star = ($4 == "1" || $1 == cur) ? "  *" : ""
			lock = ($3 == "1") ? "WPA" : "open"
			printf "%-26s %3d%%  %-4s%s\t%s\n", $1, sig, lock, star, $1
		}')

	tmp_list=$(mktemp /tmp/i3-ef-wifi-XXXXXX)
	printf '%s\n' "$display" | cut -f1 >"${tmp_list}"
	sel=$(rofi -dmenu -p "WiFi" -theme i3-everforest \
		-theme-str 'window {width: 500px; height: 340px;}' \
		-theme-str 'listview {lines: 9;}' \
		-input "${tmp_list}" 2>/dev/null)
	rm -f "${tmp_list}"
	[ -n "$sel" ] || exit 0

	# Map the chosen display row back to the raw SSID.
	ssid=$(printf '%s\n' "$display" | awk -F'\t' -v s="$sel" '$1==s{print $2; exit}')
	[ -n "$ssid" ] || exit 0

	secured=$(printf '%s\n' "$rows" | awk -F'\t' -v s="$ssid" '$1==s{print $3; exit}')
	join_network "$ssid" "${secured:-1}"
}

show_config() {
	have_nm || say "NetworkManager is not running"

	dev=$(wifi_dev)
	[ -n "$dev" ] || say "No wireless adaptor detected"

	# Collect everything NetworkManager knows about the link.
	fields=$(nmcli -t -f GENERAL.STATE,GENERAL.CONNECTION,GENERAL.HWADDR,\
IP4.ADDRESS,IP4.GATEWAY,IP4.DNS,IP4.ROUTE device show "$dev" 2>/dev/null)

	get() {
		# Array fields are reported as "KEY[1]:", scalars as "KEY:".
		printf '%s\n' "$fields" | grep -E "^$1(\[[0-9]+\])?:" |
			cut -d: -f2- | head -1
	}

	get_all() {
		printf '%s\n' "$fields" | grep -E "^$1(\[[0-9]+\])?:" |
			cut -d: -f2- | sed '/^$/d' | paste -sd' ' -
	}

	state=$(get GENERAL.STATE)
	conn=$(get GENERAL.CONNECTION)
	mac=$(get GENERAL.HWADDR)
	ip=$(get IP4.ADDRESS | cut -d/ -f1)
	gw=$(get IP4.GATEWAY)
	dns=$(get_all IP4.DNS)

	# Signal for the active link, from the background cache when present.
	cache="${XDG_RUNTIME_DIR:-/tmp}/i3-everforest-wifi.cache"
	link=""
	if [ -f "${cache}" ]; then
		link=$(awk -F: '$1=="*"{print; exit}' "${cache}" 2>/dev/null)
	fi
	if [ -z "${link}" ]; then
		link=$(nmcli -t -f IN-USE,SSID,SIGNAL,CHAN,RATE device wifi list 2>/dev/null |
			awk -F: '$1=="*"{print; exit}')
	fi
	ssid=$(printf '%s' "$link" | cut -d: -f2)
	sig=$(printf '%s' "$link" | cut -d: -f3)
	chan=$(iw dev "$dev" info 2>/dev/null | awk '/channel/{print $2; exit}')
	sec=$(printf '%s' "$link" | cut -d: -f4)
	rate=$(iw dev "$dev" link 2>/dev/null |
		awk '/bitrate/{print $2, $3; exit}')

	speed=$(nmcli -t -f GENERAL.CONNECTION device show "$dev" 2>/dev/null >/dev/null && \
		iw dev "$dev" link 2>/dev/null | awk '/bitrate/{print $2, $3; exit}')
	bssid=$(iw dev "$dev" link 2>/dev/null | awk '/Connected to/{print $3; exit}')

	info="Interface : ${dev}
State     : ${state:-unknown}
Network   : ${ssid:-none}
BSSID     : ${bssid:-n/a}
MAC       : ${mac:-n/a}
IP        : ${ip:-none}
Gateway   : ${gw:-none}
DNS       : ${dns:-none}
Signal    : ${sig:-n/a}%
Channel   : ${chan:-n/a}
Security  : ${sec:-n/a}
Rate      : ${rate:-n/a}
Link speed: ${speed:-n/a}"

	# Menu entries, each mapped to an action below.
	menu="Reconnect
Disconnect
Forget this network
Open advanced editor
Copy IP to clipboard
Close"

	choice=$(printf '%s\n' "$menu" |
		rofi -dmenu -p "WiFi: ${ssid:-$dev}" -mesg "$info" -theme i3-everforest \
			-theme-str 'window {width: 540px; height: 430px;}' \
			-theme-str 'listview {lines: 6;}' \
			-theme-str 'textbox {font: "JetBrains Mono 10";}' \
			-theme-str 'message {border: 1px 0px 0px 0px; padding: 8px;}' \
			2>/dev/null)
	[ -n "$choice" ] || exit 0

	case "$choice" in
	Reconnect)
		[ -n "$conn" ] && [ "$conn" != "--" ] || exit 0
		nmcli connection down id "$conn" >/dev/null 2>&1
		nmcli connection up id "$conn" >/dev/null 2>&1 &&
			say "Reconnected to $conn" 3000 0
		say "Could not reconnect $conn" 4000 1
		;;
	Disconnect)
		nmcli device disconnect "$dev" >/dev/null 2>&1 &&
			say "Disconnected" 3000 0
		say "Could not disconnect" 4000 1
		;;
	Forget*)
		[ -n "$conn" ] && [ "$conn" != "--" ] || exit 0
		nmcli connection delete id "$conn" >/dev/null 2>&1 &&
			say "Forgot $conn" 3000 0
		say "Could not forget $conn" 4000 1
		;;
	Open\ advanced*)
		# nm-connection-editor ships with network-manager-gnome and gives the
		# full set of options (IPv4 method, DNS, routes, security).
		if command -v nm-connection-editor >/dev/null 2>&1; then
			nm-connection-editor >/dev/null 2>&1 &
		elif command -v nmtui >/dev/null 2>&1; then
			command -v st >/dev/null 2>&1 &&
				st -e nmtui >/dev/null 2>&1 &
		else
			say "No connection editor installed" 4000 1
		fi
		exit 0
		;;
	Copy\ IP*)
		if [ -n "$ip" ] && command -v xclip >/dev/null 2>&1; then
			printf '%s' "$ip" | xclip -selection clipboard 2>/dev/null
			say "Copied $ip" 2500 0
		fi
		say "No IP to copy" 3000 1
		;;
	esac
	exit 0
}

case "${1:-list}" in
config) show_config ;;
*) show_list ;;
esac
WIFI
	chmod 755 /usr/local/bin/i3-everforest-wifi

	# A tiny refresher keeps NetworkManager's wifi list in a file. nmcli blocks
	# for ~10s whenever its internal cache has expired, and paying that on a
	# click is unacceptable; polling in the background means the popup always
	# reads a ready-made snapshot.
	cat >/usr/local/bin/i3-everforest-wifi-cache <<'WCACHE'
#!/bin/sh
# Refresh the wifi snapshot every 20s so the bar's popup opens instantly.
export LC_ALL=C
cache="${XDG_RUNTIME_DIR:-/tmp}/i3-everforest-wifi.cache"
while :; do
	nmcli -t -f IN-USE,SSID,SIGNAL,SECURITY device wifi list \
		>/tmp/.wf.$$ 2>/dev/null &&
		mv /tmp/.wf.$$ "${cache}" 2>/dev/null
	sleep 20
done
WCACHE
	chmod 755 /usr/local/bin/i3-everforest-wifi-cache
	register_file /usr/local/bin/i3-everforest-wifi-cache
	register_file /usr/local/bin/i3-everforest-wifi

	# The bar's wifi control is nmcli-only, so NetworkManager has to own the
	# radio. On a default Debian install NetworkManager.conf ships
	# `managed=false`, which leaves the adaptor to ifupdown and makes every
	# nmcli call fail; flipping it (and stopping an ifupdown wpa_supplicant
	# that already holds the interface) is what makes the bar's wifi work.
	if [[ ${OPT_DRY_RUN} -eq 0 ]]; then
		local nmconf="/etc/NetworkManager/NetworkManager.conf"
		if [[ -f "${nmconf}" ]] && grep -q '^managed=false' "${nmconf}"; then
			sed -i 's/^managed=false/managed=true/' "${nmconf}"
			ui_ok "NetworkManager now manages all devices"
			systemctl restart NetworkManager >/dev/null 2>&1 || true
		fi

		# Stop a stray supplicant started by ifupdown: NetworkManager's own
		# instance cannot grab an interface that is already taken, and the
		# bar's wifi button then scans nothing.
		#
		# `kill ... && ui_dim` used to abort the whole install: under `set -e`
		# a failing kill (already gone, or not ours) makes the loop's exit
		# status non-zero. Collect the pids first and never let a failure
		# escape.
		if command -v pgrep >/dev/null 2>&1; then
			local stray
			stray="$(pgrep -f 'wpa_supplicant.*-i wlp' 2>/dev/null || true)"
			for pid in ${stray}; do
				if kill "${pid}" 2>/dev/null; then
					ui_dim "stopped a stray wpa_supplicant (pid ${pid})"
				fi
			done || true
			# NetworkManager restarts its own instance once the port is free.
			if [[ -n "${stray}" ]]; then
				sleep 1
				systemctl restart NetworkManager >/dev/null 2>&1 || true
			fi
		fi

		# The old setup granted sudo for wpa_cli/iw/dhcp; nmcli needs none.
		local sc="/etc/sudoers.d/i3-everforest-wifi"
		if [[ -f "${sc}" ]]; then
			rm -f "${sc}"
			ui_dim "removed the obsolete wifi sudoers rule"
		fi
	fi

	# --- input method: toggle whichever framework is actually running --------
	cat >/usr/local/bin/i3-everforest-ime <<'IME'
#!/bin/sh
# Input method control for the bar.
#
#   toggle   left click: switch between the configured input methods
#   config   right click: state, current IM, hotkey, and quick actions
export LC_ALL=C

say() {
	command -v notify-send >/dev/null 2>&1 &&
		notify-send -a Everforest -t "${2:-2500}" "Input method" "$1"
	exit "${3:-0}"
}

have_fcitx() {
	command -v fcitx5-remote >/dev/null 2>&1 && pgrep -x fcitx5 >/dev/null 2>&1
}

# "keyboard-us" -> "English (US)", "pinyin" -> "Pinyin"
pretty() {
	case "$1" in
	keyboard-us) echo "English (US)" ;;
	keyboard) echo "English" ;;
	pinyin) echo "Pinyin (Chinese)" ;;
	*) echo "$1" ;;
	esac
}

do_toggle() {
	if have_fcitx; then
		fcitx5-remote -t >/dev/null 2>&1 && exit 0
	fi
	if command -v ibus >/dev/null 2>&1 && pgrep -x ibus-daemon >/dev/null 2>&1; then
		ibus engine "$(ibus engine | grep -q xkb && echo pinyin || echo xkb:us::eng)" \
			>/dev/null 2>&1 && exit 0
	fi
	if command -v setxkbmap >/dev/null 2>&1; then
		cur=$(setxkbmap -query 2>/dev/null | sed -n 's/^layout: *//p')
		case "${cur}" in
		us*) setxkbmap -layout us,ru >/dev/null 2>&1 &&
			setxkbmap -layout ru >/dev/null 2>&1 ;;
		*)   setxkbmap -layout us >/dev/null 2>&1 ;;
		esac
	fi
	if command -v fcitx5 >/dev/null 2>&1 || command -v ibus >/dev/null 2>&1; then
		say "No IM daemon is running"
	fi
	say "No input method installed"
}

do_config() {
	# Framework, state and the current input method.
	if have_fcitx; then
		fw="fcitx5"
		state=$(fcitx5-remote 2>/dev/null)
		case "$state" in
		0) state_txt="disabled" ;;
		1) state_txt="inactive (English)" ;;
		2) state_txt="active" ;;
		*) state_txt="unknown" ;;
		esac
		cur=$(fcitx5-remote -n 2>/dev/null)
	else
		fw="none"
		state_txt="no daemon"
		cur=""
	fi

	# Enabled input methods, from fcitx5's profile.
	ims=""
	if [ -f "${HOME}/.config/fcitx5/profile" ]; then
		ims=$(awk -F= '/^Name=/ && !/^Name=Default/ {print $2}' \
			"${HOME}/.config/fcitx5/profile" 2>/dev/null | paste -sd', ' -)
	fi

	# The trigger key comes from the installed hotkey.conf.
	hotkey=""
	if [ -f "${HOME}/.config/fcitx5/conf/hotkey.conf" ]; then
		hotkey=$(awk -F= '/^[0-9]*=Control\+space/ {print "Ctrl+Space"; exit}' \
			"${HOME}/.config/fcitx5/conf/hotkey.conf" 2>/dev/null)
	fi
	[ -n "${hotkey}" ] || hotkey="Ctrl+Space"

	ver=""
	have_fcitx && ver=$(fcitx5 --version 2>/dev/null | head -1)

	info="Framework : ${fw}
State     : ${state_txt}
Current   : $(pretty "${cur:-none}")
Enabled   : ${ims:-none}
Hotkey    : ${hotkey}
Version   : ${ver:-n/a}"

	menu="Switch input method
Restart fcitx5
Open fcitx5 settings
Reload configuration
Close"

	choice=$(printf '%s\n' "${menu}" |
		rofi -dmenu -p "Input method" -mesg "${info}" -theme i3-everforest \
			-theme-str 'window {width: 520px; height: 380px;}' \
			-theme-str 'listview {lines: 5;}' 2>/dev/null)
	[ -n "${choice}" ] || exit 0

	case "${choice}" in
	Switch*)
		fcitx5-remote -t >/dev/null 2>&1 &&
			say "Switched to $(pretty "$(fcitx5-remote -n 2>/dev/null)")" 2000 0
		say "Could not switch" 3000 1
		;;
	Restart*)
		pkill -x fcitx5 2>/dev/null
		sleep 1
		setsid fcitx5 -d --disable virtualkeyboard,emoji,table,spell,kimpanel,quickphrase,unicode,clipboard,notificationitem,fcitx4frontend,ibusfrontend,wayland,waylandim >/dev/null 2>&1 </dev/null &
		sleep 2
		say "fcitx5 restarted" 2000 0
		;;
	Open\ fcitx5*)
		if command -v fcitx5-configtool >/dev/null 2>&1; then
			setsid fcitx5-configtool >/dev/null 2>&1 </dev/null &
			exit 0
		fi
		say "fcitx5-configtool is not installed" 3500 1
		;;
	Reload*)
		fcitx5-remote -r >/dev/null 2>&1 || fcitx5-remote -o >/dev/null 2>&1
		pkill -USR1 -x fcitx5 2>/dev/null
		say "Configuration reloaded" 2000 0
		;;
	esac
	exit 0
}

case "${1:-toggle}" in
config) do_config ;;
*) do_toggle ;;
esac
IME
	chmod 755 /usr/local/bin/i3-everforest-ime
	register_file /usr/local/bin/i3-everforest-ime

	return 0
}

write_sysinfo() {
	# Two helpers for the bar's right-hand pills, matching the reference
	# layout: disk+CPU, and the P/V temperature readout.
	local si="/usr/local/bin/i3-everforest-sysinfo"
	cat >"${si}" <<'SYSINFO'
#!/bin/sh
# Memory and CPU usage for the bar.
mem=$(awk '/^MemTotal:/{t=$2} /^MemAvailable:/{a=$2} END{if(t>0) printf "%d", (t-a)*100/t; else print 0}' /proc/meminfo)
# Instantaneous CPU load: sample /proc/stat twice 0.3s apart and use the
# delta. Reading it once gives the average since boot, which barely moves and
# looks like a frozen widget.
cpu=$(
	a=$(awk '/^cpu /{t=0; for(i=2;i<=NF;i++) t+=$i; printf "%s %s", t, $5}' /proc/stat)
	sleep 0.3
	b=$(awk '/^cpu /{t=0; for(i=2;i<=NF;i++) t+=$i; printf "%s %s", t, $5}' /proc/stat)
	awk -v a="$a" -v b="$b" 'BEGIN{
		split(a, x, " "); split(b, y, " ");
		dt = y[1] - x[1]; di = y[2] - x[2];
		if (dt <= 0) { print 0; exit }
		printf "%d", (dt - di) * 100 / dt
	}'
)
[ -n "$mem" ] || mem=0
[ -n "$cpu" ] || cpu=0
# `--cpu` prints only the CPU figure, which the bar's line graph samples.
# The default output is the memory reading alone: CPU is shown as a graph,
# so printing its percentage as well would be noise.
if [ "${1:-}" = "--cpu" ]; then
	printf '%s\n' "$cpu"
	exit 0
fi
printf '%s %s%%\n' "" "$mem"
SYSINFO
	chmod 755 "${si}"
	register_file "${si}"

	local tp="/usr/local/bin/i3-everforest-temps"
	cat >"${tp}" <<'TEMPS'
#!/bin/sh
# CPU and GPU temperature for the bar.
read_temp() {
	for z in /sys/class/thermal/thermal_zone*/temp; do
		[ -r "$z" ] || continue
		v=$(cat "$z" 2>/dev/null) || continue
		[ -n "$v" ] && { echo $((v / 1000)); return 0; }
	done
	return 1
}
cpu=$(read_temp) || cpu="--"
gpu="--"
if command -v nvidia-smi >/dev/null 2>&1; then
	gpu=$(nvidia-smi --query-gpu=temperature.gpu --format=csv,noheader 2>/dev/null | head -1)
fi
[ -n "$gpu" ] || gpu="--"
printf ' P/V %s°  %s°\n' "$cpu" "$gpu"
TEMPS
	chmod 755 "${tp}"
	register_file "${tp}"
	return 0
}

write_input() {
	# X11 has no sway-style `input` blocks, so the same device settings are
	# applied with xinput/setxkbmap at session start:
	#   touchpad  - tap to click, natural scrolling, disable while typing
	#   keyboard  - Caps Lock acts as Ctrl (xkb option ctrl:nocaps)
	# The script is idempotent and silent when a device is absent (a desktop
	# has no touchpad), so it can run unconditionally from i3's autostart.
	local dest="/usr/local/bin/i3-everforest-input"
	cat >"${dest}" <<'INPUT'
#!/bin/sh
# Apply the rice's input-device settings on X11.
#
# sway expresses these as `input type:touchpad { ... }` and
# `input type:keyboard { xkb_options ctrl:nocaps }`; on X11 the equivalents
# are xinput properties and an XKB option. Every step is best-effort: a
# machine without a touchpad must not produce errors.

# --- Caps Lock as Ctrl -------------------------------------------------------
# ctrl:nocaps is the same XKB option sway's xkb_options uses. setxkbmap
# replaces the whole layout, so the current one is preserved.
if command -v setxkbmap >/dev/null 2>&1; then
	cur_layout=$(setxkbmap -query 2>/dev/null | sed -n 's/^layout: *//p')
	cur_variant=$(setxkbmap -query 2>/dev/null | sed -n 's/^variant: *//p')
	cur_options=$(setxkbmap -query 2>/dev/null | sed -n 's/^options: *//p')

	# Keep any options that are already set, but never duplicate ctrl:nocaps.
	opts="ctrl:nocaps"
	case ",${cur_options}," in
	*,ctrl:nocaps,*) opts="${cur_options}" ;;
	*) [ -n "${cur_options}" ] && opts="${cur_options},ctrl:nocaps" ;;
	esac

	if [ -n "${cur_layout}" ]; then
		if [ -n "${cur_variant}" ]; then
			setxkbmap -layout "${cur_layout}" -variant "${cur_variant}" \
				-option "${opts}" >/dev/null 2>&1 || true
		else
			setxkbmap -layout "${cur_layout}" -option "${opts}" \
				>/dev/null 2>&1 || true
		fi
	else
		setxkbmap -option "${opts}" >/dev/null 2>&1 || true
	fi
fi

# --- touchpad ---------------------------------------------------------------
# xinput lists devices by name; a device is a touchpad when it exposes the
# libinput "Tapping Enabled" property.
if command -v xinput >/dev/null 2>&1; then
	xinput list --name-only 2>/dev/null | while IFS= read -r dev; do
		[ -n "$dev" ] || continue
		props=$(xinput list-props "$dev" 2>/dev/null) || continue
		case "$props" in
		*"Tapping Enabled"*) ;;
		*) continue ;;   # not a touchpad
		esac
		# tap to click
		xinput set-prop "$dev" "libinput Tapping Enabled" 1 >/dev/null 2>&1 || \
			xinput set-prop "$dev" "Tapping Enabled" 1 >/dev/null 2>&1 || true
		# natural scrolling
		xinput set-prop "$dev" "libinput Natural Scrolling Enabled" 1 \
			>/dev/null 2>&1 || \
			xinput set-prop "$dev" "Natural Scrolling Enabled" 1 \
			>/dev/null 2>&1 || true
		# disable-while-typing (dwt)
		xinput set-prop "$dev" "libinput Disable While Typing Enabled" 1 \
			>/dev/null 2>&1 || true
	done
fi

exit 0
INPUT
	chmod 755 "${dest}"
	register_file "${dest}"
	return 0
}

write_network() {
	# Waybar's native `network` module picks one of three glyphs:
	#   wifi         \uf1eb
	#   ethernet     \uf09e
	#   disconnected \uf00d
	# This helper reproduces that decision so the bar can render the same
	# thing on X11 without a native module.
	local dest="/usr/local/bin/i3-everforest-network"
	cat >"${dest}" <<'NET'
#!/bin/sh
# Network glyph for the bar: wifi, ethernet, or the no-connection cross.
export LC_ALL=C

WIFI='\357\207\253'      # U+F1EB wifi
ETH='\357\202\236'       # U+F09E ethernet
OFF='\357\200\215'       # U+F00D no connection

# While a connection is being established the helper touches this flag; the bar
# then renders a spinner instead of the static glyph.
STATE_DIR="${XDG_RUNTIME_DIR:-/run/user/$(id -u 2>/dev/null || echo 0)}"
BUSY_FLAG="${STATE_DIR:-/tmp}/i3-everforest-wifi-busy"
if [ -e "${BUSY_FLAG}" ]; then
	# Braille spinner, eight frames. The frame is chosen from the clock so the
	# helper stays stateless.
	now=$(date +%s%N 2>/dev/null || echo 0)
	idx=$(( (now / 130000000) % 8 ))
	case "${idx}" in
	0) f='\357\240\213' ;; 1) f='\357\240\231' ;;
	2) f='\357\240\271' ;; 3) f='\357\240\270' ;;
	4) f='\357\240\274' ;; 5) f='\357\240\264' ;;
	6) f='\357\240\246' ;; *) f='\357\240\247' ;;
	esac
	printf '%b\n' "${f}"
	exit 0
fi

# Decide which glyph to show. waybar's own module reports "disconnected" only
# when there is genuinely no link, and a desktop rice on a laptop is almost
# always on wifi - so the default is the wifi glyph and the cross is reserved
# for a real, detected disconnection.

# Decide from the *default route*, which is the interface traffic actually
# uses. nmcli is a poor proxy: a card can be marked `unmanaged` (or be driven
# by iwd/wpa_supplicant directly) while still carrying all the traffic.
default_dev() {
	ip route show default 2>/dev/null | awk '/^default/{
		for (i = 1; i <= NF; i++) if ($i == "dev") { print $(i+1); exit }
	}'
}

is_wireless() {
	[ -n "$1" ] || return 1
	[ -d "/sys/class/net/$1/wireless" ] || [ -d "/sys/class/net/$1/phy80211" ]
}

DEV=$(default_dev)
if [ -n "${DEV}" ]; then
	if is_wireless "${DEV}"; then
		printf '%b\n' "${WIFI}"
	else
		printf '%b\n' "${ETH}"
	fi
	exit 0
fi

# No default route: fall back to NetworkManager's opinion.
if command -v nmcli >/dev/null 2>&1; then
	state=$(nmcli -t -f STATE general 2>/dev/null)
	case "${state}" in
	connected*)
		if nmcli -t -f DEVICE,TYPE,STATE device 2>/dev/null |
			grep -q ':wifi:connected'; then
			printf '%b\n' "${WIFI}"
		else
			printf '%b\n' "${ETH}"
		fi
		exit 0
		;;
	esac
fi

# No NetworkManager: read the kernel. A machine with a wireless interface is
# treated as wifi-first, which is what this rice assumes.
have_wifi=0; wifi_up=0; wired_up=0
for dev in /sys/class/net/*; do
	[ -e "$dev" ] || continue
	case "${dev##*/}" in
	lo) continue ;;
	esac
	if [ -d "${dev}/wireless" ] || [ -d "${dev}/phy80211" ]; then
		have_wifi=1
		[ "$(cat "${dev}/operstate" 2>/dev/null)" = "up" ] && wifi_up=1
	elif [ -e "${dev}/device" ] && [ ! -d "${dev}/wireless" ]; then
		[ "$(cat "${dev}/carrier" 2>/dev/null)" = "1" ] && wired_up=1
	fi
done

if [ "${wifi_up}" -eq 1 ]; then
	printf '%b\n' "${WIFI}"
elif [ "${wired_up}" -eq 1 ]; then
	printf '%b\n' "${ETH}"
elif [ "${have_wifi}" -eq 1 ]; then
	# A wireless card exists but is down: still the wifi glyph, because the
	# pill is the "network" button, not a link-state indicator.
	printf '%b\n' "${WIFI}"
else
	printf '%b\n' "${WIFI}"
fi
NET
	chmod 755 "${dest}"
	register_file "${dest}"
	return 0
}

write_brightness() {
	# A bar module that renders nothing shifts every control after it. A
	# helper keeps the pill in place: internal backlight first, then ddcutil
	# for external screens, then a RandR gamma change, then a dim glyph.
	local dest="/usr/local/bin/i3-everforest-brightness"
	cat >"${dest}" <<'BRIGHT'
#!/bin/sh
# Screen brightness for the bar pill.
# Order: internal backlight -> external monitor via ddcutil -> dimmed glyph.

set_backlight() {
	if [ -d /sys/class/backlight ] && command -v brightnessctl >/dev/null 2>&1; then
		dev=$(ls /sys/class/backlight | head -1)
		brightnessctl -d "$dev" set "$1" >/dev/null 2>&1 && return 0
	fi
	return 1
}

read_backlight() {
	[ -d /sys/class/backlight ] || return 1
	dev=$(ls /sys/class/backlight | head -1)
	cur=$(cat "/sys/class/backlight/$dev/brightness" 2>/dev/null)
	max=$(cat "/sys/class/backlight/$dev/max_brightness" 2>/dev/null)
	[ -n "$cur" ] && [ -n "$max" ] && [ "$max" -gt 0 ] || return 1
	echo $(( cur * 100 / max ))
}

read_ddc() {
	command -v ddcutil >/dev/null 2>&1 || return 1
	ddcutil getvcp 10 2>/dev/null | sed -n 's/.*current value = *\([0-9]*\).*/\1/p' | head -1
}

# X11 fallback: RandR brightness. Unlike sysfs/ddcutil this never fails
# silently - it is a software gamma change - so it always keeps the pill
# useful on a machine without a controllable backlight.
read_randr() {
	command -v xrandr >/dev/null 2>&1 || return 1
	v=$(xrandr --verbose 2>/dev/null | sed -n 's/^[[:space:]]*Brightness: *//p' | head -1)
	[ -n "$v" ] || return 1
	awk -v b="$v" 'BEGIN{printf "%d", b*100}'
}

set_randr() {
	command -v xrandr >/dev/null 2>&1 || return 1
	cur=$(read_randr) || cur=100
	case "$1" in
	+*) step=$(( ${1%\%+} )) ;;
	-*) step=$(( ${1%\%-} )) ;;
	*)  step=0 ;;
	esac
	if [ "$step" -eq 0 ]; then nxt=$cur; else nxt=$((cur + step)); fi
	[ "$nxt" -gt 100 ] && nxt=100
	[ "$nxt" -lt 10 ] && nxt=10
	val=$(awk -v n="$nxt" 'BEGIN{printf "%.2f", n/100}')
	for out in $(xrandr --query 2>/dev/null | awk '/ connected/{print $1}'); do
		xrandr --output "$out" --brightness "$val" >/dev/null 2>&1
	done
	return 0
}

case "$1" in
	up)
		set_backlight 5%+ && exit 0
		cur=$(read_ddc) && [ -n "$cur" ] && {
			nxt=$((cur + 10)); [ "$nxt" -gt 100 ] && nxt=100
			ddcutil setvcp 10 "$nxt" >/dev/null 2>&1
			exit 0
		}
		set_randr 10%+ && exit 0
		exit 0
		;;
	down)
		set_backlight 5%- && exit 0
		cur=$(read_ddc) && [ -n "$cur" ] && {
			nxt=$((cur - 10)); [ "$nxt" -lt 5 ] && nxt=5
			ddcutil setvcp 10 "$nxt" >/dev/null 2>&1
			exit 0
		}
		set_randr 10%- && exit 0
		exit 0
		;;
esac

p=$(read_backlight) || p=$(read_ddc) || p=$(read_randr)
if [ -n "$p" ]; then
	printf '%s \n' "$p"
else
	printf '\n'
fi
BRIGHT
	chmod 755 "${dest}"
	register_file "${dest}"
	return 0
}

write_volume() {
	# Polybar's pulseaudio module exposes only the sink, but the reference
	# shows speaker and microphone together in one pill, so print both here.
	local dest="/usr/local/bin/i3-everforest-volume"
	{
		printf '%s\n' '#!/bin/sh'
		printf '%s\n' '# Speaker and microphone level for the bar volume pill.'
		printf '%s\n' 'command -v pactl >/dev/null 2>&1 || { printf "\357\200\246 n/a\n"; exit 0; }'
		printf '%s\n' ''
		printf '%s\n' 'sink=$(pactl get-sink-volume @DEFAULT_SINK@ 2>/dev/null | grep -o "[0-9]\\+%" | head -1)'
		printf '%s\n' 'src=$(pactl get-source-volume @DEFAULT_SOURCE@ 2>/dev/null | grep -o "[0-9]\\+%" | head -1)'
		printf '%s\n' 'smute=$(pactl get-sink-mute @DEFAULT_SINK@ 2>/dev/null | grep -c yes)'
		printf '%s\n' 'rmute=$(pactl get-source-mute @DEFAULT_SOURCE@ 2>/dev/null | grep -c yes)'
		printf '%s\n' '[ -n "$sink" ] || sink="--"'
		printf '%s\n' '[ -n "$src" ] || src="--"'
		printf '%s\n' 'if [ "$smute" -eq 1 ]; then si="\357\200\246"; else si="\357\200\247"; fi'
		printf '%s\n' 'if [ "$rmute" -eq 1 ]; then mi="\357\204\261"; else mi="\357\204\260"; fi'
		printf '%s\n' 'printf "%s %b  %s %b\\n" "$sink" "$si" "$src" "$mi"'
	} >"${dest}"
	# The block above uses printf without a redirection on purpose built
	# strings only; the file itself is written by the surrounding >"${dest}".
	chmod 755 "${dest}"
	register_file "${dest}"
	return 0
}

write_picker() {
	# One icon, two jobs, chosen by mouse button:
	#   left  - full-screen screenshot to the clipboard (+ a file)
	#   right - drag a region, screenshot that to the clipboard
	# The colour dropper is a separate pill and takes a single click.
	#
	# X11 equivalent of grim/slurp/wl-copy: maim captures, slop selects the
	# region, xclip puts the PNG on the CLIPBOARD selection.
	# The clipboard owner itself: GTK advertises every image target at once,
	# which xclip cannot do (one target per process).
	cat >/usr/local/bin/i3-everforest-clip <<'CLIP'
#!/usr/bin/env python3
"""Hold the clipboard for an image or a string.

xclip serves a single target per process, so a screenshot copied as PNG only
appears in applications that ask for exactly image/png. A file manager asks for
image/bmp, and then "paste" looks empty. GTK can publish all the targets from
one owner, which is what this does.
"""
import os
import signal
import sys

import gi

gi.require_version("Gtk", "3.0")
gi.require_version("Gdk", "3.0")
gi.require_version("GdkPixbuf", "2.0")
from gi.repository import Gdk, GdkPixbuf, GLib, Gtk  # noqa: E402


def main():
    mode = sys.argv[1] if len(sys.argv) > 1 else "text"
    value = sys.argv[2] if len(sys.argv) > 2 else ""

    clip = Gtk.Clipboard.get(Gdk.SELECTION_CLIPBOARD)

    if mode == "text":
        clip.set_text(value, -1)
        Gtk.main()
        return 0

    # image: load once, publish as a pixbuf (GTK derives png/bmp/jpeg from it).
    try:
        pb = GdkPixbuf.Pixbuf.new_from_file(value)
    except Exception:
        return 1
    clip.set_image(pb)
    # Keep the file alive for as long as the clipboard holds it.
    Gtk.main()
    return 0


if __name__ == "__main__":
    signal.signal(signal.SIGTERM, lambda *_: Gtk.main_quit())
    sys.exit(main())
CLIP
	chmod 755 /usr/local/bin/i3-everforest-clip
	register_file /usr/local/bin/i3-everforest-clip
	local dest="/usr/local/bin/i3-everforest-shot"
	cat >"${dest}" <<'SHOT'
#!/bin/sh
# Screenshot helper behind the bar button.
#   i3-everforest-shot          full screen -> clipboard + file
#   i3-everforest-shot region   drag a region -> clipboard + file
# Every branch exits explicitly; falling through used to run a second capture.
export LC_ALL=C

notify() {
	if command -v notify-send >/dev/null 2>&1; then
		notify-send -a Everforest -t "${3:-2000}" "$1" "$2"
	fi
	# A detached screenshot is invisible otherwise; flash the bar.
	if command -v i3-msg >/dev/null 2>&1; then
		i3-msg -q 'mode "default"' >/dev/null 2>&1 || true
	fi
}

CLIP_HELPER="/usr/local/bin/i3-everforest-clip"

# Clipboard for images and colours.
#
# xclip serves exactly one target per process, so a PNG-only clipboard shows
# nothing when a file manager asks for image/bmp. This helper owns the
# clipboard from GTK and advertises every format a paste target might request.
copy_image() {
	"${CLIP_HELPER}" image "$1"
}



copy_text() {
	"${CLIP_HELPER}" text "$1"
}

fail() { notify "$1" "$2" 3000; exit 1; }


fail() { notify "$1" "$2" 3000; exit 1; }


# Save a capture to ~/Pictures/Screenshots. The clipboard is deliberately not
# touched: a saved file can be dragged or opened, and silently overwriting the
# clipboard was never wanted.
save_shot() {
	_src="$1"
	dir="${XDG_PICTURES_DIR:-$HOME/Pictures}/Screenshots"
	# Sets the global `file` so the caller can hand it to an editor.
	file=""
	if mkdir -p "${dir}" 2>/dev/null; then
		file="${dir}/$(date +%Y-%m-%d_%H-%M-%S).png"
		cp -f "${_src}" "${file}" 2>/dev/null || file=""
	fi
	if [ -n "${file}" ]; then
		# Report the directory rather than the full path: the notification is
		# narrow, and the timestamp alone is enough to identify the file.
		notify "Screenshot" "Saved to ~/Pictures/Screenshots/$(basename "${file}")"
		exit 0
	fi
	fail "Screenshot" "could not save the capture to ${dir}"
}

# maim is the X11 screenshot tool; scrot/import are the fallbacks that ship
# with a stock X install.
capture() {
	# capture <output-file> [geometry]
	if command -v maim >/dev/null 2>&1; then
		if [ -n "${2:-}" ]; then
			maim -u -g "$2" "$1" 2>/dev/null
		else
			maim -u "$1" 2>/dev/null
		fi
		return $?
	fi
	if command -v scrot >/dev/null 2>&1; then
		if [ -n "${2:-}" ]; then
			scrot -a "$2" "$1" 2>/dev/null
		else
			scrot "$1" 2>/dev/null
		fi
		return $?
	fi
	if command -v import >/dev/null 2>&1; then
		if [ -n "${2:-}" ]; then
			import -window root -crop "$2" "$1" 2>/dev/null
		else
			import -window root "$1" 2>/dev/null
		fi
		return $?
	fi
	return 127
}

tmp=$(mktemp /tmp/shot-XXXXXX.png) || exit 1
trap 'rm -f "${tmp}"' EXIT INT TERM

# Modes, matching the three bindings the sway config uses:
#   full | clip          full screen -> clipboard + file
#   region               drag a region -> clipboard + file
#   region-clip          drag a region -> clipboard only  ($mod+Print)
#   region-swappy        drag a region -> clipboard, then swappy ($mod+Shift+Print)
mode="${1:-full}"

grab_region() {
	if ! command -v slop >/dev/null 2>&1; then
		fail "Screenshot" "slop is not installed"
	fi
	# Say that the crosshair is armed before blocking on the drag.
	notify "Screenshot" "Drag to select an area" 2500
	# slop prints "WxH+X+Y"; maim takes exactly that geometry.
	# slop only accepts %x %y %w %h %g %i %c after a '%'; the old
	# '%wx%h%+X%+Y' errored out and region capture never ran.
	set -- $(slop -f '%w %h %x %y' 2>/dev/null) || exit 0
	[ $# -eq 4 ] || exit 0
	geom="${1}x${2}+${3}+${4}"
	[ -n "${geom}" ] || exit 0
	capture "${tmp}" "${geom}" || fail "Screenshot" "capture failed"
}

case "${mode}" in
region|region-clip|region-swappy)
	grab_region
	;;
*)
	capture "${tmp}" || fail "Screenshot" "capture failed (is maim installed?)"
	;;
esac

# Every mode saves to ~/Pictures/Screenshots. The clipboard-only modes existed
# to mirror the Wayland recipe (grim - | wl-copy), but a saved file is what is
# actually useful here.
save_shot "${tmp}"

# swappy is an editor: hand it the saved file when that mode was asked for.
if [ "${mode}" = "region-swappy" ]; then
	if command -v swappy >/dev/null 2>&1 && [ -n "${file}" ]; then
		# swappy keeps reading the file, so it must outlive the trap.
		trap - EXIT INT TERM
		swappy -f "${file}" >/dev/null 2>&1 &
	else
		notify "Screenshot" "swappy is not installed" 3000
	fi
fi
SHOT
	chmod 755 "${dest}"
	register_file "${dest}"

	# Single-click colour dropper. slop's -p mode picks one pixel and returns
	# as soon as the button is released; the rectangle mode is what made it
	# feel like a drag selection.
	local pck="/usr/local/bin/i3-everforest-pick"
	cat >"${pck}" <<'PICK'
#!/bin/sh
# Pick the colour under a single click and copy its hex value.
#
# A GTK overlay is the wrong tool here: i3 tiles a normal window, so the overlay
# did not cover the screen and sampled the wrong place. Instead ask for a 1x1
# selection with an existing tool and read that pixel - no window of our own.
export LC_ALL=C

say() {
	command -v notify-send >/dev/null 2>&1 &&
		notify-send -a Everforest -t "${2:-2500}" "Colour pick" "$1"
	exit "${3:-0}"
}

# Announce before the selector grabs the screen.
say "Click the colour you want" 2200 0 &
sleep 0.3

tmp=$(mktemp /tmp/pick-XXXXXX.png) || exit 1
trap 'rm -f "${tmp}"' EXIT INT TERM

# slop with a 1x1 minimum: any click (or a hair of drag) returns a geometry.
geom=""
if command -v slop >/dev/null 2>&1; then
	geom=$(slop -t 0 -f '%x %y' 2>/dev/null) || geom=""
fi

if [ -n "${geom}" ]; then
	x=${geom% *}
	y=${geom#* }
	if command -v maim >/dev/null 2>&1; then
		maim -u -g "1x1+${x}+${y}" "${tmp}" 2>/dev/null
	fi
fi

# Fallback: maim's own region selector (also a single drag).
if [ ! -s "${tmp}" ]; then
	if command -v maim >/dev/null 2>&1; then
		maim -u -s -b 1 "${tmp}" 2>/dev/null || say "Colour pick" "selection cancelled" 2000 1
	fi
fi

[ -s "${tmp}" ] || say "Colour pick" "could not read that pixel" 3000 1

if command -v magick >/dev/null 2>&1; then CONV=magick
elif command -v convert >/dev/null 2>&1; then CONV=convert
else say "Colour pick" "ImageMagick is not installed" 3000 1; fi

hex=$("${CONV}" "${tmp}" -format '%[hex:p{0,0}]' info: 2>/dev/null |
	tr -d '\n' | tr 'A-F' 'a-f' | cut -c1-6)
[ -n "${hex}" ] || say "Colour pick" "could not read the pixel" 3000 1

# Text on the clipboard through the shared owner so it survives this process.
if command -v xclip >/dev/null 2>&1; then
	printf '#%s' "${hex}" | xclip -selection clipboard 2>/dev/null &&
		say "Copied #${hex} to the clipboard" 2500 0
fi
say "Colour #${hex} (clipboard unavailable)" 3000 1
PICK
	chmod 755 "${pck}"
	register_file "${pck}"
	return 0
}

# ---------------------------------------------------------------------
#  Lock screen, idle handling and power menu (X11)
# ---------------------------------------------------------------------
write_lock_and_power() {
	# i3lock takes a PNG or a flat colour. The wallpaper as the lock screen
	# is what the reference shows, so prefer it; fall back to the flat
	# Everforest background when there is no wallpaper yet.
	local lock="/usr/local/bin/i3-everforest-lock"
	cat >"${lock}" <<'LOCK'
#!/bin/sh
# Lock the X session.
#
# i3lock cannot scale a JPEG, so the wallpaper is converted to a PNG that
# matches the current screen size and cached next to it. A flat Everforest
# background is the fallback, so the lock screen never comes up white.
wall="${XDG_DATA_HOME:-$HOME/.local/share}/i3-everforest/wallpaper.jpg"
cache="${XDG_CACHE_HOME:-$HOME/.cache}/i3-everforest/lock.png"

# Already locked? i3lock refuses a second instance, which is fine.
pgrep -x i3lock >/dev/null 2>&1 && exit 0

if [ -f "${wall}" ]; then
	mkdir -p "$(dirname "${cache}")" 2>/dev/null
	if [ ! -s "${cache}" ] || [ "${wall}" -nt "${cache}" ]; then
		# i3lock needs a PNG at (close to) the screen size. Asking X for the
		# dimensions can fail; an empty argument would make convert error out
		# and the lock screen fall back to a flat colour, so it is checked.
		dims=""
		if command -v xdpyinfo >/dev/null 2>&1; then
			dims=$(xdpyinfo 2>/dev/null |
				awk '/dimensions:/{split($2,a,"x"); if (a[1] && a[2]) print a[1]"x"a[2]; exit}')
		fi
		[ -n "${dims}" ] || dims="1920x1080"
		if command -v convert >/dev/null 2>&1; then
			# Fit the wallpaper to the screen, then dim it so the indicator
			# stays readable over a bright image. -modulate is
			# brightness,saturation,hue - the dimming goes in the *first*
			# component; using the third would rotate the hue instead and
			# turned the lock screen magenta.
			convert "${wall}" -resize "${dims}" -modulate 55,100,100 "${cache}" \
				>/dev/null 2>&1 || rm -f "${cache}"
		fi
	fi
fi

# Load the palette written by the installer, then hand over to i3lock.
icons="$HOME/.config/i3/i3lock-color.xresources"
if [ -f "${icons}" ] && command -v xrdb >/dev/null 2>&1; then
	xrdb -merge "${icons}" >/dev/null 2>&1 || true
fi

lock() {
	if [ -s "${cache}" ]; then
		i3lock -n -i "${cache}" -e -f
	else
		i3lock -n -c 1e2326 -e -f
	fi
}

lock
exit 0
LOCK
	chmod 755 "${lock}"
	register_file "${lock}"

	# Idle handling: DISABLED (2026-11-03). The session does not lock, blank or
	# sleep on its own; the screen is kept on. i3-everforest-lock still runs on
	# $mod+Escape, so manual locking keeps working.
	# Original behaviour (lock at 10 min, blank at 15 min, lock on resume) is
	# preserved as a commented block at the end of the generated script.
	local idle="/usr/local/bin/i3-everforest-idle"
	cat >"${idle}" <<'IDLE'
#!/bin/sh
# Idle handling — DISABLED at the user's request (2026-11-03).
#
# Previously this script started xss-lock (lock before suspend) and enforced
# two idle stages with xprintidle: lock at 600s, DPMS power-off at 900s.
# All of that is gone: the session no longer locks itself, no longer blanks,
# and no longer sleeps. The screen is kept on unconditionally.
#
# Manual locking still works: $mod+Escape runs i3-everforest-lock.
# To restore the old behaviour, reinstall i3-everforest or see the commented
# block at the bottom of this file.

if command -v xset >/dev/null 2>&1; then
	# No X screensaver blanking.
	xset s off >/dev/null 2>&1
	xset s noblank >/dev/null 2>&1
	# Power the display back on first, in case a previous session left it in a
	# DPMS-off state, and only then disable DPMS. Order matters: `xset dpms
	# force on` re-arms DPMS, so a `-dpms` issued before it gets undone and the
	# monitor would blank again once the timeout elapsed.
	xset dpms 0 0 0 >/dev/null 2>&1
	xset dpms force on >/dev/null 2>&1
	xset -dpms >/dev/null 2>&1
fi

# Hard-block suspend/hibernate for the lifetime of this session, so nothing
# (suspend key, logind idle policy, the power menu, another user's command)
# can put the machine to sleep. The lock is released automatically at logout.
if command -v systemd-inhibit >/dev/null 2>&1; then
	# i3 restart re-runs this script while the previous inhibitor is still
	# alive; skip instead of stacking a second identical lock.
	if pgrep -f "systemd-inhibit.*--who=i3-everforest" >/dev/null 2>&1; then
		exit 0
	fi
	exec systemd-inhibit \
		--what=sleep \
		--who=i3-everforest \
		--why="Suspend disabled: screen kept on" \
		--mode=block \
		sleep infinity
fi

exit 0

# ---------------------------------------------------------------------------
# Old behaviour, kept for reference:
#
# if command -v xss-lock >/dev/null 2>&1; then
# 	xss-lock --transfer-sleep-lock -- "${lockcmd}" >/dev/null 2>&1 &
# fi
# xset s 600 600
# xset dpms 900 900 900
# ... plus the xprintidle loop that ran the locker at 600s and
# `xset dpms force off` at 900s.
# ---------------------------------------------------------------------------
IDLE
	chmod 755 "${idle}"
	register_file "${idle}"

	# Power menu: rofi list -> real actions. Session-scoped only when the
	# systemd logind interface is there, and it asks before shutting down.
	local pwr="/usr/local/bin/i3-everforest-powermenu"

	# The reference uses wlogout for this, which is Wayland-only (it links
	# gtk-layer-shell). The replacement paints the same full-screen grid with
	# plain GTK: a dark scrim, one large tile per action, Esc to dismiss.
	cat >/usr/local/bin/i3-everforest-powermenu-ui <<'PWRUI'
#!/usr/bin/env python3
"""Full-screen power menu (wlogout look) for X11."""
import subprocess
import sys

import gi

gi.require_version("Gtk", "3.0")
gi.require_version("Gdk", "3.0")
from gi.repository import Gdk, GLib, Gtk  # noqa: E402

SCRIM = (0.055, 0.067, 0.071, 0.72)   # translucent: picom blurs it

# Nerd Font glyphs, the same set the bar uses:
#   U+F023 lock  U+F2F5 sign-out  U+F186 moon  U+F021 refresh  U+F011 power
ACTIONS = [
    ("Lock", "\uf023", ["/usr/local/bin/i3-everforest-lock"]),
    ("Log out", "\uf2f5", ["i3-msg", "exit"]),
    ("Suspend", "\uf186", ["sh", "-c",
                            "/usr/local/bin/i3-everforest-lock; "
                            "sleep 1; systemctl suspend"]),
    ("Reboot", "\uf021", ["systemctl", "reboot"]),
    ("Shutdown", "\uf011", ["systemctl", "poweroff"]),
]

# A GtkButton is used for each tile: it lays its child out correctly and honours
# min-width/min-height. Selectors are written so the icon rule cannot be beaten
# by a generic `.tile label` rule (equal specificity was collapsing the glyph to
# the label's 14px).
CSS = b"""
.tile {
  background-color: rgba(30, 35, 38, 0.88);
  background-image: none;
  border: 1px solid #3a4044;
  border-radius: 10px;
  padding: 26px 8px 18px 8px;
  min-width: 150px;
  min-height: 168px;
  box-shadow: none;
  text-shadow: none;
  outline-style: none;
}
.tile:hover {
  background-color: #2f3336;
  border-color: #b9ff66;
}
.tile .tile-icon {
  color: #d3c6aa;
  font-size: 52px;
  min-height: 64px;
}
.tile:hover .tile-icon {
  color: #b9ff66;
}
.tile .tile-text {
  color: #d3c6aa;
  font-size: 14px;
  font-weight: 700;
  margin-top: 12px;
}
.tile:hover .tile-text {
  color: #fffbef;
}
"""


def spawn(cmd):
    subprocess.Popen(cmd, stdout=subprocess.DEVNULL,
                     stderr=subprocess.DEVNULL, start_new_session=True)


def main():
    win = Gtk.Window()
    win.set_decorated(False)
    win.set_skip_taskbar_hint(True)
    win.set_skip_pager_hint(True)
    win.set_keep_above(True)
    win.fullscreen()

    screen = win.get_screen()
    visual = screen.get_rgba_visual()
    if visual is not None and screen.is_composited():
        win.set_visual(visual)
    win.set_app_paintable(True)

    prov = Gtk.CssProvider()
    prov.load_from_data(CSS)
    Gtk.StyleContext.add_provider_for_screen(
        screen, prov, Gtk.STYLE_PROVIDER_PRIORITY_APPLICATION)

    scrim = Gtk.EventBox()
    scrim.override_background_color(Gtk.StateFlags.NORMAL, Gdk.RGBA(*SCRIM))
    win.add(scrim)

    grid = Gtk.Grid()
    grid.set_row_spacing(22)
    grid.set_column_spacing(22)
    grid.set_halign(Gtk.Align.CENTER)
    grid.set_valign(Gtk.Align.CENTER)
    scrim.add(grid)

    def on_click(cmd):
        def handler(_b):
            spawn(cmd)
            Gtk.main_quit()
        return handler

    for i, (text, glyph, cmd) in enumerate(ACTIONS):
        tile = Gtk.Button()
        tile.get_style_context().add_class("tile")
        tile.set_relief(Gtk.ReliefStyle.NONE)
        tile.set_can_focus(False)

        inner = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=0)
        icon = Gtk.Label(label=glyph)
        icon.get_style_context().add_class("tile-icon")
        icon.set_xalign(0.5)
        label = Gtk.Label(label=text)
        label.get_style_context().add_class("tile-text")
        label.set_xalign(0.5)
        inner.pack_start(icon, True, True, 0)
        inner.pack_start(label, False, False, 0)
        tile.add(inner)

        tile.connect("clicked", on_click(cmd))
        grid.attach(tile, i, 0, 1, 1)

    def on_key(_w, ev):
        if ev.keyval == Gdk.KEY_Escape:
            Gtk.main_quit()
            return True
        return False

    win.connect("key-press-event", on_key)
    def _cleanup(*_a):
        try:
            os.unlink(lock)
        except Exception:
            pass
        Gtk.main_quit()

    win.connect("destroy", _cleanup)
    GLib.timeout_add_seconds(60, lambda: (Gtk.main_quit(), False)[1])
    win.show_all()
    Gtk.main()
    return 0


if __name__ == "__main__":
    sys.exit(main())
PWRUI
	chmod 755 /usr/local/bin/i3-everforest-powermenu-ui
	register_file /usr/local/bin/i3-everforest-powermenu-ui

	cat >"${pwr}" <<'PWR'
#!/bin/sh
# Power menu for the bar's red button and for Mod+Shift+E.
#
# wlogout (the reference's power menu) is Wayland-only, so this launches the
# GTK equivalent, which draws the same full-screen grid on X11.
export LC_ALL=C

exec /usr/local/bin/i3-everforest-powermenu-ui
PWR
	chmod 755 "${pwr}"
	register_file "${pwr}"
	return 0
}


write_bash_extras() {
	local rc="${HOME_DIR}/.bashrc"
	local marker_begin="# >>> i3-everforest >>>"
	local marker_end="# <<< i3-everforest <<<"

	[[ -f "${rc}" ]] || touch "${rc}"
	chown_user "${rc}"

	if grep -qF "${marker_begin}" "${rc}" 2>/dev/null; then
		ui_dim "bash prompt already configured in ${rc}"
		return 0
	fi

	backup_path "${rc}"
	{
		printf '\n%s\n' "${marker_begin}"
		cat <<'BASHRC'
# Everforest prompt (i3 rice) - remove by running the installer --uninstall
__ef_prompt() {
	local reset=$'\033[0m'
	local green=$'\033[38;2;167;192;128m'
	local blue=$'\033[38;2;127;187;179m'
	local grey=$'\033[38;2;122;132;120m'
	local lime=$'\033[38;2;185;255;102m'
	local yellow=$'\033[38;2;219;188;127m'
	# \w shows the working directory (~ for $HOME), the yellow plus the path so
	# it stands out from the user@host part.
	PS1="${green}╭─${lime}\$${reset}${green}\u${reset}${blue}@\h${reset} ${yellow}\w${reset} ${grey}\t${reset}\n${green}╰─${lime}\$${reset} "
}
PROMPT_COMMAND="__ef_prompt${PROMPT_COMMAND:+; $PROMPT_COMMAND}"
export EDITOR="${EDITOR:-nano}"
BASHRC
		printf '%s\n' "${marker_end}"
	} >>"${rc}"
	chown_user "${rc}"
	register_file "${rc}"
	ui_ok "Everforest prompt added to ${rc}"
}

# ---------------------------------------------------------------------
# 75-session.sh
# ---------------------------------------------------------------------
# =====================================================================
#  Login session (display manager entry)
# ---------------------------------------------------------------------
#  i3 is an X11 window manager, so the session entry belongs in
#  /usr/share/xsessions and is started through the X session machinery
#  (startx / the display manager's Xsession). The launcher exports the
#  identity variables every desktop-aware program keys off.
# =====================================================================

SESSION_DIR="/usr/share/xsessions"
SESSION_LAUNCHER="/usr/local/bin/i3-everforest-session"

session_write_launcher() {
	local dest="${SESSION_LAUNCHER}"
	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then ui_dim "would write ${dest}"; return 0; fi

	if [[ -e "${dest}" ]]; then backup_path "${dest}"; fi
	cat >"${dest}" <<'LAUNCH'
#!/bin/sh
# Launcher for the i3 (Everforest) X11 session, used by the xsessions entry.
#
# It runs i3 inside a D-Bus session bus so notifications, portals, pulseaudio
# and NetworkManager all reach the same bus, then hands the session over to
# i3. Everything it exports is what GTK/Qt/portal consumers expect on X11.

LOG="/tmp/i3-everforest-session.log"
: >"${LOG}" 2>/dev/null || LOG=/dev/null

say() { printf '%s\n' "$*" | tee -a "${LOG}" >&2; }

export XDG_CURRENT_DESKTOP=i3
export XDG_SESSION_DESKTOP=i3
export XDG_SESSION_TYPE=x11
export DESKTOP_SESSION=i3
export MOZ_ENABLE_WAYLAND=0
export QT_QPA_PLATFORMTHEME=gtk3
export _JAVA_AWT_WM_NONREPARENTING=1

# A logind session provides /run/user/<uid>. If pam_systemd did not run (for
# example because libpam-systemd was never installed) every XDG consumer
# falls back to a world-readable /tmp and the session comes up half broken.
# Create it so the session can at least run, and record the diagnosis.
UID_NUM="$(id -u)"
if [ -z "${XDG_RUNTIME_DIR:-}" ]; then
	export XDG_RUNTIME_DIR="/run/user/${UID_NUM}"
fi
if [ ! -d "${XDG_RUNTIME_DIR}" ]; then
	say "warning: ${XDG_RUNTIME_DIR} is missing (no logind session?)"
	if mkdir -p "${XDG_RUNTIME_DIR}" 2>/dev/null; then
		chmod 700 "${XDG_RUNTIME_DIR}"
		say "warning: created ${XDG_RUNTIME_DIR} as a fallback"
	else
		mkdir -p "/tmp/runtime-${UID_NUM}" 2>/dev/null &&
			chmod 700 "/tmp/runtime-${UID_NUM}" 2>/dev/null &&
			export XDG_RUNTIME_DIR="/tmp/runtime-${UID_NUM}"
		say "warning: falling back to ${XDG_RUNTIME_DIR}"
	fi
fi

say "starting i3 (DISPLAY=${DISPLAY:-unset}, XDG_RUNTIME_DIR=${XDG_RUNTIME_DIR})"

# i3 itself, with the Everforest config. -a updates the X cursor to the
# theme's arrow, which some clients otherwise leave as an X cross.
if [ -x /usr/bin/dbus-run-session ]; then
	exec /usr/bin/dbus-run-session -- /usr/bin/i3 >>"${LOG}" 2>&1
fi
exec /usr/bin/i3 >>"${LOG}" 2>&1
LAUNCH
	chmod 755 "${dest}"
	register_file "${dest}"
	ui_ok "wrote ${dest}"
	return 0
}

session_install() {
	ui_hdr "Login session"
	local dest="${SESSION_DIR}/${SESSION_FILE}"
	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then ui_dim "would write ${dest}"; return 0; fi

	mkdir -p "${SESSION_DIR}"
	# A leftover Wayland entry from the sway installer would keep offering a
	# session that no longer exists; remove it when it is clearly ours.
	if [[ -f "/usr/share/wayland-sessions/${SESSION_FILE}" ]]; then
		rm -f "/usr/share/wayland-sessions/${SESSION_FILE}" 2>/dev/null || true
	fi

	if [[ -e "${dest}" ]]; then backup_path "${dest}"; fi
	cat >"${dest}" <<'DESKTOP'
[Desktop Entry]
Name=i3 (Everforest)
Comment=i3 with the Everforest rice (X11)
Exec=/usr/local/bin/i3-everforest-session
TryExec=/usr/bin/i3
Type=Application
DesktopNames=i3
Keywords=x11;tiling;window manager;i3;
DESKTOP
	chmod 644 "${dest}"
	register_file "${dest}"
	session_write_launcher
	ui_ok "wrote ${dest}"

	# The session list is cached by some greeters; refresh it.
	if have update-desktop-database; then
		update-desktop-database "${SESSION_DIR}" >/dev/null 2>&1 || true
	fi

	local dm=""
	have lightdm && dm="lightdm"
	if [[ -z "${dm}" ]] && have gdm3; then dm="gdm3"; fi
	if [[ -z "${dm}" ]] && have sddm; then dm="sddm"; fi
	if [[ -z "${dm}" ]] && have greetd; then dm="greetd"; fi
	if [[ -n "${dm}" ]]; then
		ui_dim "display manager detected: ${dm} - pick 'i3 (Everforest)' at login"
	else
		ui_dim "no display manager yet: enable the 'sddm' component to get a greeter"
		ui_dim "from a TTY you can also run: startx i3"
	fi
}

# ---------------------------------------------------------------------
#  Optional: install a display manager when the machine boots to a TTY
# ---------------------------------------------------------------------
session_maybe_install_dm() {
	((SESSION)) || return 0
	local active; active="$(systemctl get-default 2>/dev/null || echo unknown)"
	if [[ "${active}" == "graphical.target" ]]; then return 0; fi
	if have lightdm || have gdm3 || have sddm || have greetd; then return 0; fi
	ui_dim "no display manager installed - the session will be available after installing one"
}

session_enable_dm() {
	((SESSION)) || return 0
	local dm=""
	have lightdm && dm="lightdm"
	if [[ -z "${dm}" ]] && have gdm3; then dm="gdm3"; fi
	if [[ -z "${dm}" ]] && have sddm; then dm="sddm"; fi
	if [[ -z "${dm}" ]] && have greetd; then dm="greetd"; fi
	if [[ -z "${dm}" ]]; then return 0; fi
	if systemctl is-enabled "${dm}" >/dev/null 2>&1; then return 0; fi
	ui_step "enabling ${dm} so you can pick the i3 session at login"
	systemctl enable "${dm}" >>"${LOG_FILE}" 2>&1 || ui_warn "could not enable ${dm}"
}

# ---------------------------------------------------------------------
# 77-sddm.sh
# ---------------------------------------------------------------------
# =====================================================================
#  Display manager: SDDM + SilentSDDM theme
# ---------------------------------------------------------------------
#  A minimal Debian install boots to a TTY with no greeter, so there is
#  no way to pick the i3 session. This module installs SDDM, turns it
#  into the system default (graphical.target), and applies the SilentSDDM
#  theme with its stock configuration. SDDM runs its greeter on X11, which
#  is exactly the server the i3 session needs.
#
#  Everything needed for the greeter is pulled in here too: SDDM's Qt6
#  QML runtime is not a dependency of sddm itself, so a bare install
#  would show a black screen instead of the theme.
# =====================================================================

SDDM_THEME_NAME="silent"
SDDM_THEME_DIR="/usr/share/sddm/themes/${SDDM_THEME_NAME}"
SDDM_CONF="/etc/sddm.conf"
SDDM_CONF_D="/etc/sddm.conf.d"
SDDM_PROFILE="/etc/sddm.conf.d/10-i3-everforest.conf"
SDDM_XSESSION_WRAPPER="/usr/local/bin/i3-everforest-session"

# Qt6 QML modules imported by SilentSDDM's Main.qml and components/.
# Missing any one of them makes the greeter fall back to a black screen.
PKGS_SDDM=(
	sddm
	qml6-module-qtquick
	qml6-module-qtquick-controls
	qml6-module-qtquick-layouts
	qml6-module-qtquick-window
	qml6-module-qtquick-templates
	qml6-module-qtquick-shapes
	qml6-module-qtquick-effects
	qml6-module-qtquick-particles
	qml6-module-qtqml-workerscript
	qml6-module-qt-labs-platform
	qml6-module-qtmultimedia
	qml6-module-qtquick-virtualkeyboard
	qt6-virtualkeyboard-plugin
	libqt6svg6
	qt6-svg-plugins
	qt6-image-formats-plugins
	xserver-xorg
	xserver-xorg-video-all
	xserver-xorg-video-fbdev
	xserver-xorg-input-libinput
	x11-xserver-utils
	x11-utils
	xauth
	dbus-x11
	# The X11 greeter is what SDDM starts by default; keep the backend and
	# an X terminal emulator available so its fail-safe greeter works too.
	xterm
	hicolor-icon-theme
	shared-mime-info
	desktop-file-utils
)

# ---------------------------------------------------------------------
#  The greeter runs as the `sddm` user, so it must be able to read the
#  theme. Files land as root:root 644/755, which is fine; the check below
#  catches the case where a umask made them unreadable.
# ---------------------------------------------------------------------
sddm_theme_ok() {
	[[ -f "${SDDM_THEME_DIR}/Main.qml" ]] || return 1
	[[ -f "${SDDM_THEME_DIR}/metadata.desktop" ]] || return 1
	runuser -u sddm -- test -r "${SDDM_THEME_DIR}/Main.qml" 2>/dev/null || return 1
	return 0
}

sddm_pin_stock_config() {
	# The upstream theme selects its preset through metadata.desktop.
	# "default.conf" is SilentSDDM's stock configuration.
	local meta="${SDDM_THEME_DIR}/metadata.desktop"
	[[ -f "${meta}" ]] || return 1
	sed -i 's|^ConfigFile=.*|ConfigFile=configs/default.conf|' "${meta}"
	return 0
}

sddm_install_theme_files() {
	local src="${ASSET_DIR}/sddm/silent"
	if [[ ! -d "${src}" ]]; then
		ui_err "the bundled SilentSDDM theme is missing from the payload"
		return 1
	fi
	ui_step "installing the SilentSDDM theme"
	rm -rf "${SDDM_THEME_DIR}"
	install -d "${SDDM_THEME_DIR}"
	cp -a "${src}/." "${SDDM_THEME_DIR}/"
	sddm_pin_stock_config || return 1

	# The theme ships its own fonts (RedHatDisplay); the greeter needs them
	# installed system-wide, not just present in the theme directory.
	if [[ -d "${SDDM_THEME_DIR}/fonts" ]]; then
		install -d /usr/share/fonts/silent-sddm
		find "${SDDM_THEME_DIR}/fonts" -type f \( -name '*.otf' -o -name '*.ttf' \) \
			-exec cp -f {} /usr/share/fonts/silent-sddm/ \; 2>/dev/null || true
		if have fc-cache; then
			fc-cache -f /usr/share/fonts/silent-sddm >/dev/null 2>&1 || true
		fi
	fi

	# Make sure the sddm user can actually read everything.
	chmod -R a+rX "${SDDM_THEME_DIR}"
	ui_ok "theme installed: ${SDDM_THEME_DIR}"

	# Account avatar shown on the login screen.
	#
	# The greeter runs as the `sddm` system user, and a stock Debian home is
	# mode 0700, so it cannot open ~/.face.icon at all - writing only there
	# leaves the login screen with the generic placeholder. Install the same
	# image to every location a greeter may consult:
	#
	#   ~/.face, ~/.face.icon          accounts-service / SDDM convention
	#   /usr/share/sddm/faces/*.face.icon   SDDM's system-wide fallback
	local avatar_src="${ASSET_DIR}/user-avatar.jpg"
	if [[ -f "${avatar_src}" ]]; then
		local face="${HOME_DIR}/.face"
		install -m 644 "${avatar_src}" "${face}"
		install -m 644 "${avatar_src}" "${face}.icon"
		chown_user "${face}" 2>/dev/null || true
		chown_user "${face}.icon" 2>/dev/null || true
		register_file "${face}"
		register_file "${face}.icon"

		# System-wide copies, readable by the greeter regardless of home perms.
		local uname_s
		uname_s="$(id -un "${TARGET_USER}" 2>/dev/null || echo "${TARGET_USER}")"
		install -d -m 755 /usr/share/sddm/faces
		install -m 644 "${avatar_src}" \
			"/usr/share/sddm/faces/${uname_s}.face.icon"
		manifest_file "/usr/share/sddm/faces/${uname_s}.face.icon"
		ui_ok "login avatar installed for ${uname_s}"
	fi
	return 0
}

sddm_write_profile_plain() {
	# Minimal drop-in for greeters that cannot load SilentSDDM: still enable
	# the Sway session and a sane InputMethod, but no theme override.
	install -d "${SDDM_CONF_D}"
	if [[ -f "${SDDM_PROFILE}" ]]; then
		backup_path "${SDDM_PROFILE}"
	fi
	cat >"${SDDM_PROFILE}" <<EOF
# Generated by the i3 Everforest installer.
# Delete this file to revert SDDM to the distribution defaults.

[General]
InputMethod=qtvirtualkeyboard

[Users]
MaximumUid=65000
MinimumUid=1000
EOF
	chmod 644 "${SDDM_PROFILE}"
	register_file "${SDDM_PROFILE}"
	ui_ok "wrote ${SDDM_PROFILE} (stock greeter)"
	return 0
}

sddm_write_profile() {
	# A drop-in under /etc/sddm.conf.d/ is used instead of editing
	# /etc/sddm.conf, so the distribution's own file stays untouched and
	# uninstalling is a plain file removal.
	install -d "${SDDM_CONF_D}"
	if [[ -f "${SDDM_PROFILE}" ]]; then
		backup_path "${SDDM_PROFILE}"
	fi
	cat >"${SDDM_PROFILE}" <<EOF
# Generated by the i3 Everforest installer.
# Delete this file to revert SDDM to the distribution defaults.

[General]
InputMethod=qtvirtualkeyboard
GreeterEnvironment=QML2_IMPORT_PATH=${SDDM_THEME_DIR}/components/,QT_IM_MODULE=qtvirtualkeyboard

[Theme]
Current=${SDDM_THEME_NAME}

[X11]
# Start the greeter on the X server SDDM manages (the default, stated
# explicitly so a distro override cannot switch it to Wayland behind our back).
ServerPath=/usr/bin/X
# Hand the session the environment it needs; without this the greeter logs in
# a window manager that starts with a bare environment.
SessionCommand=/etc/sddm/Xsession
UserAuthFile=/var/run/sddm/xauth

[Users]
MaximumUid=65000
MinimumUid=1000
EOF
	chmod 644 "${SDDM_PROFILE}"
	register_file "${SDDM_PROFILE}"
	ui_ok "wrote ${SDDM_PROFILE}"
	return 0
}

sddm_write_session_launcher() {
	# The xsessions entry points at the same launcher the session component
	# writes; keep one copy so a greeter login and `startx i3` behave alike.
	if [[ -x "${SDDM_XSESSION_WRAPPER}" ]]; then
		ui_dim "session launcher already present: ${SDDM_XSESSION_WRAPPER}"
		return 0
	fi
	session_write_launcher
	return 0
}

sddm_enable_service() {
	ui_step "enabling SDDM as the default display manager"
	# A minimal install boots into multi-user.target; the greeter only
	# appears after switching the default target.
	systemctl set-default graphical.target >>"${LOG_FILE}" 2>&1 || {
		ui_warn "could not set graphical.target as the default"
	}

	# display-manager.service is a single alias: if another greeter (lightdm,
	# gdm3, ...) owns it, `systemctl enable sddm` refuses to overwrite it.
	# Point the alias at SDDM explicitly so SDDM really is the one that starts.
	local dm_link="/etc/systemd/system/display-manager.service"
	if [[ -L "${dm_link}" || -e "${dm_link}" ]]; then
		local target
		target="$(readlink -f "${dm_link}" 2>/dev/null || true)"
		if [[ "${target}" != */sddm.service ]]; then
			ui_dim "replacing the current display-manager.service (${target##*/})"
		fi
	fi
	ln -sfn /lib/systemd/system/sddm.service "${dm_link}" || {
		ui_warn "could not point display-manager.service at SDDM"
	}
	systemctl daemon-reload >>"${LOG_FILE}" 2>&1 || true
	systemctl enable sddm.service >>"${LOG_FILE}" 2>&1 || {
		ui_warn "could not enable sddm.service"
		return 1
	}
	# Debian's display-manager selection, so `service display-manager start`
	# and the boot order follow SDDM.
	if [[ -d /etc/X11 ]]; then
		printf '/usr/sbin/sddm\n' >/etc/X11/default-display-manager
		chmod 644 /etc/X11/default-display-manager
		register_file /etc/X11/default-display-manager
	fi
	ui_ok "SDDM enabled (graphical.target is now the default)"
	return 0
}

# ---------------------------------------------------------------------
#  pam_systemd is what creates the logind session for the greeter's login.
#  Without it there is no /run/user/<uid>, and the session comes up with a
#  missing session bus instead of a working desktop.
#  It is only a Recommends of sddm/systemd-sysv, so verify it explicitly and
#  repair it if an earlier run used --no-install-recommends.
# ---------------------------------------------------------------------
sddm_ensure_pam_systemd() {
	if [[ -f /usr/lib/x86_64-linux-gnu/security/pam_systemd.so ]] ||
		[[ -f /usr/lib/security/pam_systemd.so ]] ||
		[[ -f /lib/x86_64-linux-gnu/security/pam_systemd.so ]]; then
		return 0
	fi
	ui_warn "pam_systemd is missing - the session would log in to a black screen"
	ui_step "installing libpam-systemd"
	apt_update_once
	if apt-get install -y --no-install-recommends libpam-systemd >>"${LOG_FILE}" 2>&1; then
		manifest_pkg libpam-systemd
		ui_ok "libpam-systemd installed"
		return 0
	fi
	ui_err "could not install libpam-systemd; logging in may fail"
	return 1
}

sddm_version_string() {
	local v
	v="$(sddm --version 2>/dev/null | head -1)"
	[[ -n "${v}" ]] || v="$(apt-cache policy sddm 2>/dev/null | awk '/Installed:/{print $2}')"
	printf '%s' "${v:-unknown}"
}

sddm_theme_loadable() {
	# Actually ask the installed greeter to parse the theme. This is the only
	# reliable test: version numbers lie, and a theme that fails to load gives
	# the user a black login screen. `--test-mode` needs a display, so run it
	# headless under Xvfb when available and fall back to a QML syntax check.
	local theme="${SDDM_THEME_DIR}"
	local meta="${theme}/metadata.desktop"
	[[ -f "${meta}" ]] || return 1

	# 1. the theme's own ConfigFile must exist, or the greeter aborts
	local cfgfile
	cfgfile="$(awk -F= '/^ConfigFile=/{print $2; exit}' "${meta}" 2>/dev/null)"
	if [[ -n "${cfgfile}" && ! -f "${theme}/${cfgfile}" ]]; then
		ui_dim "  theme config missing: ${cfgfile}"
		return 1
	fi

	# 2. every QML import the theme uses must resolve to an installed module
	local -a imports=()
	mapfile -t imports < <(grep -rhoE '^import [A-Za-z0-9.]+' "${theme}" --include='*.qml' 2>/dev/null \
		| awk '{print $2}' | sort -u)
	local qmldir="/usr/lib/${DEB_HOST_MULTIARCH:-x86_64-linux-gnu}/qt6/qml"
	local mod missing=0
	for mod in "${imports[@]}"; do
		case "${mod}" in
			QtQuick|QtQml|QtMultimedia|QtQuick.*) : ;;
			SddmComponents)
				# provided by sddm itself
				if [[ ! -d "${qmldir}/SddmComponents" ]]; then
					ui_dim "  SddmComponents module not found"
					missing=1
				fi
				;;
			*)
				if [[ ! -d "${qmldir}/${mod//.//}" ]]; then
					ui_dim "  QML module not installed: ${mod}"
					missing=1
				fi
				;;
		esac
	done
	(( missing == 0 )) || return 1

	# 3. the greeter binary itself must exist
	if ! have sddm-greeter-qt6 && ! have sddm-greeter; then
		ui_dim "  no sddm greeter binary"
		return 1
	fi
	return 0
}

sddm_verify() {
	local ok=1
	if ! have sddm; then
		ui_err "sddm is not installed"; ok=0
	fi
	if ! have sddm-greeter-qt6; then
		ui_err "sddm-greeter-qt6 is missing"; ok=0
	fi
	# Only require the theme files when the profile actually selects the theme.
	local prof_theme
	prof_theme="$(awk -F= '/^\[Theme\]/{t=1;next} t&&/^Current=/{print $2;exit}' "${SDDM_PROFILE}" 2>/dev/null)"
	if [[ "${prof_theme}" == "${SDDM_THEME_NAME}" ]]; then
		if ! sddm_theme_ok; then
			ui_err "the theme is not readable by the sddm user"; ok=0
		fi
	fi

	if ! systemctl is-enabled sddm.service >/dev/null 2>&1; then
		ui_err "sddm.service is not enabled"; ok=0
	fi
	if [[ "$(systemctl get-default 2>/dev/null)" != "graphical.target" ]]; then
		ui_err "the default systemd target is not graphical.target"; ok=0
	fi
	if [[ ! -f "${SESSION_DIR}/${SESSION_FILE}" ]]; then
		ui_err "the i3 xsessions entry is missing"; ok=0
	fi
	if [[ ! -f /usr/lib/x86_64-linux-gnu/security/pam_systemd.so ]] &&
		[[ ! -f /usr/lib/security/pam_systemd.so ]]; then
		ui_err "pam_systemd is missing: login would land on a black screen"; ok=0
	fi
	if ((ok)); then
		if [[ "${prof_theme}" == "${SDDM_THEME_NAME}" ]]; then
			ui_ok "SDDM will show the SilentSDDM greeter and offer the i3 session"
		else
			ui_ok "SDDM will show its stock greeter and offer the i3 session"
		fi
	fi
	((ok))
}

sddm_install() {
	ui_hdr "Display manager (SDDM + SilentSDDM)"

	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then
		ui_dim "would install SDDM, the SilentSDDM theme and enable the greeter"
		return 0
	fi
	apt_install "display manager" "${PKGS_SDDM[@]}" || {
		ui_err "the SDDM packages could not be installed"
		return 1
	}

	# Remember what we found, so --uninstall can put it back. These files are
	# written once: re-running the installer must not overwrite the original
	# state with the state left by the previous run.
	if [[ ! -f "${STATE_DIR}/previous-display-manager" ]]; then
		if [[ -f /etc/X11/default-display-manager ]]; then
			cp -f /etc/X11/default-display-manager \
				"${STATE_DIR}/previous-display-manager" 2>/dev/null || true
		else
			: >"${STATE_DIR}/previous-display-manager"
		fi
	fi
	if [[ ! -f "${STATE_DIR}/previous-target" ]]; then
		systemctl get-default >"${STATE_DIR}/previous-target" 2>/dev/null || true
	fi
	# The display-manager.service symlink is the thing that actually decides
	# which greeter starts, so record its target as well.
	if [[ ! -f "${STATE_DIR}/previous-dm-link" ]]; then
		local prev_link
		prev_link="$(readlink -f /etc/systemd/system/display-manager.service 2>/dev/null || true)"
		printf '%s\n' "${prev_link}" >"${STATE_DIR}/previous-dm-link"
	fi

	# Debian 13 ships SDDM 0.21 built against Qt6, which is exactly what the
	# theme needs, so install it unconditionally.
	sddm_install_theme_files || return 1
	sddm_write_profile || return 1
	sddm_write_session_launcher || return 1

	# The greeter needs a session entry to show; write it even when the
	# separate "session" component was skipped.
	if [[ ! -f "${SESSION_DIR}/${SESSION_FILE}" ]]; then
		SESSION_FILE_OVERRIDE=1
		session_install >/dev/null 2>&1 || true
	fi

	sddm_enable_service
	sddm_ensure_pam_systemd || true
	ui_rule
	sddm_verify || ui_warn "SDDM is installed but some checks failed (see above)"
	return 0
}

# ---------------------------------------------------------------------
# 80-uninstall.sh
# ---------------------------------------------------------------------
# =====================================================================
#  Uninstall - restore the machine to its pre-install state
# ---------------------------------------------------------------------
#  Restoring backups runs FIRST, so a file that existed before this
#  script ever ran is never left deleted if something goes wrong.
# =====================================================================

uninstall_restore_backups() {
	local map="${STATE_DIR}/backup-map.tsv"
	if [[ ! -f "${map}" ]]; then
		ui_dim "no backups to restore"
		return 0
	fi
	local orig back n=0
	# Restore in two passes: every recorded original gets its backup back.
	while IFS=$'\t' read -r orig back; do
		[[ -n "${orig}" && -e "${back}" ]] || continue
		mkdir -p "$(dirname "${orig}")"
		rm -rf "${orig}"
		cp -a "${back}" "${orig}"
		ui_dim "restored ${orig}"
		n=$((n + 1))
	done <"${map}"
	((n == 0)) && ui_dim "no backups needed restoring"
	return 0
}

# Paths that existed before the install (recorded in the backup map).
uninstall_backed_up_paths() {
	local map="${STATE_DIR}/backup-map.tsv" p
	[[ -f "${map}" ]] || return 0
	while IFS=$'\t' read -r p _; do
		[[ -n "${p}" ]] && printf '%s\n' "${p}"
	done <"${map}"
}

uninstall_files() {
	[[ -f "${STATE_DIR}/installed-files.list" ]] || { ui_dim "no file list recorded"; return 0; }

	local -A restored=()
	local p
	while IFS= read -r p; do
		[[ -n "${p}" ]] && restored["${p}"]=1
	done < <(uninstall_backed_up_paths)

	local removed=0 skipped=0
	# Reverse order so nested paths are handled before their parents.
	while IFS= read -r p; do
		[[ -n "${p}" ]] || continue
		if [[ -n "${restored[${p}]:-}" ]]; then
			skipped=$((skipped + 1))
			continue
		fi
		if [[ -e "${p}" || -L "${p}" ]]; then
			rm -rf "${p}"
			removed=$((removed + 1))
		fi
	done < <(tac "${STATE_DIR}/installed-files.list")
	ui_dim "removed ${removed} file(s), kept ${skipped} restored from backup"
	return 0
}

uninstall_dirs() {
	local kind path n=0
	[[ -f "${MANIFEST}" ]] || return 0
	while IFS=$'\t' read -r kind path; do
		[[ "${kind}" == "dir" ]] || continue
		[[ -d "${path}" ]] || continue
		rm -rf "${path}"
		ui_dim "removed ${path}"
		n=$((n + 1))
	done <"${MANIFEST}"
	((n == 0)) && ui_dim "no directories to remove"
	return 0
}

uninstall_packages() {
	if [[ ${OPT_KEEP_PACKAGES} -eq 1 ]]; then
		ui_dim "keeping installed packages (--keep-packages)"
		return 0
	fi
	[[ -f "${MANIFEST}" ]] || return 0

	# Packages the script is responsible for, split by whether they existed
	# before it ran. The second list is the default target: removing something
	# the user already had would be surprising. --purge-everything extends the
	# removal to the whole list for a truly clean machine.
	local -a fresh=() everything=()
	local kind path
	while IFS=$'\t' read -r kind path; do
		[[ "${kind}" == "pkg" ]] || continue
		[[ -n "${path}" ]] || continue
		everything+=("${path}")
		if [[ -f "${STATE_DIR}/preinstalled-packages.txt" ]] &&
			grep -qxF "${path}" "${STATE_DIR}/preinstalled-packages.txt"; then
			continue
		fi
		fresh+=("${path}")
	done <"${MANIFEST}"

	local -a pkgs=()
	if [[ ${OPT_PURGE_EVERYTHING} -eq 1 ]]; then
		pkgs=("${everything[@]}")
	else
		pkgs=("${fresh[@]}")
	fi

	if [[ ${#pkgs[@]} -eq 0 ]]; then
		ui_dim "no packages to remove"
		if [[ ${#everything[@]} -gt 0 ]]; then
			ui_dim "  ${#everything[@]} package(s) were already present before the install;"
			ui_dim "  re-run with --purge-everything to remove them too"
		fi
		return 0
	fi

	# Filter to what is actually installed right now, so apt does not fail on
	# a package that is already gone.
	local -a real=()
	local p
	for p in "${pkgs[@]}"; do
		if dpkg-query -W -f='${Status}' "${p}" 2>/dev/null | grep -q "ok installed"; then
			real+=("${p}")
		fi
	done
	if [[ ${#real[@]} -eq 0 ]]; then
		ui_dim "no packages left to remove"
		return 0
	fi

	ui_step "removing ${#real[@]} package(s)"

	# Remove in batches and never let one refusal abort the rest: apt refuses a
	# whole transaction when a single package is protected (sudo, dbus and the
	# X server are common), which used to leave every package in place.
	local -a batch=()
	local failed=() removed=0
	for p in "${real[@]}"; do
		batch+=("${p}")
		# 20 at a time keeps the apt output readable and the retries cheap.
		if [[ ${#batch[@]} -ge 20 ]]; then
			if apt-get remove -y --purge -o Dpkg::Options::=--force-confdef \
				-o Dpkg::Options::=--force-confold "${batch[@]}" >>"${LOG_FILE}" 2>&1; then
				removed=$((removed + ${#batch[@]}))
			else
				failed+=("${batch[@]}")
			fi
			batch=()
		fi
	done
	if [[ ${#batch[@]} -gt 0 ]]; then
		if apt-get remove -y --purge -o Dpkg::Options::=--force-confdef \
			-o Dpkg::Options::=--force-confold "${batch[@]}" >>"${LOG_FILE}" 2>&1; then
			removed=$((removed + ${#batch[@]}))
		else
			failed+=("${batch[@]}")
		fi
	fi

	# Retry the failures one by one, so a single protected package only blocks
	# itself.
	if [[ ${#failed[@]} -gt 0 ]]; then
		ui_dim "retrying ${#failed[@]} package(s) individually"
		local f
		for f in "${failed[@]}"; do
			if apt-get remove -y --purge -o Dpkg::Options::=--force-confdef \
				-o Dpkg::Options::=--force-confold "${f}" >>"${LOG_FILE}" 2>&1; then
				removed=$((removed + 1))
			else
				ui_dim "  could not remove ${f} (protected or a dependency)"
			fi
		done
	fi

	# Dependencies that came in with them and are no longer needed.
	apt-get autoremove -y --purge >>"${LOG_FILE}" 2>&1 || true
	ui_ok "package removal finished (${removed} requested)"
	return 0
}

uninstall_bash_block() {
	local rc="${HOME_DIR}/.bashrc"
	[[ -f "${rc}" ]] || return 0
	if ! grep -qF "# >>> i3-everforest >>>" "${rc}" 2>/dev/null; then
		return 0
	fi
	local tmp
	tmp="$(mktemp)"
	awk '
		/# >>> i3-everforest >>>/ { skip = 1; next }
		/# <<< i3-everforest <<</ { skip = 0; next }
		!skip { print }
	' "${rc}" >"${tmp}"
	install -m 644 "${tmp}" "${rc}"
	rm -f "${tmp}"
	chown "${TARGET_USER}:${TARGET_GROUP}" "${rc}" 2>/dev/null || true
	ui_dim "removed the i3-everforest block from ${rc}"
	return 0
}

uninstall_tidy_dirs() {
	local d
	for d in \
		"${HOME_DIR}/.config/i3" \
		"${HOME_DIR}/.config/i3-everforest" \
		"${HOME_DIR}/.config/kitty" \
		"${HOME_DIR}/.config/foot" \
		"${HOME_DIR}/.config/rofi" \
		"${HOME_DIR}/.config/dunst" \
		"${HOME_DIR}/.config/picom" \
		"${HOME_DIR}/.config/btop/themes"; do
		[[ -d "${d}" ]] || continue
		rmdir "${d}" 2>/dev/null && ui_dim "removed empty ${d}"
	done
	rm -f /usr/share/backgrounds/i3-everforest.jpg 2>/dev/null
	# A stale Wayland entry left behind by an earlier sway install would keep
	# offering a session that no longer exists.
	rm -f /usr/share/wayland-sessions/sway-everforest.desktop 2>/dev/null || true
	sddm_uninstall_restore 2>/dev/null || true
	return 0
}

# ---------------------------------------------------------------------
#  Put the display manager back the way we found it.
# ---------------------------------------------------------------------
sddm_uninstall_restore() {
	[[ ${SDDM_UNINSTALL_DONE:-0} -eq 1 ]] && return 0
	[[ -f "${SDDM_PROFILE}" ]] || return 0
	ui_step "reverting the display manager changes"

	rm -f "${SDDM_PROFILE}" 2>/dev/null && ui_dim "removed ${SDDM_PROFILE}"

	# restore the previous default target, if we changed it
	if [[ -f "${STATE_DIR}/previous-target" ]]; then
		local prev
		prev="$(cat "${STATE_DIR}/previous-target" 2>/dev/null)"
		if [[ -n "${prev}" && "${prev}" != "graphical.target" ]]; then
			systemctl set-default "${prev}" >>"${LOG_FILE}" 2>&1 &&
				ui_dim "default target restored to ${prev}"
		fi
	fi

	# Restore the display-manager.service symlink first: it is what decides
	# which greeter starts. fall back to the Debian selector file.
	if [[ -f "${STATE_DIR}/previous-dm-link" ]]; then
		local prev_link
		prev_link="$(cat "${STATE_DIR}/previous-dm-link" 2>/dev/null)"
		if [[ -n "${prev_link}" && -e "${prev_link}" ]]; then
			ln -sfn "${prev_link}" /etc/systemd/system/display-manager.service 2>/dev/null &&
				ui_dim "display-manager.service restored to ${prev_link##*/}"
		else
			rm -f /etc/systemd/system/display-manager.service 2>/dev/null
			ui_dim "display-manager.service alias removed"
		fi
		systemctl daemon-reload >>"${LOG_FILE}" 2>&1 || true
	fi

	if [[ -f "${STATE_DIR}/previous-display-manager" ]]; then
		local pdm
		pdm="$(cat "${STATE_DIR}/previous-display-manager" 2>/dev/null | tr -d '[:space:]')"
		if [[ -n "${pdm}" ]]; then
			printf '%s\n' "${pdm}" >/etc/X11/default-display-manager 2>/dev/null || true
			ui_dim "default-display-manager restored to ${pdm}"
		else
			rm -f /etc/X11/default-display-manager 2>/dev/null
			ui_dim "default-display-manager removed (there was none before)"
		fi
	fi
	SDDM_UNINSTALL_DONE=1
	return 0
}

do_uninstall() {
	preflight
	ui_hdr "Uninstall"
	ui_warn "this removes the i3/everforest desktop installed by this script"
	ui_dim "state: ${STATE_DIR}"
	ui_dim "packages are kept unless you drop --keep-packages"

	if [[ ${OPT_YES} -eq 0 && ${INTERACTIVE} -eq 1 ]]; then
		printf '  %sContinue? [y/N]%s ' "${C_FG}" "${C_RESET}"
		local a=""
		IFS= read -r a || a="n"
		if [[ ! "${a}" =~ ^[yY] ]]; then
			ui_dim "cancelled"
			exit 0
		fi
	fi

	# 1. put every pre-existing file back
	uninstall_restore_backups
	# 2. remove files that this script created
	uninstall_files
	# 3. remove directories it created
	uninstall_dirs
	# 4. strip the bash block (restored in step 1: do it again, harmlessly)
	uninstall_bash_block
	# 5. tidy empty directories it may have created
	uninstall_tidy_dirs
	# 6. optionally remove packages
	uninstall_packages

	ui_ok "uninstalled"
	if [[ ${INTERACTIVE} -eq 1 ]]; then
		printf '  %sAlso delete the log and backup directory (%s)? [y/N]%s ' \
			"${C_FG}" "${STATE_DIR}" "${C_RESET}"
		local a=""
		IFS= read -r a || a="n"
		if [[ "${a}" =~ ^[yY] ]]; then
			rm -rf "${STATE_DIR}"
			ui_dim "removed ${STATE_DIR}"
		else
			ui_dim "kept ${STATE_DIR} (delete it manually when you are sure)"
		fi
	fi
	return 0
}

# ---------------------------------------------------------------------
# 85-payload.sh
# ---------------------------------------------------------------------
# =====================================================================
#  Payload: embedded assets (icons, GTK theme, wallpaper)
# ---------------------------------------------------------------------
#  Everything the look depends on ships inside this file, so the
#  installer works on a machine with no network at all. The blobs live
#  after PAYLOAD_MARKER at the end of the script as base64 blocks:
#
#     @@asset icons.tar.xz.b64
#     <base64 ...>
#     @@end
#
#  `--extract-assets DIR` writes them out for inspection.
# =====================================================================
PAYLOAD_MARKER="__I3_EVERFOREST_PAYLOAD_BELOW__"

assets_unpack_from_self() {
	local dir="$1"
	mkdir -p "${dir}"
	# Skip the first line: the marker itself is matched exactly.
	awk -v out="${dir}" -v marker="${PAYLOAD_MARKER}" '
		BEGIN { inpay = 0; name = "" }
		inpay == 0 {
			line = $0
			sub(/^#[[:space:]]*/, "", line)
			if (line == marker) inpay = 1
			next
		}
		/^@@asset / { name = $2; file = out "/" name; next }
		/^@@end/    { if (name != "") close(file); name = ""; next }
		name != ""  { print $0 >> file }
	' "${SELF}"

	local f base
	for f in "${dir}"/*.b64; do
		[[ -e "${f}" ]] || continue
		base="${f%.b64}"
		if base64 -d "${f}" >"${base}" 2>/dev/null; then
			rm -f "${f}"
		else
			ui_warn "could not decode $(basename "${f}")"
			rm -f "${f}" "${base}"
		fi
	done

	# Expand the archives in place.
	if [[ -f "${dir}/icons.tar.xz" ]]; then
		mkdir -p "${dir}/icons"
		tar -xJf "${dir}/icons.tar.xz" -C "${dir}/icons" 2>/dev/null || ui_warn "icon payload is damaged"
	fi
	if [[ -f "${dir}/gtk-theme.tar.xz" ]]; then
		mkdir -p "${dir}/gtk-theme"
		tar -xJf "${dir}/gtk-theme.tar.xz" -C "${dir}/gtk-theme" 2>/dev/null || ui_warn "theme payload is damaged"
	fi
	if [[ -f "${dir}/bar.tar.xz" ]]; then
		mkdir -p "${dir}/bar"
		tar -xJf "${dir}/bar.tar.xz" -C "${dir}" 2>/dev/null || ui_warn "the bar payload is damaged"
	fi
	if [[ -f "${dir}/bar-c.tar.xz" ]]; then
		tar -xJf "${dir}/bar-c.tar.xz" -C "${dir}" 2>/dev/null || ui_warn "the bar source payload is damaged"
	fi
	if [[ -f "${dir}/fonts.tar.xz" ]]; then
		mkdir -p "${dir}/fonts"
		tar -xJf "${dir}/fonts.tar.xz" -C "${dir}/fonts" 2>/dev/null || ui_warn "the font payload is damaged"
	fi
	if [[ -f "${dir}/sddm-theme.tar.xz" ]]; then
		mkdir -p "${dir}/sddm"
		tar -xJf "${dir}/sddm-theme.tar.xz" -C "${dir}/sddm" 2>/dev/null || ui_warn "the SDDM theme payload is damaged"
	fi
	if [[ -f "${dir}/user-avatar.jpg" ]]; then
		: # already a plain file in the payload
	fi
	if [[ -f "${dir}/wallpaper.jpg.xz" ]]; then
		xz -dc "${dir}/wallpaper.jpg.xz" >"${dir}/wallpaper.jpg" 2>/dev/null || ui_warn "wallpaper payload is damaged"
		rm -f "${dir}/wallpaper.jpg.xz"
	fi
	return 0
}

assets_prepare() {
	if [[ -n "${ASSET_DIR}" ]]; then return 0; fi
	if [[ -n "${SCRIPT_ASSET_DIR:-}" && -d "${SCRIPT_ASSET_DIR}" ]]; then
		ASSET_DIR="${SCRIPT_ASSET_DIR}"
		return 0
	fi
	local dir="${TMPWORK}/assets"
	ui_step "unpacking the bundled assets"
	assets_unpack_from_self "${dir}" || return 1
	ASSET_DIR="${dir}"
	local n=0
	if [[ -d "${dir}/icons/${ICON_NAME}" ]]; then n=$((n + 1)); fi
	if [[ -d "${dir}/gtk-theme/${THEME_NAME}" ]]; then n=$((n + 1)); fi
	if [[ -s "${dir}/wallpaper.jpg" ]]; then n=$((n + 1)); fi
	if [[ -d "${dir}/sddm/silent" ]]; then n=$((n + 1)); fi
	if [[ -d "${dir}/fonts" ]]; then n=$((n + 1)); fi
	if [[ -d "${dir}/bar" ]]; then n=$((n + 1)); fi
	((n > 0)) || { ui_warn "the embedded payload is empty"; return 1; }
	ui_ok "assets ready (${n}/6)"
	return 0
}

extract_assets() {
	local dir="${1:-./i3-everforest-assets}"
	mkdir -p "${dir}"
	TMPWORK="${TMPWORK:-${dir}}"
	LOG_FILE=""
	printf '  unpacking the embedded payload into %s\n' "${dir}"
	assets_unpack_from_self "${dir}"
	# the archives themselves are kept, so they can be inspected
	printf '  contents:\n'
	find "${dir}" -maxdepth 2 -mindepth 1 -printf '    %p\n' 2>/dev/null | sort | head -20
	printf '  done\n'
}

# ---------------------------------------------------------------------
# 90-main.sh
# ---------------------------------------------------------------------
# =====================================================================
#  Main: argument parsing, orchestration, summary
# =====================================================================

usage() {
	cat <<EOF
${PROG} ${VERSION} - i3 Everforest rice for Debian 13 (trixie, X11)

USAGE
  sudo ./$(basename "${SELF}")                 menu: install / reinstall / uninstall
  sudo ./$(basename "${SELF}") --yes           install everything, no questions
  sudo ./$(basename "${SELF}") --dry-run       preview only, change nothing

COMPONENTS
  core      i3, C bar, kitty, rofi, dunst, feh, picom, i3lock
  apps      pcmanfm, btop, pavucontrol, flameshot, imv, nomacs, mpv, cliphist
  theme     GTK2/3/4 Everforest-Dark-BL-LB + libadwaita override
  icons     Material-Black-Lime-Numix-FLAT
  wall      wallpaper from wallhaven (4xxw9z), 1920x1080
  dots      i3, bar, kitty, rofi, dunst, i3lock, btop configs
  session   /usr/share/xsessions entry for i3
  sddm      SDDM display manager + SilentSDDM theme (graphical login)
  shell     the 'mf' fetch block + Everforest bash prompt

OPTIONS
  -y, --yes               non-interactive: install everything with defaults
      --user NAME         desktop user (default: the sudo invoker)
  -n, --dry-run           show what would be done, change nothing
      --no-tui            never ask questions (same as a non-interactive run)
      --opacity LEVEL     bar transparency: solid (default), soft, clear
      --no-apt-update     do not refresh the package lists

  Skip one component:
      --no-core  --no-apps  --no-theme  --no-icons
      --no-wallpaper  --no-dots  --no-session  --no-sddm  --no-shell

  Install one component only:
      --only-dots  --only-theme  --only-wallpaper  --only-shell  --only-sddm

  Remove / inspect:
  -u, --uninstall         remove everything this script installed
      --keep-packages     with --uninstall: leave the apt packages alone
      --purge-everything  with --uninstall: also remove packages that were
                          already installed before this script ran
      --extract-assets D  unpack the bundled assets into D and exit
      --list              print the component list and exit
  -h, --help              this help
  -v, --version           print the version

NOTES
  Run it as root (sudo). The desktop user is the account that invoked sudo,
  or whatever you pass with --user.

  An interactive run starts by asking what you want to do:
      1 Install     pick components and install them
      2 Reinstall   re-select everything, then install again
      3 Uninstall   remove everything this script installed
  Pass --yes, --uninstall or --dry-run to skip that question.

  The installer is idempotent: running it twice does not duplicate anything,
  and every file it overwrites is backed up under
  ~/.local/state/i3-everforest/backups/<timestamp>/.
  Everything the look needs (theme, icons, wallpaper) is embedded, so it
  also works with no network at all.
  After installing, reboot: SDDM shows the SilentSDDM greeter, and picking
  "i3 (Everforest)" logs straight into the desktop.
  On a machine with no display manager at all, choose the "sddm" component.
  This is an X11 desktop: there is no Wayland session, and no compositor
  effects beyond what picom provides.

KEYBINDINGS AFTER INSTALL
  Mod = Super/Windows key
  Mod+Return terminal     Mod+d launcher        Mod+e files
  Mod+Shift+Return btop   Mod+Shift+E power     Mod+Shift+C reload
  Mod+1..8 workspaces     Mod+Escape lock       Print screenshot
  Mod+F fullscreen        Mod+W tabbed          Mod+R resize mode
  Mod+Shift+R restart     Mod+Shift+Print region screenshot
EOF
}

list_components() {
	cat <<EOF
core     i3 GTK-bar kitty rofi dunst feh picom i3lock xorg
apps     pcmanfm gvfs btop fastfetch pavucontrol network-manager-gnome
         imv nomacs mpv flameshot swappy cliphist
theme    ${THEME_NAME} (GTK2/3/4) + gtk-3.0/gtk-4.0/libadwaita settings
icons    ${ICON_NAME}
wall     wallhaven 4xxw9z -> ~/.local/share/${SHARE_DIR_NAME}/wallpaper.jpg
dots     i3, C bar, kitty, rofi, dunst, i3lock, btop
session  /usr/share/xsessions/${SESSION_FILE}
sddm     SDDM + SilentSDDM theme -> ${SDDM_THEME_DIR}, boots to graphical.target
shell    /usr/local/bin/mf + Everforest bash prompt
EOF
}

parse_args() {
	local -a ONLY_LIST=()
	while [[ $# -gt 0 ]]; do
		case "$1" in
		-y | --yes) OPT_YES=1 ;;
		-u | --uninstall) OPT_UNINSTALL=1 ;;
		-n | --dry-run) OPT_DRY_RUN=1 ;;
		--keep-packages) OPT_KEEP_PACKAGES=1 ;;
		--purge-everything) OPT_PURGE_EVERYTHING=1 ;;
		--no-apt-update) OPT_APT_UPDATE=0 ;;
		--user) shift; OPT_USER="${1:-}" ;;
		--user=*) OPT_USER="${1#*=}" ;;
		--no-tui) OPT_ASSUME_TUI=off ;;
		--no-apps) APPS=0 ;;
		--no-theme) GTK_THEME=0 ;;
		--no-icons) ICONS=0 ;;
		--no-wallpaper) WALLPAPER=0 ;;
		--no-dots) DOTS=0 ;;
		--no-session) SESSION=0 ;;
		--no-shell) SHELLFX=0 ;;
		--no-sddm) SDDM=0 ;;
		--opacity) shift; BAR_OPACITY="${1:-solid}"; OPT_OPACITY_GIVEN=1 ;;
		--opacity=*) BAR_OPACITY="${1#*=}"; OPT_OPACITY_GIVEN=1 ;;
		--only-sddm) ONLY_LIST+=("sddm") ;;
		--no-core) CORE=0 ;;
		--only-dots) ONLY_LIST+=("dots") ;;
		--only-theme) ONLY_LIST+=("theme") ;;
		--only-shell) ONLY_LIST+=("shell") ;;
		--only-wallpaper) ONLY_LIST+=("wallpaper") ;;
		--extract-assets) shift; DEST="${1:-./i3-everforest-assets}"; KEEP_TMP=1; extract_assets "${DEST}"; exit 0 ;;
		--list) list_components; exit 0 ;;
		-h | --help) usage; exit 0 ;;
		-v | --version) echo "${PROG} ${VERSION}"; exit 0 ;;
		*) die "unknown option '$1' (try --help)" ;;
		esac
		shift
	done

	# Apply --only-* selections in one pass: every component not named is
	# switched off. This makes the flags combinable (`--only-dots --only-shell`)
	# instead of letting the last one win.
	if [[ ${#ONLY_LIST[@]} -gt 0 ]]; then
		local c
		local want_dots=0 want_shell=0 want_theme=0 want_wall=0 want_sddm=0
		for c in "${ONLY_LIST[@]}"; do
			case "${c}" in
			dots) want_dots=1 ;;
			shell) want_shell=1 ;;
			theme) want_theme=1 ;;
			wallpaper) want_wall=1 ;;
			sddm) want_sddm=1 ;;
			esac
		done
		CORE=0; APPS=0; SESSION=0
		GTK_THEME=${want_theme}
		ICONS=${want_theme}       # the theme component also carries the icons
		WALLPAPER=${want_wall}
		DOTS=${want_dots}
		SHELLFX=${want_shell}
		SDDM=${want_sddm}
	fi

	case "${BAR_OPACITY}" in
	solid|soft|clear) : ;;
	*) die "invalid --opacity '${BAR_OPACITY}' (use solid, soft or clear)" ;;
	esac
}


snapshot_packages() {
	# Remember what was already installed, so --uninstall only removes
	# the packages that this script added.
	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then return 0; fi
	mkdir -p "${STATE_DIR}"
	dpkg-query -W -f='${Package}\n' 2>/dev/null | sort -u >"${STATE_DIR}/preinstalled-packages.txt"
}

install_flow() {
	preflight
	snapshot_packages

	tui_summary_preview

	ui_hdr "Installing"
	ui_line "target user : ${TARGET_USER}"
	ui_line "components  : $(selected_list)"
	ui_rule

	if [[ ${CORE} -eq 1 || ${APPS} -eq 1 || ${ICONS} -eq 1 || ${GTK_THEME} -eq 1 || ${SDDM} -eq 1 ]]; then
		install_packages
	fi

	# Optional third-page software is independent of the component selection.
	install_optional_software || true

	if [[ ${GTK_THEME} -eq 1 || ${ICONS} -eq 1 || ${WALLPAPER} -eq 1 || ${SDDM} -eq 1 || ${DOTS} -eq 1 ]]; then
		assets_prepare || ui_warn "continuing without bundled assets"
	fi

	if [[ ${DOTS} -eq 1 ]]; then
		fonts_install || true
		write_stats || true
		write_volume || true
		write_brightness || true
		write_sysinfo || true
		write_network || true
		write_input || true
		write_bar_actions || true
		write_picker || true
		write_lock_and_power || true
	fi

	if [[ ${GTK_THEME} -eq 1 ]]; then theme_install; fi
	if [[ ${ICONS} -eq 1 ]]; then
		icons_install || true
		icons_install_overrides || true
	fi
	if [[ ${WALLPAPER} -eq 1 ]]; then wallpaper_install || true; fi
	if [[ ${DOTS} -eq 1 ]]; then
		if [[ ${OPT_DRY_RUN} -eq 1 ]]; then ui_dim "would write the configuration files"; else dotfiles_install; fi
	fi
	if [[ ${SESSION} -eq 1 ]]; then
		if [[ ${OPT_DRY_RUN} -eq 1 ]]; then ui_dim "would write ${SESSION_DIR}/${SESSION_FILE}"; else session_install; fi
	fi
	if [[ ${SDDM} -eq 1 ]]; then sddm_install || ui_warn "the display manager could not be configured"; fi
	if [[ ${SHELLFX} -eq 1 ]]; then
		if [[ ${OPT_DRY_RUN} -eq 1 ]]; then
			ui_dim "would install /usr/local/bin/mf, the bar helpers and the bash prompt"
		else
			write_mf; write_stats; write_volume; write_brightness; write_sysinfo
			write_network; write_input; write_bar_actions; write_picker
			write_lock_and_power
			write_bash_extras
		fi
	fi

	if [[ ${GTK_THEME} -eq 1 || ${ICONS} -eq 1 ]]; then
		if [[ ${OPT_DRY_RUN} -eq 1 ]]; then
			ui_dim "would apply the GTK settings"
		else
			gtk_apply_settings
			theme_guard_install || true
		fi
	fi

	if [[ ${OPT_DRY_RUN} -ne 1 && ${SDDM} -ne 1 ]]; then session_enable_dm || true; fi

	if [[ ${OPT_DRY_RUN} -ne 1 ]]; then
		validate_install || ui_warn "configuration validation reported problems (see above)"
	fi

	finalize_manifest
	print_summary
}

selected_list() {
	local out=()
	if [[ ${CORE} -eq 1 ]]; then out+=("core"); fi
	if [[ ${APPS} -eq 1 ]]; then out+=("apps"); fi
	if [[ ${GTK_THEME} -eq 1 ]]; then out+=("theme"); fi
	if [[ ${ICONS} -eq 1 ]]; then out+=("icons"); fi
	if [[ ${WALLPAPER} -eq 1 ]]; then out+=("wallpaper"); fi
	if [[ ${DOTS} -eq 1 ]]; then out+=("dotfiles"); fi
	if [[ ${SESSION} -eq 1 ]]; then out+=("session"); fi
	if [[ ${SHELLFX} -eq 1 ]]; then out+=("shell"); fi
	if [[ ${SDDM} -eq 1 ]]; then out+=("sddm"); fi
	printf '%s' "${out[*]:-none}"
}

tui_summary_preview() {
	ui_hdr "Plan"
	local k
	for k in "${OPT_KEYS[@]}"; do
		if [[ "$(opt_state "${k}")" == "x" ]]; then
			ui_ok "$(opt_short "${k}")"
		fi
	done
	ui_rule
}

finalize_manifest() {
	[[ -f "${MANIFEST}.new" ]] || return 0
	if [[ -f "${MANIFEST}" ]]; then
		# keep the older entries: an install may be repeated
		cat "${MANIFEST}" "${MANIFEST}.new" | sort -u >"${MANIFEST}.tmp"
		mv "${MANIFEST}.tmp" "${MANIFEST}"
	else
		mv "${MANIFEST}.new" "${MANIFEST}"
	fi
	chown_user "${STATE_DIR}"
}

# ---------------------------------------------------------------------
#  Validation: prove the generated configuration actually loads
# ---------------------------------------------------------------------
validate_install() {
	ui_hdr "Validation"
	local ok=1

	# `i3 -C` parses the config without starting the window manager. The exit
	# status is the verdict; i3 prints its own diagnostics to stderr.
	if [[ -f "${HOME_DIR}/.config/i3/config" ]] && have i3; then
		local i3log="${TMPWORK}/i3-check.log"
		if runuser -u "${TARGET_USER}" -- env DISPLAY= HOME="${HOME_DIR}" \
			i3 -C -c "${HOME_DIR}/.config/i3/config" >"${i3log}" 2>&1; then
			ui_ok "i3 config is valid"
		else
			local real_errors
			real_errors="$(grep -iE 'error|invalid|expected|could not|unknown' "${i3log}" 2>/dev/null | head -8)"
			ui_err "i3 reported configuration problems:"
			printf '%s\n' "${real_errors:-$(head -5 "${i3log}" 2>/dev/null)}" | sed 's/^/      /'
			ok=0
		fi
	fi

	# The bar is a compiled C binary driven by a JSON description. Two things
	# can break it, and both are checkable without a display: the binary must
	# be a runnable ELF, and the JSON must parse and name the modules it lists.
	if [[ -f "/usr/local/bin/i3-everforest-bar" ]]; then
		local barprog="/usr/local/bin/i3-everforest-bar"
		if [[ -x "${barprog}" ]] && head -c 4 "${barprog}" | grep -q $'\x7fELF'; then
			ui_ok "bar binary is runnable"
		else
			ui_err "the bar is not an executable binary"
			ok=0
		fi
	fi

	if [[ -f "${HOME_DIR}/.config/i3-everforest/bar.json" ]]; then
		local barcfg="${HOME_DIR}/.config/i3-everforest/bar.json"
		local barcheck
		barcheck="$(runuser -u "${TARGET_USER}" -- python3 - "${barcfg}" <<'PYCHK' 2>&1
import json, sys
path = sys.argv[1]
cfg = json.load(open(path))
mods = cfg.get("modules", {})
listed = []
for side in ("modules-left", "modules-center", "modules-right"):
    listed += cfg.get(side, [])
missing = [m for m in listed if m not in mods]
if missing:
    print("modules listed but not defined: " + ", ".join(missing))
    sys.exit(1)
# Every module must declare a type the bar understands.
known = {"workspaces", "window", "separator", "custom", "graph"}
bad = [m for m, d in mods.items() if d.get("type") not in known]
if bad:
    print("unknown module type: " + ", ".join(bad))
    sys.exit(1)
print("ok")
PYCHK
)"
		if [[ "${barcheck}" == "ok" ]]; then
			ui_ok "bar layout is valid"
		else
			ui_err "bar layout is invalid:"
			printf '%s\n' "${barcheck}" | head -5 | sed 's/^/      /'
			ok=0
		fi
	fi

	# rofi validates its own theme with `-dump-theme`, but that needs an X
	# connection; without one it fails on "Failed to open display", which is
	# an environment problem, not a theme problem. So: ask rofi when a display
	# answers, and otherwise check the structure its parser requires.
	if [[ -f "${HOME_DIR}/.config/rofi/i3-everforest.rasi" ]]; then
		local rasi="${HOME_DIR}/.config/rofi/i3-everforest.rasi"
		if have rofi && display_reachable; then
			local rofiout="${TMPWORK}/rofi-check.log"
			runuser -u "${TARGET_USER}" -- env HOME="${HOME_DIR}" \
				DISPLAY="${DISPLAY}" XAUTHORITY="${XAUTHORITY:-}" \
				rofi -theme "${rasi}" -dump-theme >"${rofiout}" 2>&1 || true
			# Only a real parse complaint counts; locale and display warnings
			# are noise from the environment.
			local rproblem
			rproblem="$(grep -iE 'error|invalid|unknown|expected|unexpected|deprecat' "${rofiout}" 2>/dev/null |
				grep -viE 'failed to set locale|failed to open display|connection has error' || true)"
			if [[ -n "${rproblem}" ]]; then
				ui_warn "rofi reported theme problems:"
				printf '%s\n' "${rproblem}" | head -5 | sed 's/^/      /'
				ok=0
			else
				ui_ok "rofi theme is valid"
			fi
		else
			local nb no
			nb="$(tr -cd '}' <"${rasi}" | wc -c)"
			no="$(tr -cd '{' <"${rasi}" | wc -c)"
			if [[ "${nb}" -ne "${no}" ]]; then
				ui_err "rofi theme has unbalanced braces (${no} open, ${nb} close)"
				ok=0
			elif ! grep -qE '^\*[[:space:]]*\{' "${rasi}"; then
				ui_err "rofi theme is missing its default * { } block"
				ok=0
			elif ! grep -qE '^window[[:space:]]*\{' "${rasi}"; then
				ui_err "rofi theme is missing its window { } block"
				ok=0
			else
				ui_ok "rofi theme is well formed"
			fi
		fi
	fi

	if [[ -f "${HOME_DIR}/.config/kitty/kitty.toml" ]] && have kitty; then
		if runuser -u "${TARGET_USER}" -- env XDG_RUNTIME_DIR=/tmp \
			kitty --config-file "${HOME_DIR}/.config/kitty/kitty.toml" --version >/dev/null 2>&1; then
			ui_ok "kitty config is valid"
		else
			ui_warn "kitty could not read its configuration"
			ok=0
		fi
	fi

	if [[ ${ICONS} -eq 1 ]]; then
		if [[ -f "/usr/share/icons/${ICON_NAME}/index.theme" ]]; then
			ui_ok "icon theme present: ${ICON_NAME}"
		else
			ui_err "icon theme missing"; ok=0
		fi
	fi
	if [[ ${GTK_THEME} -eq 1 ]]; then
		if [[ -f "/usr/share/themes/${THEME_NAME}/gtk-3.0/gtk.css" ]]; then
			ui_ok "gtk theme present: ${THEME_NAME}"
		else
			ui_err "gtk theme missing"; ok=0
		fi
	fi
	((ok)) || return 1
	return 0
}

print_summary() {
	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then
		ui_hdr "Dry run finished"
		ui_ok "nothing was changed - this was a preview"
		printf '\n'
		ui_dim "re-run without -n/--dry-run to install"
		printf '\n'
		return 0
	fi
	# Reload the bar so settings that are read at startup (the transparency
	# preset, bar.json layout) take effect without a logout.
	if [[ ${OPT_DRY_RUN} -eq 0 ]] && command -v ps >/dev/null 2>&1; then
		if ps -eo args= 2>/dev/null | grep -qx "python3 /usr/local/bin/i3-everforest-bar"; then
			ps -eo pid,args --no-headers 2>/dev/null |
				awk '$0 ~ /^ *[0-9]+ python3 \/usr\/local\/bin\/i3-everforest-bar$/ {print $1}' |
				while read -r pid; do kill "${pid}" 2>/dev/null || true; done
			# The watchdog brings it back within a few seconds.
			ui_dim "restarting the bar so the new settings apply"
		fi
	fi

	ui_hdr "Done"
	ui_ok "i3 Everforest is installed for user ${TARGET_USER}"
	printf '\n'
	ui_line "Log out and choose ${C_BOLD}i3 (Everforest)${C_RESET} at the login screen,"
	ui_line "or start it from a TTY with:  ${C_LIME}startx i3${C_RESET}"
	printf '\n'
	ui_line "Keybindings:"
	ui_dim "  Mod+Return  terminal        Mod+d        application launcher"
	ui_dim "  Mod+e       files           Mod+Shift+E  power menu"
	ui_dim "  Mod+1..8    workspaces      Mod+Shift+C  reload i3"
	ui_dim "  Mod+Escape  lock screen     Print        screenshot"
	printf '\n'
	ui_line "Files:"
	ui_dim "  configs   ${HOME_DIR}/.config/{i3,i3-everforest,kitty,rofi,dunst}"
	ui_dim "  wallpaper ${HOME_DIR}/.local/share/${SHARE_DIR_NAME}/wallpaper.jpg"
	ui_dim "  manifest  ${MANIFEST}"
	ui_dim "  log       ${LOG_FILE}"
	ui_dim "  backups   ${BACKUP_DIR}"
	printf '\n'
	ui_line "Undo everything with:  ${C_LIME}sudo $(basename "${SELF}") --uninstall${C_RESET}"
	printf '\n'
}

main() {
	setup_colors
	LOG_FILE=""
	parse_args "$@"
	tui_detect
	tui_size

	# Scratch space for downloads/builds
	TMPWORK="$(mktemp -d /tmp/i3-everforest.XXXXXX)"
	chmod 755 "${TMPWORK}"

	# Which directory holds pre-extracted assets (development runs)
	SCRIPT_ASSET_DIR=""
	if [[ -d "$(dirname "${SELF}")/assets" ]]; then
		SCRIPT_ASSET_DIR="$(dirname "${SELF}")/assets"
	fi

	if [[ ${OPT_UNINSTALL} -eq 1 ]]; then
		do_uninstall
		exit 0
	fi

	if [[ ${INTERACTIVE} -eq 1 ]]; then
		# Resolve the user up front so the menu and summary can show the
		# real home directory, state directory and log path.
		resolve_target_user

		# First question is the intent: install, reinstall or remove.
		tui_action_menu
		case "${TUI_ACTION}" in
		uninstall)
			do_uninstall
			exit 0
			;;
		reinstall)
			# Start from a clean slate so nothing silently stays skipped
			# from a previous partial run.
			CORE=1 APPS=1 GTK_THEME=1 ICONS=1 WALLPAPER=1 \
				DOTS=1 SESSION=1 SHELLFX=1 SDDM=1
			;;
		esac

		tui_menu
		# Third page: optional software. Returning 2 means "back", which
		# reopens the component page instead of losing the choices.
		local soft_rc
		while true; do
			tui_soft_menu
			soft_rc=$?
			[[ ${soft_rc} -eq 2 ]] && { tui_menu; continue; }
			break
		done
		tui_summary || exit 0
	else
		INTERACTIVE=0
	fi

	if [[ ${OPT_DRY_RUN} -eq 1 ]]; then
		ui_hdr "Dry run"
		ui_warn "no changes will be made"
	fi

	if [[ ${INTERACTIVE} -eq 1 ]]; then
		install_flow
	else
		# non-interactive: still print the plan for the log
		install_flow
	fi
}

main "$@"
# The asset payload is appended below this line by build.sh.
exit 0


